`if_exists="replace"` drops and recreates the table. Use a SQL `UPDATE` instead, matching rows by `id`:

```python
import pandas as pd
from sqlalchemy import MetaData, Table, bindparam, select, update

def updateexisting_data(self, df: pd.DataFrame) -> int:
    if df.empty:
        return 0

    with self.engine.begin() as conn:
        table = Table(
            self.table_name,
            MetaData(),
            autoload_with=conn,
        )

        existing_ids = conn.execute(select(table.c.id)).scalars().all()
        matching_rows = df.loc[df["id"].isin(existing_ids)]

        columns_to_update = [col for col in df.columns if col != "id"]

        if matching_rows.empty or not columns_to_update:
            return 0

        statement = (
            update(table)
            .where(table.c.id == bindparam("_match_id"))
            .values({
                col: bindparam(f"_value_{i}")
                for i, col in enumerate(columns_to_update)
            })
        )

        parameters = [
            {
                "_match_id": row["id"],
                **{
                    f"_value_{i}": row[col]
                    for i, col in enumerate(columns_to_update)
                },
            }
            for row in matching_rows.to_dict(orient="records")
        ]

        conn.execute(statement, parameters)
        return len(parameters)
```

This updates only existing IDs, leaves other rows untouched, and does not insert new IDs. Only non-`id` columns present in the DataFrame are updated. The return value counts matching DataFrame rows processed.

