Below is a complete Rust application using:

- **egui/eframe** for the GUI.
- **rfd** for native folder-selection dialogs.
- **notify** for filesystem monitoring.

It displays the three selected folders, provides **Start** and **Stop** buttons, and logs newly created files or files moved into the input folder.

The output and done folders are stored and displayed; this example does not process or move files.

## 1. Create the project

```bash
cargo new folder_monitor
cd folder_monitor
```

Replace `Cargo.toml` with:

```toml
[package]
name = "folder_monitor"
version = "0.1.0"
edition = "2021"

[dependencies]
eframe = "0.29"
rfd = "0.15"
notify = "6.1"
```

## 2. Application code

Replace `src/main.rs` with:

```rust
use std::{
    collections::VecDeque,
    path::PathBuf,
    sync::mpsc::{self, Receiver},
    time::{SystemTime, UNIX_EPOCH},
};

use eframe::egui;
use notify::{
    event::RenameMode, Event, EventKind, RecommendedWatcher, RecursiveMode, Watcher,
};

const MAX_LOG_ENTRIES: usize = 1_000;

#[derive(Default)]
struct FolderMonitorApp {
    input_folder: Option<PathBuf>,
    output_folder: Option<PathBuf>,
    done_folder: Option<PathBuf>,

    // The watcher must remain alive while monitoring.
    watcher: Option<RecommendedWatcher>,
    events: Option<Receiver<notify::Result<Event>>>,

    log: VecDeque<String>,
}

impl FolderMonitorApp {
    fn add_log(&mut self, message: impl AsRef<str>) {
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        self.log
            .push_back(format!("[{timestamp}] {}", message.as_ref()));

        while self.log.len() > MAX_LOG_ENTRIES {
            self.log.pop_front();
        }
    }

    fn folder_picker(
        ui: &mut egui::Ui,
        button_text: &str,
        selected_folder: &mut Option<PathBuf>,
    ) {
        ui.horizontal(|ui| {
            if ui.button(button_text).clicked() {
                let mut dialog = rfd::FileDialog::new()
                    .set_title(button_text);

                if let Some(current_folder) = selected_folder.as_ref() {
                    dialog = dialog.set_directory(current_folder);
                }

                if let Some(folder) = dialog.pick_folder() {
                    *selected_folder = Some(folder);
                }
            }

            match selected_folder.as_ref() {
                Some(folder) => {
                    ui.label(folder.display().to_string());
                }
                None => {
                    ui.weak("No folder selected");
                }
            }
        });
    }

    fn start_monitoring(&mut self, ctx: &egui::Context) {
        // Validate all three selections before starting.
        let validation_error = [
            ("input", self.input_folder.as_ref()),
            ("output", self.output_folder.as_ref()),
            ("done", self.done_folder.as_ref()),
        ]
        .into_iter()
        .find_map(|(name, folder)| match folder {
            None => Some(format!("Please select the {name} folder.")),
            Some(path) if !path.is_dir() => Some(format!(
                "The {name} folder does not exist or is not a directory: {}",
                path.display()
            )),
            _ => None,
        });

        if let Some(error) = validation_error {
            self.add_log(error);
            return;
        }

        let input_folder = self.input_folder.clone().unwrap();

        let (sender, receiver) = mpsc::channel::<notify::Result<Event>>();
        let repaint_context = ctx.clone();

        // notify invokes this callback outside the GUI update function.
        // Send events to the GUI rather than modifying GUI state here.
        let watcher_result = notify::recommended_watcher(
            move |event: notify::Result<Event>| {
                if sender.send(event).is_ok() {
                    repaint_context.request_repaint();
                }
            },
        );

        let mut watcher = match watcher_result {
            Ok(watcher) => watcher,
            Err(error) => {
                self.add_log(format!("Could not create filesystem watcher: {error}"));
                return;
            }
        };

        // Watch only the selected folder, not its subfolders.
        if let Err(error) =
            watcher.watch(&input_folder, RecursiveMode::NonRecursive)
        {
            self.add_log(format!(
                "Could not monitor {}: {error}",
                input_folder.display()
            ));
            return;
        }

        self.events = Some(receiver);
        self.watcher = Some(watcher);

        self.add_log(format!(
            "Started monitoring: {}",
            input_folder.display()
        ));
    }

    fn stop_monitoring(&mut self) {
        // Dropping the watcher stops filesystem monitoring.
        self.watcher = None;
        self.events = None;
        self.add_log("Monitoring stopped.");
    }

    fn handle_event(&mut self, event: Event) {
        // A file may arrive by creation or by being renamed/moved into
        // the watched folder.
        let arrival_event = matches!(
            &event.kind,
            EventKind::Create(_)
                | EventKind::Modify(notify::event::ModifyKind::Name(
                    RenameMode::To | RenameMode::Both | RenameMode::Any
                ))
        );

        if !arrival_event {
            return;
        }

        let event_description = format!("{:?}", event.kind);

        // For a paired rename event, paths are [source, destination].
        // We only want to report the destination.
        let paths = if matches!(
            &event.kind,
            EventKind::Modify(notify::event::ModifyKind::Name(
                RenameMode::Both
            ))
        ) {
            event.paths.into_iter().last().into_iter().collect()
        } else {
            event.paths
        };

        for path in paths {
            // Skip directories and paths that have already disappeared.
            let metadata = match std::fs::metadata(&path) {
                Ok(metadata) if metadata.is_file() => metadata,
                _ => continue,
            };

            self.add_log(format!(
                "File arrived | Event: {} | Path: {} | Current size: {} bytes",
                event_description,
                path.display(),
                metadata.len()
            ));
        }
    }

    fn receive_events(&mut self) {
        // try_recv never waits, so monitoring does not block the GUI
        // while there are no events.
        //
        // Limit work per frame so a large event burst does not monopolize
        // the GUI thread.
        for _ in 0..200 {
            let message = self
                .events
                .as_ref()
                .and_then(|receiver| receiver.try_recv().ok());

            match message {
                Some(Ok(event)) => self.handle_event(event),
                Some(Err(error)) => {
                    self.add_log(format!("Filesystem watcher error: {error}"));
                }
                None => break,
            }
        }
    }
}

impl eframe::App for FolderMonitorApp {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.receive_events();

        let monitoring = self.watcher.is_some();

        // Also periodically repaint to drain any remaining queued events.
        if monitoring {
            ctx.request_repaint_after(std::time::Duration::from_millis(100));
        }

        egui::CentralPanel::default().show(ctx, |ui| {
            ui.heading("Folder Monitor");
            ui.add_space(12.0);

            // Prevent changing the displayed configuration while watching.
            ui.add_enabled_ui(!monitoring, |ui| {
