                    ui,
                    "Select input folder",
                    &mut self.input_folder,
                );

                Self::folder_picker(
                    ui,
                    "Select output folder",
                    &mut self.output_folder,
                );

                Self::folder_picker(
                    ui,
                    "Select done folder",
                    &mut self.done_folder,
                );
            });

            ui.add_space(12.0);

            ui.horizontal(|ui| {
                if ui
                    .add_enabled(!monitoring, egui::Button::new("Start"))
                    .clicked()
                {
