Your existing `ratio_1` checks **buy on Nobitex → sell on Bitpin**. You can also check the reverse direction, accounting for fees, available balances, and order-book liquidity.

Below is a conservative replacement. It defaults to **dry-run** because your snippet does not show Bitpin’s order-placement API or either exchange’s fill-status API.

**Assumptions to verify:**
- Nobitex prices are in **rials**, and Bitpin prices are in **tomans**, matching your existing `* 10`.
- Asset values are **available balances**, not total balances including locked funds.
- Order-book levels expose their USDT quantity as `.amount`; change `level_amount()` if necessary.
- Fee rates, minimum trade size, and amount precision below are **examples**, not verified exchange settings.

```python
import logging
import time
from concurrent.futures import ThreadPoolExecutor
from decimal import Decimal, ROUND_DOWN

from apis.bitpin import Bitpin
from apis.nobitex import NobitexAPIClient
from logging_config import setup_logging


logger = logging.getLogger("main")

D = Decimal

DRY_RUN = True

# Set True only after implementing submit_bp_order() below.
BP_ORDER_ADAPTER_READY = False

POLL_SECONDS = 5
MAX_TRADE_USDT = D("100")

# EXAMPLES: replace with actual exchange requirements.
MIN_TRADE_USDT = D("5")
AMOUNT_STEP = D("0.01")
FEES = {
    "nb": D("0.001"),  # Nobitex taker fee
    "bp": D("0.001"),  # Bitpin taker fee
}

# Required estimated profit after fees: 0.2%.
MIN_NET_RETURN = D("0.002")

# Use only part of displayed liquidity / available balances.
DEPTH_UTILIZATION = D("0.80")
BALANCE_UTILIZATION = D("0.99")

# Normalize prices and quote balances into rials.
RIAL_MULTIPLIER = {
    "nb": D("1"),
    "bp": D("10"),
}

# Change these keys to match get_current_assets().
QUOTE_ASSET_KEY = {
    "nb": "RLS",
    "bp": "IRT",
}


def decimal(value):
    return D(str(value))


def level_amount(level):
    """Must return the level's quantity in USDT, not quote currency."""
    return decimal(level.amount)


def available_balance(assets, symbol):
    """
    Must return AVAILABLE / unlocked funds.

    If your wrapper returns nested balances, adapt this function,
    e.g. assets[symbol]["available"].
    """
    return decimal(assets[symbol])


def round_amount(amount):
    return (
        (amount / AMOUNT_STEP).to_integral_value(rounding=ROUND_DOWN)
        * AMOUNT_STEP
    )


def find_opportunity(buy_exchange, sell_exchange, books, assets):
    ask = books[buy_exchange].get_best_ask()
    bid = books[sell_exchange].get_best_bid()

    if ask is None or bid is None:
        return None

    buy_native_price = decimal(ask.price)
    sell_native_price = decimal(bid.price)

    buy_price = buy_native_price * RIAL_MULTIPLIER[buy_exchange]
    sell_price = sell_native_price * RIAL_MULTIPLIER[sell_exchange]

    if buy_price <= 0 or sell_price <= 0:
        return None

    # Assumes fees are charged in quote currency.
    cost_per_usdt = buy_price * (1 + FEES[buy_exchange])
    proceeds_per_usdt = sell_price * (1 - FEES[sell_exchange])

    net_return = proceeds_per_usdt / cost_per_usdt - 1

    logger.info(
        "%s -> %s: estimated net return %.4f%%",
        buy_exchange,
        sell_exchange,
        float(net_return * 100),
    )

    if net_return < MIN_NET_RETURN:
        return None

    buy_quote_balance_rials = (
        available_balance(
            assets[buy_exchange],
            QUOTE_ASSET_KEY[buy_exchange],
        )
        * RIAL_MULTIPLIER[buy_exchange]
    )

    sell_usdt_balance = available_balance(
        assets[sell_exchange], "USDT"
    )

    amount = round_amount(min(
        MAX_TRADE_USDT,
        level_amount(ask) * DEPTH_UTILIZATION,
        level_amount(bid) * DEPTH_UTILIZATION,
        buy_quote_balance_rials
        * BALANCE_UTILIZATION
        / cost_per_usdt,
        sell_usdt_balance * BALANCE_UTILIZATION,
    ))

    if amount < MIN_TRADE_USDT:
        return None

    # Add each exchange's minimum-notional validation here if required.
    return {
        "buy_exchange": buy_exchange,
        "sell_exchange": sell_exchange,
        "amount": amount,
        "buy_price": buy_native_price,
        "sell_price": sell_native_price,
        "net_return": net_return,
        "estimated_profit_rials": (
            proceeds_per_usdt - cost_per_usdt
        ) * amount,
    }


def submit_bp_order(client, side, amount, price):
    """
    Implement using your Bitpin wrapper's actual method signature.

    Submit a LIMIT order on USDT-IRT at the supplied native price.
    Prefer IOC if supported, but partial fills still require reconciliation.

    Do not enable BP_ORDER_ADAPTER_READY until this is implemented.
    """
    raise NotImplementedError(
        "Bitpin order-placement signature was not provided."
    )


def submit_order(clients, exchange, side, amount, price):
    if exchange == "nb":
        return clients["nb"].place_order(
            side,
            execution="limit",
            src_currency="usdt",
            dst_currency="rls",
            amount=format(amount, "f"),
            price=format(price, "f"),
        )

    if exchange == "bp":
        return submit_bp_order(
            clients["bp"], side, amount, price
        )

    raise ValueError(f"Unknown exchange: {exchange}")


def execute_opportunity(clients, opportunity):
    logger.info(
        "%sBUY %s / SELL %s | amount=%s USDT | "
        "buy_price=%s | sell_price=%s | "
        "estimated_profit=%s rials",
        "[DRY RUN] " if DRY_RUN else "",
        opportunity["buy_exchange"],
        opportunity["sell_exchange"],
        opportunity["amount"],
        opportunity["buy_price"],
        opportunity["sell_price"],
        opportunity["estimated_profit_rials"],
    )

    if DRY_RUN:
        return

    # Submit both legs concurrently to reduce, not eliminate, timing risk.
    legs = {
        "buy": (
            opportunity["buy_exchange"],
            opportunity["buy_price"],
        ),
        "sell": (
            opportunity["sell_exchange"],
            opportunity["sell_price"],
        ),
    }

    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = {
            side: executor.submit(
                submit_order,
                clients,
                exchange,
                side,
                opportunity["amount"],
                price,
            )
            for side, (exchange, price) in legs.items()
        }

        for side, future in futures.items():
            try:
                response = future.result()
                logger.warning(
                    "%s submission response: %r", side, response
                )
            except Exception:
                # A timeout does NOT prove the exchange rejected the order.
                logger.exception(
                    "%s submission failed or has unknown status. "
                    "Do not retry blindly.",
                    side,
                )

    # Acknowledgement is not a fill. Without status/cancel adapters,
    # continuing could accumulate unmatched exposure or resting orders.
    logger.critical(
        "Trading stopped after live submission. Check BOTH exchanges, "
        "cancel remaining orders, and reconcile actual fills before restart."
    )
    raise SystemExit(1)


def main():
    setup_logging()

    if not DRY_RUN and not BP_ORDER_ADAPTER_READY:
        raise RuntimeError(
            "Implement the Bitpin order adapter before enabling live trading."
        )

    clients = {
        "nb": NobitexAPIClient(),
        "bp": Bitpin(),
    }

    with ThreadPoolExecutor(max_workers=4) as executor:
        while True:
            try:
                # Fetch concurrently to reduce snapshot timing differences.
                book_futures = {
                    exchange: executor.submit(
                        client.get_orderbook, pair="USDT-IRT"
                    )
                    for exchange, client in clients.items()
                }

                asset_futures = {
                    exchange: executor.submit(client.get_current_assets)
                    for exchange, client in clients.items()
                }

                books = {
                    exchange: future.result()
                    for exchange, future in book_futures.items()
                }
                assets = {
                    exchange: future.result()
                    for exchange, future in asset_futures.items()
                }

                opportunities = []

                for buy_exchange, sell_exchange in [
                    ("nb", "bp"),
                    ("bp", "nb"),
                ]:
                    opportunity = find_opportunity(
                        buy_exchange,
                        sell_exchange,
                        books,
                        assets,
                    )
                    if opportunity:
                        opportunities.append(opportunity)

                if opportunities:
                    best = max(
                        opportunities,
                        key=lambda item: item["estimated_profit_rials"],
                    )
                    execute_opportunity(clients, best)

            except Exception:
                logger.exception("Arbitrage scan failed")

            time.sleep(POLL_SECONDS)


if __name__ == "__main__":
    main()
```

**Important:** this uses pre-funded inventory: quote currency on the buying exchange and USDT on the selling exchange. It does not transfer funds or rebalance inventory. Marketable limit orders can partially fill or remain open, so the live path deliberately stops after one pair of submissions.

To make it run unattended, share Bitpin’s `place_order()` signature and both clients’ order-status/cancellation methods. Those are needed to reconcile fills and handle an unmatched leg safely.

