참고로 이 정도의 연습 문제에는 `int`로도 충분하지만, **큰 정수 금액을 처리하려고 `BigInteger`를 사용한 것도 올바른 선택**입니다. 기능상 반드시 수정해야 할 부분은 없습니다.

`RangeSlider` prevents the start thumb from passing the end thumb, but it **allows both thumbs to have the same value**. To prevent that, enforce a minimum gap—for your slider, one step is `0.5f` (30 minutes).

Use the **value-based overload** and clamp the thumb being moved in `onValueChange`, instead of correcting the state afterward in `snapshotFlow`. Updating state from an observer can compete with the slider’s own drag updates.

```kotlin
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MycanRangeSlider(
    modifier: Modifier,
    onValuesChange: (ClosedFloatingPointRange<Float>) -> Unit,
    defaultTimeRange: ClosedFloatingPointRange<Float>,
    enabled: Boolean,
    isScrolling: Boolean = false
) {
    val allowedRange = 7f..18f
    val stepSize = 0.5f
    val minGap = stepSize
    val steps = (
        (allowedRange.endInclusive - allowedRange.start) / stepSize
    ).roundToInt() - 1

    fun snap(value: Float): Float {
        val step = ((value - allowedRange.start) / stepSize).roundToInt()
        return (allowedRange.start + step * stepSize)
            .coerceIn(allowedRange.start, allowedRange.endInclusive)
    }

    var selectedRange by remember {
        // Ensure the initial selection also satisfies the minimum gap.
        val start = snap(defaultTimeRange.start).coerceIn(
            allowedRange.start,
            allowedRange.endInclusive - minGap
        )
        val end = snap(defaultTimeRange.endInclusive).coerceIn(
            start + minGap,
            allowedRange.endInclusive
        )

        mutableStateOf(start..end)
    }

    RangeSlider(
        modifier = modifier,
        value = selectedRange,
        onValueChange = { proposed ->
            val old = selectedRange
            val proposedStart = snap(proposed.start)
            val proposedEnd = snap(proposed.endInclusive)

            val next = if (proposedStart != old.start) {
                // Start thumb moved: leave the end thumb in place.
                proposedStart.coerceIn(
                    allowedRange.start,
                    old.endInclusive - minGap
                )..old.endInclusive
            } else {
                // End thumb moved: leave the start thumb in place.
                old.start..proposedEnd.coerceIn(
                    old.start + minGap,
                    allowedRange.endInclusive
                )
            }

            if (next != old) {
                selectedRange = next
                onValuesChange(next)
            }
        },
        enabled = enabled,
        valueRange = allowedRange,
        steps = steps
    )
}
```

You can keep your existing thumb and color customization on the value-based overload where supported by your Material 3 version.

The key invariant is:

```kotlin
end - start >= 0.5f
```

Clamping only the moving endpoint keeps the other endpoint stable and prevents an equal start/end selection. Note that this prevents **equal values**, not necessarily visual overlap between large thumb drawings.

Below is a controlled autocomplete `Input` with:

- Case-insensitive **prefix matching**.
- A dropdown that disappears when nothing matches.
- Required, option-membership, and custom validation.
- Keyboard navigation, accessible combobox attributes, and IME support.
- Indexed searching and virtualized rendering for large option lists.

It uses one dependency for virtualization:

```bash
npm install @tanstack/react-virtual
```

## `Input.tsx`

```tsx
import {
  useCallback,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  defaultRangeExtractor,
  useVirtualizer,
} from "@tanstack/react-virtual";

import "./Input.css";

type InputProps = {
  label: string;
  options: readonly string[];

  value: string;
  onChange: (value: string) => void;
  onSelect?: (value: string) => void;

  id?: string;
  name?: string;
  placeholder?: string;
  required?: boolean;
  disabled?: boolean;
  readOnly?: boolean;

  /** When false, nonempty values must match an option. */
  allowCustomValue?: boolean;

  /** Return an error message, or null if valid. */
  validate?: (value: string) => string | null;
};

type Entry = {
  label: string;
  key: string;
};

type ActiveOption = {
  source: readonly Entry[];
  query: string;
  index: number;
};

const ROW_HEIGHT = 40;
const MAX_VISIBLE_ROWS = 7;

function normalize(value: string): string {
  return value.trim().normalize("NFKC").toLowerCase();
}

/** First index satisfying a monotonic predicate. */
function lowerBound(
  items: readonly Entry[],
  predicate: (entry: Entry) => boolean,
): number {
  let low = 0;
  let high = items.length;

  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);

    if (predicate(items[middle])) {
      high = middle;
    } else {
      low = middle + 1;
    }
  }

  return low;
}

function findPrefixRange(
  entries: readonly Entry[],
  query: string,
): [number, number] {
  if (!query) return [0, 0];

  const start = lowerBound(entries, (entry) => entry.key >= query);

  // All strings with this prefix are contiguous in the sorted index.
  const end = lowerBound(
    entries,
    (entry) => entry.key >= query && !entry.key.startsWith(query),
  );

  return [start, end];
}

export function Input({
  label,
  options,
  value,
  onChange,
  onSelect,
  id,
  name,
  placeholder,
  required = false,
  disabled = false,
  readOnly = false,
  allowCustomValue = false,
  validate,
}: InputProps) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const listId = `${inputId}-list`;
  const errorId = `${inputId}-error`;

  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const composingRef = useRef(false);

  const [open, setOpen] = useState(false);
  const [composing, setComposing] = useState(false);
  const [touched, setTouched] = useState(false);
  const [active, setActive] = useState<ActiveOption | null>(null);

  // Build this only when options change. Blank options are ignored;
  // normalized duplicates keep their first supplied label.
  const { entries, keys } = useMemo(() => {
    const unique = new Map<string, string>();

    for (const option of options) {
      const key = normalize(option);

      if (key && !unique.has(key)) {
        unique.set(key, option);
      }
    }

    const entries: Entry[] = Array.from(
      unique,
      ([key, label]) => ({ key, label }),
    );

    // Use the same ordering as the binary-search comparisons.
    entries.sort((a, b) =>
      a.key < b.key ? -1 : a.key > b.key ? 1 : 0,
    );

    return {
      entries,
      keys: new Set(unique.keys()),
    };
  }, [options]);

  const query = normalize(value);

  const [start, end] = useMemo(
    () => findPrefixRange(entries, query),
    [entries, query],
  );

  const matchCount = end - start;

  const visible =
    open &&
    !disabled &&
    !readOnly &&
    !composing &&
    matchCount > 0;

  // An active index belongs to a particular query and option snapshot.
  // This prevents stale selections when either changes.
  const activeIndex =
    active?.source === entries &&
    active.query === query &&
    active.index >= 0 &&
    active.index < matchCount
      ? active.index
      : -1;

  const error = useMemo(() => {
    if (disabled || readOnly) return null;

    if (!query) {
      if (required) return "This field is required.";
    } else if (!allowCustomValue && !keys.has(query)) {
      return "Choose a value from the available options.";
    }

    return validate?.(value) ?? null;
  }, [
    disabled,
    readOnly,
    query,
    required,
    allowCustomValue,
    keys,
    validate,
    value,
  ]);

  // Validate on blur or an attempted form submission, then update live.
  // Avoid displaying a transient error during IME composition.
  const showError = touched && !composing && Boolean(error);

  // Integrate with native <form> validation as well as visual validation.
  useLayoutEffect(() => {
    inputRef.current?.setCustomValidity(error ?? "");
  }, [error]);

  const rangeExtractor = useCallback(
    (range: Parameters<typeof defaultRangeExtractor>[0]) => {
      const indexes = defaultRangeExtractor(range);

      // aria-activedescendant must reference a mounted option, even
      // during the frame before scrolling to that option.
      if (activeIndex >= 0 && !indexes.includes(activeIndex)) {
        indexes.push(activeIndex);
        indexes.sort((a, b) => a - b);
      }

      return indexes;
    },
    [activeIndex],
  );

  const virtualizer = useVirtualizer({
    count: visible ? matchCount : 0,
    getScrollElement: () => listRef.current,
    estimateSize: () => ROW_HEIGHT,
    overscan: 5,
    rangeExtractor,
  });

  useLayoutEffect(() => {
    if (visible) virtualizer.scrollToOffset(0);
  }, [visible, query, entries, virtualizer]);

  useLayoutEffect(() => {
    if (visible && activeIndex >= 0) {
      virtualizer.scrollToIndex(activeIndex, { align: "auto" });
    }
  }, [visible, activeIndex, virtualizer]);

  function highlight(index: number) {
    setActive({ source: entries, query, index });
  }

  function select(index: number) {
    const entry = entries[start + index];
    if (!entry || disabled || readOnly) return;

    onChange(entry.label);
    onSelect?.(entry.label);
    setTouched(true);
    setActive(null);

    // Restore focus for touch or other pointer interactions that
    // focused an option. Close after focus, since focus opens the list.
    inputRef.current?.focus();
    setOpen(false);
  }

  return (
    <div
      className="autocomplete"
      onBlur={(event) => {
        const nextTarget = event.relatedTarget;

        // Moving focus to an option is not leaving the component.
        if (
          nextTarget instanceof Node &&
          event.currentTarget.contains(nextTarget)
        ) {
          return;
        }

        setTouched(true);
        setOpen(false);
        setActive(null);
      }}
    >
      <label className="autocomplete__label" htmlFor={inputId}>
        {label}
        {required && <span aria-hidden="true"> *</span>}
      </label>

      <div className="autocomplete__control">
        <input
          ref={inputRef}
          id={inputId}
          name={name}
          type="text"
          role="combobox"
          className="autocomplete__input"
          value={value}
          placeholder={placeholder}
          required={required}
          disabled={disabled}
          readOnly={readOnly}
          autoComplete="off"
          spellCheck={false}
          aria-autocomplete="list"
          aria-haspopup="listbox"
          aria-expanded={visible}
          aria-controls={visible ? listId : undefined}
          aria-activedescendant={
            visible && activeIndex >= 0
              ? `${listId}-option-${start + activeIndex}`
              : undefined
          }
          aria-invalid={showError || undefined}
          aria-describedby={showError ? errorId : undefined}
          onFocus={() => {
            if (!disabled && !readOnly) setOpen(true);
          }}
          onClick={() => {
            if (!disabled && !readOnly) setOpen(true);
          }}
          onChange={(event) => {
            onChange(event.target.value);
            setOpen(true);
            setActive(null);
          }}
          onInvalid={() => setTouched(true)}
          onCompositionStart={() => {
            composingRef.current = true;
            setComposing(true);
            setActive(null);
          }}
          onCompositionEnd={() => {
            composingRef.current = false;
            setComposing(false);
            setOpen(true);
          }}
          onKeyDown={(event) => {
            if (
              disabled ||
              readOnly ||
              composingRef.current ||
              event.nativeEvent.isComposing ||
              event.ctrlKey ||
              event.metaKey ||
              event.altKey
            ) {
              return;
            }

            if (event.key === "ArrowDown" || event.key === "ArrowUp") {
              if (!matchCount) return;

              event.preventDefault();
              setOpen(true);

              const current = visible ? activeIndex : -1;

              if (event.key === "ArrowDown") {
                highlight(
                  current < 0 ? 0 : Math.min(current + 1, matchCount - 1),
                );
              } else {
                highlight(
                  current < 0 ? matchCount - 1 : Math.max(current - 1, 0),
                );
              }
            } else if (
              event.key === "Enter" &&
              visible &&
              activeIndex >= 0
            ) {
              event.preventDefault();
              select(activeIndex);
            } else if (event.key === "Escape" && open) {
              event.preventDefault();
              event.stopPropagation();
              setOpen(false);
              setActive(null);
            } else if (event.key === "Tab") {
              // Preserve normal tab navigation; don't select implicitly.
              setOpen(false);
              setActive(null);
            }
          }}
        />

        {visible && (
          <div
            ref={listRef}
            id={listId}
            role="listbox"
            aria-label={`${label} suggestions`}
            className="autocomplete__list"
            style={{
              height:
                Math.min(matchCount, MAX_VISIBLE_ROWS) * ROW_HEIGHT,
            }}
          >
            <div
              role="presentation"
              style={{
                height: virtualizer.getTotalSize(),
                position: "relative",
              }}
            >
              {virtualizer.getVirtualItems().map((row) => {
                const entry = entries[start + row.index];
                const highlighted = row.index === activeIndex;

                return (
                  <div
                    key={entry.key}
                    id={`${listId}-option-${start + row.index}`}
                    role="option"
                    tabIndex={-1}
                    aria-selected={highlighted}
                    aria-posinset={row.index + 1}
                    aria-setsize={matchCount}
                    className="autocomplete__option"
                    data-active={highlighted || undefined}
                    title={entry.label}
                    style={{
                      position: "absolute",
                      top: 0,
                      left: 0,
                      width: "100%",
                      height: ROW_HEIGHT,
                      transform: `translateY(${row.start}px)`,
                    }}
                    onMouseDown={(event) => {
                      // Keep input focus during mouse selection.
                      // Do not prevent pointerdown: touch scrolling
                      // should remain possible.
                      event.preventDefault();
                    }}
                    onClick={() => select(row.index)}
                  >
                    {entry.label}
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {showError && (
        <p id={errorId} className="autocomplete__error" role="alert">
          {error}
        </p>
      )}
    </div>
  );
}
```

