Save this as `ltr_configurator.py` and run it with Python. Relevance labels must be integers from **0 to 30**, with larger values meaning more relevant.

```python
import importlib.util
import logging
import os
import warnings
from datetime import datetime
from pathlib import Path

import joblib
import numpy as np
import pandas as pd
from scipy import sparse
from sklearn.compose import ColumnTransformer
from sklearn.feature_extraction.text import CountVectorizer
from sklearn.impute import SimpleImputer
from sklearn.metrics import ndcg_score
from sklearn.model_selection import GroupShuffleSplit
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import (
    MinMaxScaler,
    OneHotEncoder,
    StandardScaler,
)


LOG_FILENAME = (
    f"ltr_configurator_{datetime.now().strftime('%Y%m%d')}.log"
)

logging.basicConfig(
    filename=LOG_FILENAME,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

LOGGER = logging.getLogger(__name__)

RANDOM_STATE = 42
MODEL_FILENAME = "ltr_models.joblib"


def clean_path(value):
    return Path(str(value).strip().strip('"').strip("'")).expanduser()


def make_one_hot_encoder():
    # Compatibility with older and newer scikit-learn releases.
    try:
        return OneHotEncoder(
            handle_unknown="ignore",
            sparse_output=True,
            dtype=np.float32,
        )
    except TypeError:
        return OneHotEncoder(
            handle_unknown="ignore",
            sparse=True,
            dtype=np.float32,
        )


def prepare_feature_frame(dataset, predictor_columns, column_types):
    """Deterministic conversion only; no statistics are learned here."""
    missing = [c for c in predictor_columns if c not in dataset.columns]
    if missing:
        raise ValueError(f"Missing predictor columns: {missing}")

    frame = pd.DataFrame(index=dataset.index)

    for index, column in enumerate(predictor_columns):
        name = f"feature_{index}"
        kind = column_types[column]
        values = dataset[column]

        if kind == "numeric":
            numeric = pd.to_numeric(values, errors="coerce")
            numeric = numeric.replace([np.inf, -np.inf], np.nan)
            frame[name] = numeric.astype(float)

        elif kind == "categorical":
            frame[name] = (
                values.astype("string")
                .fillna("__MISSING__")
                .astype(str)
            )

        elif kind == "text":
            text = values.astype("string").fillna("").str.strip()
            frame[name] = text.mask(text.eq(""), "__EMPTY__").astype(str)

        elif kind == "datetime":
            dates = pd.to_datetime(values, errors="coerce", utc=True)

            # Fixed-origin timestamps do not depend on the other rows.
            epoch = pd.Timestamp("1970-01-01", tz="UTC")
            frame[f"{name}_days"] = (
                (dates - epoch).dt.total_seconds() / 86400.0
            )
            frame[f"{name}_month"] = dates.dt.month.astype(float)
            frame[f"{name}_day"] = dates.dt.day.astype(float)
            frame[f"{name}_weekday"] = dates.dt.dayofweek.astype(float)
            frame[f"{name}_hour"] = dates.dt.hour.astype(float)

        else:
            raise ValueError(f"Unsupported column type: {kind}")

    return frame


def build_preprocessor(
    predictor_columns,
    column_types,
    normalization,
    ngram_range,
    max_features,
):
    numeric_columns = []
    categorical_columns = []
    text_columns = []

    for index, column in enumerate(predictor_columns):
        name = f"feature_{index}"
        kind = column_types[column]

        if kind == "numeric":
            numeric_columns.append(name)

        elif kind == "datetime":
            numeric_columns.extend(
                [
                    f"{name}_days",
                    f"{name}_month",
                    f"{name}_day",
                    f"{name}_weekday",
                    f"{name}_hour",
                ]
            )

        elif kind == "categorical":
            categorical_columns.append(name)

        elif kind == "text":
            text_columns.append(name)

    transformers = []

    if numeric_columns:
        numeric_steps = [
            (
                "imputer",
                SimpleImputer(strategy="constant", fill_value=0),
            )
        ]

        if normalization == "standard":
            numeric_steps.append(("scaler", StandardScaler()))
        elif normalization == "minmax":
            numeric_steps.append(("scaler", MinMaxScaler()))

        transformers.append(
            ("numeric", Pipeline(numeric_steps), numeric_columns)
        )

    if categorical_columns:
        transformers.append(
            (
                "categorical",
                make_one_hot_encoder(),
                categorical_columns,
            )
        )

    for index, column in enumerate(text_columns):
        transformers.append(
            (
                f"text_{index}",
                CountVectorizer(
                    ngram_range=ngram_range,
                    max_features=max_features,
                    dtype=np.float32,
                    # Include single-character words and punctuation.
                    token_pattern=r"(?u)\b\w+\b|[^\w\s]",
                ),
                column,
            )
        )

    return ColumnTransformer(
        transformers=transformers,
        remainder="drop",
        sparse_threshold=1.0,
    )


def as_feature_matrix(values):
    matrix = sparse.csr_matrix(values, dtype=np.float32)

    if matrix.shape[1] == 0:
        raise ValueError("Preprocessing produced no features.")

    if not np.isfinite(matrix.data).all():
        raise ValueError(
            "Preprocessing produced infinite or invalid feature values. "
            "Check numeric magnitudes and input data."
        )

    return matrix


def sort_by_query(dataset, group_column):
    """Make each query's rows contiguous, as ranking libraries require."""
    codes, _ = pd.factorize(dataset[group_column], sort=False)
    order = np.argsort(codes, kind="stable")
    group_sizes = np.bincount(codes).astype(np.int32)
    return dataset.iloc[order].reset_index(drop=True), group_sizes


def grouped_ndcg(y_true, y_pred, groups, k=10):
    """
    Macro-average NDCG: every query receives equal weight.

    Queries with no positive relevance receive 0.
    A singleton query with positive relevance receives 1.
    """
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)

    if len(y_true) != len(y_pred) or len(y_true) != len(groups):
        raise ValueError("Labels, predictions, and query IDs must align.")

    if not np.isfinite(y_pred).all():
        raise ValueError("Model predictions contain non-finite values.")

    codes, unique_groups = pd.factorize(groups, sort=False)
    order = np.argsort(codes, kind="stable")
    sizes = np.bincount(codes)

    scores = []
    offset = 0

    for size in sizes:
        indices = order[offset:offset + size]
        offset += size

        labels = y_true[indices]
        predictions = y_pred[indices]

        # Match the conventional exponential relevance gain used by
        # these ranking objectives.
        gains = np.exp2(labels) - 1.0

        if not np.any(gains > 0):
            score = 0.0
        elif size == 1:
            score = 1.0
        else:
            score = ndcg_score(
                gains.reshape(1, -1),
                predictions.reshape(1, -1),
                k=k,
            )

        scores.append(float(score))

    if not scores:
        raise ValueError("There are no query groups to evaluate.")

    return {
        f"ndcg@{k}": float(np.mean(scores)),
        "queries": len(unique_groups),
        "rows": len(y_true),
        "singleton_queries": int(np.sum(sizes == 1)),
    }


class LTRConfigurator:
    def __init__(self):
        self.data = None
        self.validation_data = None
        self.predictor_columns = []
        self.target_column = None
        self.group_column = None
        self.column_types = {}

        self.selected_models = []
        self.models = {}
        self.best_model_name = None
        self.preprocessor = None
        self.validation_results = None

        self.normalization = "none"
        self.ngram_range = (1, 1)
        self.max_features = 5000
        self.holdout_fraction = 0.2

        self.n_estimators = 500
        self.learning_rate = 0.05
        self.num_leaves = 31
        self.max_depth = 6
        self.num_cpus = min(6, os.cpu_count() or 1)

    @staticmethod
    def get_input(
        prompt,
        default=None,
        input_type=str,
        options=None,
        validator=None,
    ):
        while True:
            suffix = f" [default: {default}]" if default is not None else ""
            raw = input(f"{prompt}{suffix}: ").strip()

            if raw == "" and default is not None:
                raw = str(default)

            try:
                if input_type is bool:
                    normalized = raw.lower()
                    if normalized in {"true", "t", "yes", "y", "1"}:
                        value = True
                    elif normalized in {"false", "f", "no", "n", "0"}:
                        value = False
                    else:
                        raise ValueError("Enter yes or no.")
                else:
                    value = input_type(raw)

                if options is not None and value not in options:
                    raise ValueError(f"Choose one of: {', '.join(map(str, options))}")

                if validator is not None and not validator(value):
                    raise ValueError("The value is outside the allowed range.")

                return value

            except (ValueError, TypeError) as error:
                print(f"Invalid input: {error}")

    def read_csv(self, prompt, allow_skip=False):
        while True:
            raw = self.get_input(
                prompt,
                default="" if allow_skip else None,
            )

            if not raw and allow_skip:
                return None

            try:
                path = clean_path(raw)
                if not path.is_file():
                    raise ValueError("The file does not exist.")

                dataset = pd.read_csv(path, low_memory=False)
                if dataset.empty:
                    raise ValueError("The CSV contains no data rows.")

                print(
                    f"Loaded {len(dataset):,} rows and "
                    f"{len(dataset.columns):,} columns."
                )
                return dataset

            except Exception as error:
                LOGGER.exception("Could not read CSV")
                print(f"Could not load CSV: {error}")

    def select_columns_and_types(self):
        columns = list(self.data.columns)

        if len(columns) < 3:
            raise ValueError(
                "At least three columns are required: a predictor, "
                "a relevance label, and a query/group ID."
            )

        print("\nAvailable columns:")
        for index, column in enumerate(columns, start=1):
            print(f"{index}. {column}")

        valid_index = lambda value: 1 <= value <= len(columns)

        target_index = self.get_input(
            "Number of the relevance-label column",
            input_type=int,
            validator=valid_index,
        ) - 1
        self.target_column = columns[target_index]

        group_index = self.get_input(
            "Number of the query/group-ID column",
            input_type=int,
            validator=lambda value: (
                valid_index(value) and value - 1 != target_index
            ),
        ) - 1
        self.group_column = columns[group_index]

        default_predictors = ",".join(
            str(index + 1)
            for index in range(len(columns))
            if index not in {target_index, group_index}
        )

        while True:
            raw = self.get_input(
                "Predictor column numbers, comma-separated",
                default=default_predictors,
            )

            try:
                indices = [int(part.strip()) - 1 for part in raw.split(",")]

                if not indices:
                    raise ValueError("Select at least one predictor.")
                if len(indices) != len(set(indices)):
                    raise ValueError("Predictor columns must be unique.")
                if any(index < 0 or index >= len(columns) for index in indices):
                    raise ValueError("A column number is out of range.")
                if target_index in indices or group_index in indices:
                    raise ValueError(
                        "The target and query ID cannot be predictors."
                    )

                self.predictor_columns = [columns[index] for index in indices]
                break

            except ValueError as error:
                print(f"Invalid selection: {error}")

        print(
            "\nChoose feature types carefully. Use 'text' for documents or "
            "free text, and 'categorical' for discrete labels."
        )

        for column in self.predictor_columns:
            default_type = (
                "numeric"
                if pd.api.types.is_numeric_dtype(self.data[column])
                else "categorical"
            )
            self.column_types[column] = self.get_input(
                f"Type for {column!r}",
                default=default_type,
                options=["numeric", "text", "datetime", "categorical"],
            )

    def validate_dataset(self, dataset, require_target=True):
        required = self.predictor_columns + [self.group_column]
        if require_target:
            required.append(self.target_column)

        missing = [column for column in required if column not in dataset.columns]
        if missing:
            raise ValueError(f"Missing required columns: {missing}")

        if dataset.empty:
            raise ValueError("The dataset is empty.")

        result = dataset.loc[:, list(dict.fromkeys(required))].copy()

        groups = result[self.group_column]
        if groups.isna().any():
            raise ValueError("Query/group IDs cannot be missing.")

        groups = groups.astype(str)
        if groups.str.strip().eq("").any():
            raise ValueError("Query/group IDs cannot be blank.")

        result[self.group_column] = groups

        if require_target:
            labels = pd.to_numeric(
                result[self.target_column],
                errors="coerce",
            ).to_numpy(dtype=float)

            if not np.isfinite(labels).all():
                raise ValueError(
                    "Relevance labels must be numeric, finite, and nonmissing."
                )

            if (
                np.any(labels < 0)
                or np.any(labels > 30)
                or np.any(labels != np.floor(labels))
            ):
                raise ValueError(
                    "Relevance labels must be integers from 0 to 30, "
                    "with higher values indicating greater relevance."
                )

            result[self.target_column] = labels.astype(np.int32)

        return result.reset_index(drop=True)

    def configure_training(self):
        available = []

        if importlib.util.find_spec("lightgbm") is not None:
            available.append("GBM")
        if importlib.util.find_spec("xgboost") is not None:
            available.append("XGB")

        if not available:
            raise RuntimeError(
                "No ranking library is installed. Run: "
                "pip install lightgbm xgboost"
            )

        print("\nAvailable ranking models:")
        for name in available:
            description = (
                "LightGBM LGBMRanker"
                if name == "GBM"
                else "XGBoost XGBRanker"
            )
            print(f"- {name}: {description}")

        while True:
            raw = self.get_input(
                "Models, comma-separated",
                default=",".join(available),
            )
            selected = list(
                dict.fromkeys(
                    part.strip().upper()
                    for part in raw.split(",")
                    if part.strip()
                )
            )

            if selected and all(name in available for name in selected):
                self.selected_models = selected
                break

            print(f"Choose one or more of: {', '.join(available)}")

        self.normalization = self.get_input(
            "Numeric normalization",
            default="none",
            options=["none", "standard", "minmax"],
        )

        self.holdout_fraction = self.get_input(
            "Validation fraction of query groups, if no validation CSV is supplied",
            default=0.2,
            input_type=float,
            validator=lambda value: 0 < value < 1,
        )

        self.n_estimators = self.get_input(
            "Number of boosting trees",
            default=500,
            input_type=int,
            validator=lambda value: value > 0,
        )

        self.learning_rate = self.get_input(
            "Learning rate",
            default=0.05,
            input_type=float,
            validator=lambda value: 0 < value <= 1,
        )

        self.num_cpus = self.get_input(
            "CPU threads (-1 for all)",
            default=self.num_cpus,
            input_type=int,
            validator=lambda value: value == -1 or value > 0,
        )

        if "GBM" in self.selected_models:
            self.num_leaves = self.get_input(
                "LightGBM maximum leaves per tree",
                default=31,
                input_type=int,
                validator=lambda value: value >= 2,
            )

        if "XGB" in self.selected_models:
            self.max_depth = self.get_input(
                "XGBoost maximum tree depth",
                default=6,
                input_type=int,
                validator=lambda value: value > 0,
            )

        if "text" in self.column_types.values():
            while True:
                raw = self.get_input(
                    "Text n-gram range as min,max",
                    default="1,1",
                )
                try:
                    values = tuple(int(part.strip()) for part in raw.split(","))
                    if len(values) != 2 or not (1 <= values[0] <= values[1]):
                        raise ValueError
                    self.ngram_range = values
                    break
                except ValueError:
                    print("Enter two integers satisfying 1 <= min <= max.")

            self.max_features = self.get_input(
                "Maximum vocabulary size per text column",
                default=5000,
                input_type=int,
                validator=lambda value: value > 0,
            )

    def split_data(self):
        dataset = self.validate_dataset(self.data)

        if self.validation_data is not None:
            validation = self.validate_dataset(self.validation_data)

            overlap = set(dataset[self.group_column]).intersection(
                validation[self.group_column]
            )
            if overlap:
                raise ValueError(
                    f"Training and validation share {len(overlap)} query IDs. "
                    "Use disjoint query groups to prevent validation leakage."
                )

            train = dataset

        else:
            if dataset[self.group_column].nunique() < 2:
                raise ValueError(
                    "At least two distinct query groups are required "
                    "for a group-aware training/validation split."
                )

            splitter = GroupShuffleSplit(
                n_splits=1,
                test_size=self.holdout_fraction,
                random_state=RANDOM_STATE,
            )
            train_indices, validation_indices = next(
                splitter.split(
                    dataset,
                    groups=dataset[self.group_column],
                )
            )
            train = dataset.iloc[train_indices].copy()
            validation = dataset.iloc[validation_indices].copy()

        # Ranking cannot learn an ordering if every training query has
        # only one relevance level.
        relevance_counts = train.groupby(self.group_column)[
            self.target_column
        ].nunique()

        if not (relevance_counts > 1).any():
            raise ValueError(
                "No training query contains differing relevance labels. "
                "Provide multiple candidates with different relevance "
                "labels within at least one training query."
            )

        if not (
            validation.groupby(self.group_column).size() > 1
        ).any():
            warnings.warn(
                "Every validation query has only one row; "
                "NDCG cannot meaningfully assess ordering.",
                stacklevel=2,
            )

        return train, validation

    def make_model(self, name):
        if name == "GBM":
            from lightgbm import LGBMRanker

            return LGBMRanker(
                objective="lambdarank",
                metric="ndcg",
                n_estimators=self.n_estimators,
                learning_rate=self.learning_rate,
                num_leaves=self.num_leaves,
                min_child_samples=5,
                label_gain=[(2 ** index) - 1 for index in range(31)],
                random_state=RANDOM_STATE,
                n_jobs=self.num_cpus,
                verbosity=-1,
            )

        if name == "XGB":
            from xgboost import XGBRanker

            return XGBRanker(
                objective="rank:ndcg",
                eval_metric="ndcg@10",
                n_estimators=self.n_estimators,
                learning_rate=self.learning_rate,
                max_depth=self.max_depth,
                tree_method="hist",
                random_state=RANDOM_STATE,
                n_jobs=self.num_cpus,
                verbosity=0,
            )

        raise ValueError(f"Unknown model: {name}")

    def transform_features(self, dataset):
        if self.preprocessor is None:
            raise RuntimeError("No fitted preprocessor is available.")

        frame = prepare_feature_frame(
            dataset,
            self.predictor_columns,
            self.column_types,
        )
        return as_feature_matrix(self.preprocessor.transform(frame))

    def train_models(self):
        train, validation = self.split_data()
        train, train_groups = sort_by_query(train, self.group_column)
        validation, validation_groups = sort_by_query(
            validation,
            self.group_column,
        )

        print(
            f"\nTraining: {len(train):,} rows, "
            f"{len(train_groups):,} queries"
        )
        print(
            f"Validation: {len(validation):,} rows, "
            f"{len(validation_groups):,} queries"
        )

        train_frame = prepare_feature_frame(
            train,
            self.predictor_columns,
            self.column_types,
        )
        validation_frame = prepare_feature_frame(
            validation,
            self.predictor_columns,
            self.column_types,
        )

        self.preprocessor = build_preprocessor(
            self.predictor_columns,
            self.column_types,
            self.normalization,
            self.ngram_range,
            self.max_features,
        )

        # Fit all learned preprocessing exclusively on training queries.
        x_train = as_feature_matrix(
            self.preprocessor.fit_transform(train_frame)
        )
        x_validation = as_feature_matrix(
            self.preprocessor.transform(validation_frame)
        )

        y_train = train[self.target_column].to_numpy()
        y_validation = validation[self.target_column].to_numpy()

        print(f"Generated features: {x_train.shape[1]:,}")

        self.models = {}
        self.best_model_name = None
        results = []

        for name in self.selected_models:
            print(f"\nTraining {name}...")
            LOGGER.info("Starting %s training", name)

            try:
                model = self.make_model(name)

                if name == "GBM":
                    from lightgbm import log_evaluation

                    model.fit(
                        x_train,
                        y_train,
                        group=train_groups.tolist(),
                        eval_set=[(x_validation, y_validation)],
                        eval_group=[validation_groups.tolist()],
                        eval_at=[10],
                        callbacks=[log_evaluation(period=0)],
                    )
                else:
                    model.fit(
                        x_train,
                        y_train,
                        group=train_groups.tolist(),
                        eval_set=[(x_validation, y_validation)],
                        eval_group=[validation_groups.tolist()],
                        verbose=False,
                    )

                predictions = model.predict(x_validation)
                metrics = grouped_ndcg(
                    y_validation,
                    predictions,
                    validation[self.group_column],
                    k=10,
                )

                self.models[name] = model
                results.append({"model": name, **metrics})

                print(
                    f"{name} validation NDCG@10: "
                    f"{metrics['ndcg@10']:.6f}"
                )
                LOGGER.info("%s validation results: %s", name, metrics)

            except Exception as error:
                LOGGER.exception("%s training failed", name)
                print(f"{name} failed: {error}")

        if not self.models:
            self.preprocessor = None
            raise RuntimeError(
                f"All models failed. See {LOG_FILENAME} for details."
            )

        self.validation_results = (
            pd.DataFrame(results)
            .sort_values("ndcg@10", ascending=False, kind="stable")
            .reset_index(drop=True)
        )
        self.best_model_name = self.validation_results.iloc[0]["model"]

        print("\nValidation leaderboard:")
        print(self.validation_results.to_string(index=False))
        print(f"\nBest model: {self.best_model_name}")
        print(
            "NDCG@10 is averaged equally over queries using exponential "
            "relevance gains. All-zero-relevance queries score 0."
        )
        print(
            "This validation set was used to select the best model. "
            "Use a separate, untouched test set for a final performance estimate."
        )

    def evaluate_models(self, dataset):
        if not self.models:
            raise RuntimeError("Train or load models before evaluation.")

        dataset = self.validate_dataset(dataset)
        features = self.transform_features(dataset)
        labels = dataset[self.target_column].to_numpy()

        results = []
        for name, model in self.models.items():
            predictions = model.predict(features)
            metrics = grouped_ndcg(
                labels,
                predictions,
                dataset[self.group_column],
                k=10,
            )
            results.append({"model": name, **metrics})

        leaderboard = (
            pd.DataFrame(results)
            .sort_values("ndcg@10", ascending=False, kind="stable")
            .reset_index(drop=True)
        )

        print("\nEvaluation results:")
        print(leaderboard.to_string(index=False))
        return leaderboard

    def save_models(self):
        if not self.models:
            raise RuntimeError("There are no trained models to save.")

        directory = clean_path(
            self.get_input("Model output directory", default="ltr_models")
        )
        directory.mkdir(parents=True, exist_ok=True)
        destination = directory / MODEL_FILENAME

        if destination.exists():
            overwrite = self.get_input(
                f"{destination} already exists. Overwrite?",
                default="n",
                input_type=bool,
            )
            if not overwrite:
                print("Save cancelled.")
                return

        bundle = {
            "format_version": 1,
            "models": self.models,
            "best_model_name": self.best_model_name,
            "preprocessor": self.preprocessor,
            "predictor_columns": self.predictor_columns,
            "target_column": self.target_column,
            "group_column": self.group_column,
            "column_types": self.column_types,
            "normalization": self.normalization,
            "ngram_range": self.ngram_range,
            "max_features": self.max_features,
            "validation_results": self.validation_results,
        }

        joblib.dump(bundle, destination, compress=3)
        print(f"Models and preprocessing saved to: {destination.resolve()}")
        LOGGER.info("Saved model bundle to %s", destination)

    def load_models(self):
        path = clean_path(
            self.get_input(
                "Model directory or .joblib file",
                default="ltr_models",
            )
        )
        if path.is_dir():
            path = path / MODEL_FILENAME

        if not path.is_file():
            raise FileNotFoundError(f"Model bundle not found: {path}")

        print(
            "Security notice: joblib files can execute code when loaded. "
            "Only load model files from a trusted source."
        )
        if not self.get_input(
            "Do you trust this model file?",
            default="n",
            input_type=bool,
        ):
            print("Load cancelled.")
            return False

        bundle = joblib.load(path)

        if not isinstance(bundle, dict) or bundle.get("format_version") != 1:
            raise ValueError("Unsupported model bundle format.")

        required_keys = {
            "models",
            "best_model_name",
            "preprocessor",
            "predictor_columns",
            "target_column",
            "group_column",
            "column_types",
            "normalization",
            "ngram_range",
            "max_features",
            "validation_results",
        }
        missing = required_keys.difference(bundle)
        if missing:
            raise ValueError(f"Model bundle is missing fields: {sorted(missing)}")

        if not bundle["models"]:
            raise ValueError("The bundle contains no models.")

        if bundle["best_model_name"] not in bundle["models"]:
            raise ValueError("The bundle's best-model reference is invalid.")

        for key in required_keys:
            setattr(self, key, bundle[key])

        self.selected_models = list(self.models)

        print(f"Loaded models: {', '.join(self.models)}")
        print(f"Selected best model: {self.best_model_name}")
        LOGGER.info("Loaded model bundle from %s", path)
        return True

    def export_rankings(self):
        if not self.models:
            raise RuntimeError("Train or load models before prediction.")

        original = self.read_csv(
            "CSV to rank; relevance labels are optional"
        )
        dataset = self.validate_dataset(
            original,
            require_target=False,
        )
        features = self.transform_features(dataset)

        model_name = self.get_input(
            "Model to use",
            default=self.best_model_name,
            options=list(self.models),
        )
        predictions = np.asarray(
            self.models[model_name].predict(features),
            dtype=float,
        )

        if not np.isfinite(predictions).all():
            raise ValueError("Predictions contain non-finite values.")

        result = original.reset_index(drop=True).copy()

        score_column = "ltr_score"
        while score_column in result.columns:
            score_column = "_" + score_column

        rank_column = "ltr_rank"
        while rank_column in result.columns:
            rank_column = "_" + rank_column

        result[score_column] = predictions
        result[rank_column] = (
            pd.Series(predictions)
            .groupby(dataset[self.group_column], sort=False)
            .rank(method="first", ascending=False)
            .astype(np.int64)
            .to_numpy()
        )

        # Preserve query appearance order, then sort by within-query rank.
        query_codes, _ = pd.factorize(
            dataset[self.group_column],
            sort=False,
        )
        order = np.lexsort(
            (result[rank_column].to_numpy(), query_codes)
        )
        result = result.iloc[order].reset_index(drop=True)

        output = clean_path(
            self.get_input(
                "Output CSV path",
                default="ranked_predictions.csv",
            )
        )
        output.parent.mkdir(parents=True, exist_ok=True)

        if output.exists():
            if not self.get_input(
                f"{output} already exists. Overwrite?",
                default="n",
                input_type=bool,
            ):
                print("Export cancelled.")
                return

        result.to_csv(output, index=False)
        print(f"Rankings saved to: {output.resolve()}")
        print(
            f"Added columns: {score_column}, {rank_column}. "
            "Rank 1 is the highest-scoring candidate within each query. "
            "Scores are ranking scores, not probabilities."
        )

    def post_training_menu(self):
        while True:
            print("\nActions:")
            print("1. Evaluate a separate labeled CSV")
            print("2. Export rankings for a CSV")
            print("3. Save models")
            print("4. Exit")

            choice = self.get_input(
                "Choose an action",
                default="4",
                options=["1", "2", "3", "4"],
            )

            if choice == "4":
                return

            try:
                if choice == "1":
                    print(
                        "For an unbiased test, use query groups that were "
                        "not used for training or model selection."
                    )
                    dataset = self.read_csv("Path to labeled evaluation CSV")
                    self.evaluate_models(dataset)

                elif choice == "2":
                    self.export_rankings()

                elif choice == "3":
                    self.save_models()

            except Exception as error:
                LOGGER.exception("Post-training action failed")
                print(f"Action failed: {error}")
                print(f"Details were written to {LOG_FILENAME}.")

    def run(self):
        print("Learning-to-Rank Configurator")
        print("True query-aware ranking with LightGBM and XGBoost.")
        print(
            "Labels: integers 0–30. Query IDs identify candidates "
            "that must be ranked against one another."
        )

        mode = self.get_input(
            "\nChoose train, load, or exit",
            default="train",
            options=["train", "load", "exit"],
        )

        if mode == "exit":
            return

        if mode == "load":
            if self.load_models():
                self.post_training_menu()
            return

        self.data = self.read_csv("Path to training CSV")
        self.select_columns_and_types()

        print("\nSelected-column missing values:")
        columns = (
            self.predictor_columns
            + [self.target_column, self.group_column]
        )
        print(self.data[columns].isna().sum().to_string())

        self.configure_training()

        self.validation_data = self.read_csv(
            "Path to separate validation CSV, or Enter for a group-aware split",
            allow_skip=True,
        )

        if not self.get_input(
            "Start training?",
            default="y",
            input_type=bool,
        ):
            print("Training cancelled.")
            return

        self.train_models()

        if self.get_input(
            "Save trained models now?",
            default="y",
            input_type=bool,
        ):
            try:
                self.save_models()
            except Exception as error:
                LOGGER.exception("Saving models failed")
                print(f"Could not save models: {error}")
                print("You can retry from the actions menu.")

        self.post_training_menu()


def main():
    try:
        configurator = LTRConfigurator()
        configurator.run()

    except (KeyboardInterrupt, EOFError):
        print("\nSession cancelled.")

    except Exception as error:
        LOGGER.exception("Unhandled error")
        print(f"\nError: {error}")
        print(f"See {Path(LOG_FILENAME).resolve()} for details.")
        return 1

    finally:
        print("\nLearning-to-Rank Configurator session ended.")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
