Yes. If you mean **`UAudioCapture`**, rather than `UAudioCaptureComponent`, you can create it as a UObject and keep it alive with a `UPROPERTY` in your GameMode.

**Important:** GameMode exists only on the server. This approach captures the microphone on the machine running the GameMode—your local machine in standalone play, or the host in a listen-server game. It will **not** capture remote players’ microphones. For that, put the capture logic in a locally owned PlayerController or another client-side object.

## 1. Enable the plugin and module

Enable the **Audio Capture** plugin in the Unreal Editor and restart if prompted.

Add `AudioCapture` to your game module’s dependencies in `YourGame.Build.cs`:

```csharp
PublicDependencyModuleNames.AddRange(new string[]
{
    "Core",
    "CoreUObject",
    "Engine",
    "AudioCapture"
});
```

## 2. GameMode header

Replace `YOURGAME_API` with your project’s API macro.

```cpp
// MicrophoneGameMode.h

#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "MicrophoneGameMode.generated.h"

class UAudioCapture;

UCLASS()
class YOURGAME_API AMicrophoneGameMode : public AGameModeBase
{
    GENERATED_BODY()

public:
    UFUNCTION(BlueprintCallable, Category = "Microphone")
    bool StartMicrophoneCapture();

    UFUNCTION(BlueprintCallable, Category = "Microphone")
    void StopMicrophoneCapture();

protected:
    virtual void BeginPlay() override;

    virtual void EndPlay(
        const EEndPlayReason::Type EndPlayReason) override;

private:
    // Keeps the UObject alive while this GameMode owns it.
    UPROPERTY(Transient)
    TObjectPtr<UAudioCapture> AudioCapture;

    bool bStreamOpened = false;
};
```

## 3. GameMode implementation

```cpp
// MicrophoneGameMode.cpp

#include "MicrophoneGameMode.h"

#include "AudioCapture.h"

void AMicrophoneGameMode::BeginPlay()
{
    Super::BeginPlay();

    // Dedicated servers should not attempt microphone capture.
    if (GetNetMode() != NM_DedicatedServer)
    {
        StartMicrophoneCapture();
    }
}

bool AMicrophoneGameMode::StartMicrophoneCapture()
{
    if (GetNetMode() == NM_DedicatedServer)
    {
        return false;
    }

    if (!AudioCapture)
    {
        AudioCapture = NewObject<UAudioCapture>(this);
    }

    if (!AudioCapture)
    {
        UE_LOG(LogTemp, Error,
            TEXT("Failed to create UAudioCapture."));
        return false;
    }

    if (AudioCapture->IsCapturingAudio())
    {
        return true;
    }

    // Open the default microphone once. After stopping, the same
    // stream can be used to start capturing again.
    if (!bStreamOpened)
    {
        bStreamOpened = AudioCapture->OpenDefaultAudioStream();

        if (!bStreamOpened)
        {
            UE_LOG(LogTemp, Error,
                TEXT("Failed to open the default microphone. "
                     "Check the input device and microphone permissions."));
            return false;
        }
    }

    AudioCapture->StartCapturingAudio();

    const bool bStarted = AudioCapture->IsCapturingAudio();

    if (bStarted)
    {
        UE_LOG(LogTemp, Log, TEXT("Microphone capture started."));
    }
    else
    {
        UE_LOG(LogTemp, Warning,
            TEXT("The microphone stream opened, but capture did not start."));
    }

    return bStarted;
}

void AMicrophoneGameMode::StopMicrophoneCapture()
{
    if (AudioCapture && AudioCapture->IsCapturingAudio())
    {
        AudioCapture->StopCapturingAudio();

        UE_LOG(LogTemp, Log, TEXT("Microphone capture stopped."));
    }
}

void AMicrophoneGameMode::EndPlay(
    const EEndPlayReason::Type EndPlayReason)
{
    StopMicrophoneCapture();

    // Release our reference. UAudioCapture cleans up its underlying
    // capture resources when the UObject is destroyed.
    AudioCapture = nullptr;
    bStreamOpened = false;

    Super::EndPlay(EndPlayReason);
}
```

