## 3. StudentDB.cs

This follows the structure of `CustomerDB`. The file is stored in the current user's local application-data folder to avoid requiring permission to write directly to `C:\`.

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace StudentMaintenance
{
    public static class StudentDB
    {
        private static readonly string Dir = System.IO.Path.Combine(
            Environment.GetFolderPath(
                Environment.SpecialFolder.LocalApplicationData),
            "StudentMaintenance");

        private static readonly string FilePath =
            System.IO.Path.Combine(Dir, "Students.dat");

        public static void SaveStudents(List<Student> students)
        {
            // Ensure that the destination folder exists.
            Directory.CreateDirectory(Dir);

            // Replaces the file with the complete student collection.
            // Disposing BinaryWriter also closes its underlying FileStream.
            using BinaryWriter binaryOut = new(
                new FileStream(
                    FilePath, FileMode.Create, FileAccess.Write),
                Encoding.UTF8);

            foreach (Student student in students)
            {
                // Fields must be read back in this exact order and type.
                binaryOut.Write(student.StudentID);
                binaryOut.Write(student.Name);
                binaryOut.Write(student.GPA);
            }
        }

        public static List<Student> GetStudents()
        {
            List<Student> students = new();

            // No saved data is normal when the application first runs.
            if (!File.Exists(FilePath))
                return students;

            using BinaryReader binaryIn = new(
                new FileStream(
                    FilePath, FileMode.Open, FileAccess.Read),
                Encoding.UTF8);

            // Use stream position rather than PeekChar because each
            // record begins with an integer, not a character.
            while (binaryIn.BaseStream.Position < binaryIn.BaseStream.Length)
            {
                Student student = new()
                {
                    StudentID = binaryIn.ReadInt32(),
                    Name = binaryIn.ReadString(),
                    GPA = binaryIn.ReadDecimal()
                };

                students.Add(student);
            }

            return students;
        }
    }
}
```

