        private bool IsValidData()
        {
            string id = txtStudentID.Text.Trim();
            string name = txtName.Text.Trim();
            string gpa = txtGPA.Text.Trim();

            string message = "";

            // Check required fields before checking their numeric values.
            message += Validator.IsPresent(id, "Student ID");
            if (id != "")
            {
                message += Validator.IsInt32(id, "Student ID");
                message += Validator.IsWithinRange(
                    id, "Student ID", 1, int.MaxValue);
            }

            message += Validator.IsPresent(name, "Name");

            message += Validator.IsPresent(gpa, "GPA");
            if (gpa != "")
            {
                message += Validator.IsDecimal(gpa, "GPA");
                message += Validator.IsWithinRange(gpa, "GPA", 0, 4);
            }

            if (message == "")
                return true;

            MessageBox.Show(
                this,
                message,
                "Invalid Input",
                MessageBoxButtons.OK,
                MessageBoxIcon.Warning);

            return false;
        }

        private void BtnWrite_Click(object? sender, EventArgs e)
        {
            if (!IsValidData())
                return;

            RunFileOperation(() =>
            {
                Student student = new()
                {
                    StudentID = int.Parse(txtStudentID.Text.Trim()),
                    Name = txtName.Text.Trim(),
                    GPA = decimal.Parse(txtGPA.Text.Trim())
                };

                // Load existing students first so previous records
                // remain when SaveStudents replaces the file.
                List<Student> students = StudentDB.GetStudents();
                students.Add(student);

                StudentDB.SaveStudents(students);
                DisplayStudents(students);

                MessageBox.Show(
                    this,
                    "Student data saved successfully.",
                    "Save Complete",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Information);

                txtStudentID.Clear();
                txtName.Clear();
                txtGPA.Clear();
                txtStudentID.Focus();
            });
        }

        private void BtnRead_Click(object? sender, EventArgs e)
        {
            RunFileOperation(() =>
            {
                List<Student> students = StudentDB.GetStudents();
                DisplayStudents(students);

                if (students.Count == 0)
                {
                    MessageBox.Show(
                        this,
                        "No student records have been saved yet.",
                        "Read Data",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Information);
                }
            });
        }

        private void DisplayStudents(List<Student> students)
        {
            lstStudents.Items.Clear();

            foreach (Student student in students)
                lstStudents.Items.Add(student);
        }

        private void RunFileOperation(Action operation)
        {
            // Both button handlers use the same file-error handling.
            try
            {
                operation();
            }
            catch (EndOfStreamException)
            {
                ShowFileError(
                    "The student file is incomplete or damaged.");
            }
            catch (UnauthorizedAccessException)
            {
                ShowFileError(
                    "You do not have permission to access the student file.");
            }
            catch (IOException ex)
            {
                ShowFileError(
                    $"The student file could not be accessed.\n\n{ex.Message}");
            }
            catch (Exception ex) when (
                ex is FormatException || ex is ArgumentException)
            {
                ShowFileError(
                    $"The student file contains invalid data.\n\n{ex.Message}");
            }
        }

        private void ShowFileError(string message)
        {
            MessageBox.Show(
                this,
                message,
                "File Error",
                MessageBoxButtons.OK,
                MessageBoxIcon.Error);
        }
    }
}
