from collections import defaultdict
from collections.abc import AsyncIterable, Iterable, Mapping
from concurrent.futures import Executor
from contextlib import aclosing
from dataclasses import dataclass, field, replace
from pathlib import Path
from typing import Any, Callable


_MISSING = object()
_DROP = object()


class ChainError(RuntimeError):
    """An error annotated with its pipeline stage."""


def _preview(value: Any, limit: int = 200) -> str:
    try:
        text = repr(value)
    except Exception:
        text = f"<{type(value).__name__}>"
    return text[:limit]


def _call_style(fn: Callable) -> bool:
    """Return whether fn should receive (item, config), rather than (item,)."""
    try:
        signature = inspect.signature(fn)
    except (TypeError, ValueError):
        # Some native callables cannot be inspected.
        return False

    try:
        signature.bind(None, None)
        return True
    except TypeError:
        try:
            signature.bind(None)
            return False
        except TypeError as exc:
            raise TypeError(
                "Stage functions must accept fn(item) or fn(item, config). "
                "Wrap other functions in a lambda."
            ) from exc


def _is_async_callable(fn: Callable) -> bool:
    return (
        inspect.iscoroutinefunction(fn)
        or inspect.iscoroutinefunction(getattr(fn, "__call__", None))
    )


async def _invoke(
    fn: Callable,
    item: Any,
    config: Any,
    with_config: bool,
    executor: Executor | None = None,
) -> Any:
    args = (item, config) if with_config else (item,)

    if _is_async_callable(fn):
        result = fn(*args)
    elif executor is None:
        # Sync I/O does not block the event loop.
        result = await asyncio.to_thread(fn, *args)
    else:
        # Can be a ThreadPoolExecutor or ProcessPoolExecutor.
        result = await asyncio.get_running_loop().run_in_executor(
            executor, functools.partial(fn, *args)
        )

    # Also handle sync functions that return an awaitable.
    if inspect.isawaitable(result):
        result = await result

    return result


class DiskCache:
    """
    Atomic file-backed cache.

    Cache files use pickle: the cache directory must be trusted.
    """

    def __init__(self, directory: str | Path):
        self.directory = Path(directory)

    @staticmethod
    def key(namespace: Any, item: Any) -> str:
        payload = pickle.dumps((namespace, item), protocol=5)
        return hashlib.sha256(payload).hexdigest()

    def get(self, key: str) -> Any:
        path = self.directory / f"{key}.pickle"
        try:
            with path.open("rb") as file:
                return pickle.load(file)
        except FileNotFoundError:
            return _MISSING

    def put(self, key: str, value: Any) -> None:
        self.directory.mkdir(parents=True, exist_ok=True)
        fd, temporary = tempfile.mkstemp(dir=self.directory, suffix=".tmp")

        try:
            with os.fdopen(fd, "wb") as file:
                pickle.dump(value, file, protocol=5)
            os.replace(temporary, self.directory / f"{key}.pickle")
        finally:
            Path(temporary).unlink(missing_ok=True)


@dataclass(frozen=True)
class _Step:
    kind: str
    name: str
    options: dict[str, Any] = field(default_factory=dict)


def _read_file(path: Path, format: str):
    """Synchronous iterator; advanced in a worker thread."""
    if format == "text":
        with path.open(encoding="utf-8") as file:
            for line in file:
                yield line.rstrip("\r\n")

    elif format == "jsonl":
        with path.open(encoding="utf-8") as file:
            for number, line in enumerate(file, 1):
                if line.strip():
                    try:
                        yield json.loads(line)
                    except json.JSONDecodeError as exc:
                        raise ValueError(
                            f"Invalid JSON in {path}, line {number}"
                        ) from exc

    elif format == "json":
        # A top-level JSON array is the input contract.
        with path.open("rb") as file:
            first = b""
            while not first:
                byte = file.read(1)
                if not byte:
                    raise ValueError(f"{path} is empty")
                if not byte.isspace():
                    first = byte

            if first != b"[":
                raise ValueError(f"{path} must contain a JSON array")

            file.seek(0)

            try:
                import ijson
            except ImportError:
                # Functional fallback, but materializes the entire array.
                yield from json.load(file)
            else:
                yield from ijson.items(file, "item", use_float=True)

    else:
        raise ValueError(f"Unknown input format: {format!r}")


async def _iterate_sync(iterable: Iterable, batch_size: int = 64):
    """Bridge a sync iterable without blocking the event loop."""
    iterator = iter(iterable)
    try:
        while True:
            batch = await asyncio.to_thread(
                lambda: list(itertools.islice(iterator, batch_size))
            )
            if not batch:
                return
            for item in batch:
                yield item
    finally:
        close = getattr(iterator, "close", None)
        if close is not None:
            await asyncio.to_thread(close)


class _AtomicJSONWriter:
    def __init__(self, path: Path, format: str):
        self.path = path
        self.format = format
        self.temporary: str | None = None
        self.file = None
        self.first = True

    def open(self):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd, self.temporary = tempfile.mkstemp(
            dir=self.path.parent, suffix=".tmp"
        )
        self.file = os.fdopen(fd, "w", encoding="utf-8")
        if self.format == "json":
            self.file.write("[\n")

    def write(self, item: Any):
        # Deliberately no default=str: serialization mistakes should be visible.
        encoded = json.dumps(item, ensure_ascii=False, allow_nan=False)

        if self.format == "jsonl":
            self.file.write(encoded + "\n")
        else:
            if not self.first:
                self.file.write(",\n")
            self.file.write(encoded)
            self.first = False

    def commit(self):
        if self.format == "json":
            self.file.write("\n]\n")

        self.file.close()
        self.file = None
        os.replace(self.temporary, self.path)
        self.temporary = None

    def close(self):
        if self.file is not None:
            self.file.close()
            self.file = None
        if self.temporary is not None:
            Path(self.temporary).unlink(missing_ok=True)
            self.temporary = None


@dataclass(frozen=True)
class Chain:
    config: Any = None
    concurrency: int = 16
    progress: bool = True
    cache_dir: str | Path = ".chain-cache"
    _steps: tuple[_Step, ...] = field(default=(), repr=False)

    def __post_init__(self):
        if self.concurrency < 1:
            raise ValueError("concurrency must be >= 1")

    def _add(self, kind: str, name: str, **options) -> Chain:
        return replace(
            self,
            _steps=self._steps + (_Step(kind, name, options),),
        )

    def _require_source_slot(self):
        if self._steps:
            raise ValueError("load()/from_iterable() must be the first stage")

    def load(self, path: str | Path, *, format: str | None = None) -> Chain:
        self._require_source_slot()
        path = Path(path)
        format = format or {
            ".json": "json",
            ".jsonl": "jsonl",
            ".ndjson": "jsonl",
        }.get(path.suffix.lower(), "text")

        return self._add("load", f"load {path}", path=path, format=format)

    def from_iterable(self, items: Iterable | AsyncIterable) -> Chain:
        self._require_source_slot()
        return self._add("source", "source", items=items)

    def take(self, n: int | None) -> Chain:
        if n is not None and n < 0:
            raise ValueError("n must be >= 0 or None")
        return self._add("take", f"take {n}", n=n)

    def map(
        self,
        fn: Callable,
        *,
        concurrency: int | None = None,
        ordered: bool = True,
        use_cache: bool = False,
        cache_key: str | None = None,
        executor: Executor | None = None,
        name: str | None = None,
    ) -> Chain:
        limit = self.concurrency if concurrency is None else concurrency
        if limit < 1:
            raise ValueError("concurrency must be >= 1")

        label = name or getattr(fn, "__name__", type(fn).__name__)
        return self._add(
            "map",
            label,
            fn=fn,
            with_config=_call_style(fn),
            concurrency=limit,
            ordered=ordered,
            use_cache=use_cache,
            cache_key=cache_key,
            executor=executor,
        )

    def filter(
        self,
        fn: Callable,
        *,
        concurrency: int | None = None,
        ordered: bool = True,
        name: str | None = None,
    ) -> Chain:
        mapped = self.map(
            fn,
            concurrency=concurrency,
            ordered=ordered,
            name=name or f"filter {getattr(fn, '__name__', 'predicate')}",
        )
        return replace(
            mapped,
            _steps=mapped._steps[:-1]
            + (replace(mapped._steps[-1], kind="filter"),),
        )

    def flatten(self) -> Chain:
        """Flatten one level; reject strings and mappings."""
        return self._add("flatten", "flatten")

    def groupby(
        self,
        key: str | Callable,
        *,
        name: str | None = None,
    ) -> Chain:
        """
        Gather all input, then yield groups in first-seen key order.

        groupby("query") -> {"query": value, "items": [...]}
        groupby(callable) -> {"key": value, "items": [...]}
        """
        return self._add(
            "groupby",
            name or f"groupby {key}",
            key=key,
            with_config=_call_style(key) if callable(key) else False,
        )

    def save(self, path: str | Path, *, format: str | None = None) -> Chain:
        path = Path(path)
        format = format or (
            "jsonl" if path.suffix.lower() in {".jsonl", ".ndjson"} else "json"
        )
        if format not in {"json", "jsonl"}:
            raise ValueError("Output format must be json or jsonl")
        return self._add("save", f"save {path}", path=path, format=format)

    def save_to_s3(
        self,
        bucket: str,
        key: str,
        *,
        format: str | None = None,
        extra_args: dict | None = None,
    ) -> Chain:
        format = format or (
            "jsonl" if key.endswith((".jsonl", ".ndjson")) else "json"
        )
        if format not in {"json", "jsonl"}:
            raise ValueError("Output format must be json or jsonl")
        return self._add(
            "s3",
            f"s3://{bucket}/{key}",
            bucket=bucket,
            key=key,
            format=format,
            extra_args=dict(extra_args or {}),
        )

    async def _parallel(self, source, step: _Step):
        options = step.options
        fn = options["fn"]
        cache = DiskCache(self.cache_dir)

        namespace = None
        if options["use_cache"]:
            # Explicit cache_key is preferable for production versioning.
            try:
                implementation = inspect.getsource(fn)
            except (OSError, TypeError):
                implementation = None

            namespace = (
                options["cache_key"]
                or (
                    getattr(fn, "__module__", ""),
                    getattr(fn, "__qualname__", type(fn).__name__),
                    implementation,
                ),
                self.config,
            )

        async def work(index, item):
            try:
                key = None
                if options["use_cache"]:
                    key = await asyncio.to_thread(cache.key, namespace, item)
                    cached = await asyncio.to_thread(cache.get, key)
                    if cached is not _MISSING:
                        return cached

                result = await _invoke(
                    fn,
                    item,
                    self.config,
                    options["with_config"],
                    options["executor"],
                )

                if step.kind == "filter":
                    return item if result else _DROP

                if key is not None:
                    await asyncio.to_thread(cache.put, key, result)

                return result
            except Exception as exc:
                raise ChainError(
                    f"{step.name}: item #{index}, value={_preview(item)}: {exc}"
                ) from exc

        pending: list[asyncio.Task] = []

        async def receive():
            if options["ordered"]:
                task = pending[0]
            else:
                done, _ = await asyncio.wait(
                    pending, return_when=asyncio.FIRST_COMPLETED
                )
                task = next(iter(done))

            # Keep task tracked until its result has been retrieved.
            result = await task
            pending.remove(task)
            return result

        try:
            index = 0
            async for item in source:
                pending.append(asyncio.create_task(work(index, item)))
                index += 1

                if len(pending) >= options["concurrency"]:
                    result = await receive()
                    if result is not _DROP:
                        yield result

            while pending:
                result = await receive()
                if result is not _DROP:
                    yield result
        finally:
            for task in pending:
                task.cancel()
            await asyncio.gather(*pending, return_exceptions=True)

    async def _save_stream(self, source, path: Path, format: str):
        writer = _AtomicJSONWriter(path, format)
        try:
            await asyncio.to_thread(writer.open)
            async for item in source:
                await asyncio.to_thread(writer.write, item)
                yield item
            await asyncio.to_thread(writer.commit)
        finally:
            await asyncio.to_thread(writer.close)

    async def _execute(self, source, step: _Step):
        kind, options = step.kind, step.options

        if kind == "take":
            n = options["n"]
            if n == 0:
                return

            count = 0
            async for item in source:
                yield item
                count += 1
                if n is not None and count >= n:
                    return

        elif kind in {"map", "filter"}:
            async with aclosing(self._parallel(source, step)) as results:
                async for item in results:
                    yield item

        elif kind == "flatten":
            async for items in source:
                if isinstance(items, (str, bytes, bytearray, Mapping)):
                    raise TypeError(
                        "flatten() expected an iterable of items, "
                        f"not {type(items).__name__}"
                    )
                if isinstance(items, AsyncIterable):
                    async for item in items:
                        yield item
                else:
                    async with aclosing(_iterate_sync(items)) as values:
                        async for item in values:
                            yield item

        elif kind == "groupby":
            groups = defaultdict(list)
            key = options["key"]

            async for item in source:
                value = (
                    await _invoke(
                        key, item, self.config, options["with_config"]
                    )
                    if callable(key)
                    else item[key]
                )
                groups[value].append(item)

            field_name = key if isinstance(key, str) else "key"
            if field_name == "items":
                raise ValueError("'items' is reserved for group contents")

            for value, items in groups.items():
                yield {field_name: value, "items": items}

        elif kind == "save":
            async with aclosing(
                self._save_stream(source, options["path"], options["format"])
            ) as results:
                async for item in results:
                    yield item

        elif kind == "s3":
            # Spool to disk, not RAM. Upload only after complete consumption.
            with tempfile.TemporaryDirectory(prefix="chain-s3-") as directory:
                path = Path(directory) / "payload"

                async with aclosing(
                    self._save_stream(source, path, options["format"])
                ) as results:
                    async for item in results:
                        yield item

                def upload():
                    import boto3

                    boto3.client("s3").upload_file(
                        str(path),
                        options["bucket"],
                        options["key"],
                        ExtraArgs=options["extra_args"],
                    )

                await asyncio.to_thread(upload)

        else:
            raise ValueError(f"Unknown stage: {kind}")

    async def _source(self, step: _Step):
        if step.kind == "load":
            values = _read_file(step.options["path"], step.options["format"])
        else:
            values = step.options["items"]

        if isinstance(values, AsyncIterable):
            iterator = aiter(values)
            try:
                async for item in iterator:
                    yield item
            finally:
                close = getattr(iterator, "aclose", None)
                if close is not None:
                    await close()
        else:
            async with aclosing(_iterate_sync(values)) as iterator:
                async for item in iterator:
                    yield item

    async def _guard(self, iterator, step: _Step, position: int):
        bar = None
        if self.progress:
            try:
                from tqdm.auto import tqdm
            except ImportError:
                pass
            else:
                bar = tqdm(
                    desc=step.name,
                    position=position,
                    unit="item",
                    leave=True,
                )

        try:
            async with aclosing(iterator):
                async for item in iterator:
                    if bar is not None:
                        bar.update()
                    yield item
        except ChainError:
            raise
        except Exception as exc:
            raise ChainError(
                f"Stage {position + 1} ({step.name}) failed: {exc}"
            ) from exc
        finally:
            if bar is not None:
                bar.close()

    async def _stage(self, source, step: _Step, position: int):
        # Closing a downstream stage recursively closes its upstream stages.
        async with aclosing(source):
            async with aclosing(
                self._guard(self._execute(source, step), step, position)
            ) as results:
                async for item in results:
                    yield item

    def __aiter__(self):
        if not self._steps or self._steps[0].kind not in {"load", "source"}:
            raise ValueError("A chain must start with load() or from_iterable()")

        first = self._steps[0]
        stream = self._guard(self._source(first), first, 0)

        for position, step in enumerate(self._steps[1:], 1):
            stream = self._stage(stream, step, position)

        return stream

    async def arun(self, *, collect: bool = False):
        """
        Drain the pipeline.

        Return the final item count, or a list when collect=True.
        """
        output = [] if collect else None
        count = 0

        async with aclosing(aiter(self)) as stream:
            async for item in stream:
                count += 1
                if collect:
                    output.append(item)

        return output if collect else count

    def run(self, *, collect: bool = False):
        try:
            asyncio.get_running_loop()
        except RuntimeError:
            return asyncio.run(self.arun(collect=collect))

        raise RuntimeError(
            "An event loop is already running. Use `await chain.arun()`."
        )
```

