from textual.widgets import Button, Footer, Header, Label, Static


class FileRow(Horizontal):
    """A clickable file row containing a Delete button."""

    class Selected(Message):
        def __init__(self, filename: str) -> None:
            super().__init__()
            self.filename = filename

    class Deleted(Message):
        def __init__(self, filename: str) -> None:
            super().__init__()
            self.filename = filename

    def __init__(self, filename: str) -> None:
        super().__init__()
        self.filename = filename

    def compose(self) -> ComposeResult:
        yield Label(self.filename)
        yield Button("Delete", variant="error", classes="delete")

    def on_click(self, event: events.Click) -> None:
        # Don't treat a click on the Delete button as selecting the row.
        if isinstance(event.widget, Button):
            return

        event.stop()
        self.post_message(self.Selected(self.filename))

    @on(Button.Pressed, ".delete")
    def delete_clicked(self, event: Button.Pressed) -> None:
        # Prevent the button's message from bubbling to parent widgets.
        event.stop()
        self.post_message(self.Deleted(self.filename))
        self.remove()


