Replace `MarkdownBlock._parse()` with the implementation below and add the CSS. It highlights text enclosed in straight (`"..."`) or curly (`“...”`) double quotation marks, including sentences containing Markdown formatting such as `"some **bold** text"`.

### CSS

```css
md-block .md-quoted {
	color: red;
}
```

### Updated `MarkdownBlock._parse()`

```js
_parse() {
	const template = document.createElement("template");
	template.innerHTML = marked.parse(this._mdContent);

	const textNodes = [];
	let text = "";

	// Do not modify code highlighting or non-visible content.
	const skipTags = new Set([
		"CODE", "PRE", "SCRIPT", "STYLE", "TEXTAREA"
	]);

	// Prevent quotation matches from crossing separate Markdown blocks.
	const blockTags = new Set([
		"ADDRESS", "ARTICLE", "ASIDE", "BLOCKQUOTE", "DIV",
		"DL", "DT", "DD", "FIGURE", "FIGCAPTION", "FOOTER",
		"H1", "H2", "H3", "H4", "H5", "H6", "HEADER",
		"HR", "LI", "MAIN", "NAV", "OL", "P", "SECTION",
		"TABLE", "TBODY", "TD", "TH", "THEAD", "TR", "UL"
	]);

	function collect(node) {
		if (node.nodeType === Node.TEXT_NODE) {
			const start = text.length;
			text += node.nodeValue;

			textNodes.push({
				node,
				start,
				end: text.length
			});

			return;
		}

		if (node.nodeType === Node.ELEMENT_NODE) {
			if (skipTags.has(node.tagName) || node.tagName === "BR") {
				text += "\0";
				return;
			}
		}

		const isBlock =
			node.nodeType === Node.ELEMENT_NODE &&
			blockTags.has(node.tagName);

		if (isBlock) {
			text += "\0";
		}

		for (const child of node.childNodes) {
			collect(child);
		}

		if (isBlock) {
			text += "\0";
		}
	}

	collect(template.content);

	// Match paired quotation marks without crossing block boundaries.
	const quotePattern = /"[^"\0]+"|“[^”\0]+”/g;
	const matches = Array.from(text.matchAll(quotePattern), match => ({
		start: match.index,
		end: match.index + match[0].length
	}));

	for (const { node, start, end } of textNodes) {
		const overlaps = matches.filter(match =>
			match.start < end && match.end > start
		);

		if (!overlaps.length) {
			continue;
		}

		const fragment = document.createDocumentFragment();
		const value = node.nodeValue;
		let cursor = 0;

		for (const match of overlaps) {
			const from = Math.max(match.start, start) - start;
			const to = Math.min(match.end, end) - start;

			fragment.appendChild(
				document.createTextNode(value.slice(cursor, from))
			);

			const span = document.createElement("span");
			span.className = "md-quoted";
			span.textContent = value.slice(from, to);
			fragment.appendChild(span);

			cursor = to;
		}

		fragment.appendChild(
			document.createTextNode(value.slice(cursor))
		);

		node.replaceWith(fragment);
	}

	return template.innerHTML;
}
```

This operates on rendered text rather than replacing characters in HTML, so quotation marks in attributes such as `href="..."` remain untouched. Your existing sanitization still runs afterward, and `MarkdownSpan` remains unchanged.

