    local direction = parentChr.getDirection();
    sq_SetCurrentDirection(obj, direction);

    // 平滑移动耗时，单位：毫秒
    local moveTime = 200;

    // 保存本次移动的开始时间和起点坐标
    local moveData = obj.getVar("case11SmoothMove");

    if (moveData.size_vector() == 0)
    {
        moveData.push_vector(sq_GetObjectTime(obj));
        moveData.push_vector(obj.getXPos());
        moveData.push_vector(obj.getYPos());
        moveData.push_vector(obj.getZPos());
