    local startTime = moveData.get_vector(0);
    local startX = moveData.get_vector(1);
    local startY = moveData.get_vector(2);
    local startZ = moveData.get_vector(3);

    // 计算目标位置
    local targetX = parentChr.getXPos();
    local targetY = parentChr.getYPos();
    local targetZ = parentChr.getZPos() + 100;

    if (direction == ENUM_DIRECTION_LEFT)
    {
        targetX += 60;
    }
    else if (direction == ENUM_DIRECTION_RIGHT)
    {
        targetX -= 60;
    }

    // 当前已经移动的时间
    local currentT = sq_GetObjectTime(obj) - startTime;

    if (currentT < 0)
