Here’s a complete, playable hex wargame. It includes terrain-aware movement, ranged attacks, an AI opponent, health, and victory conditions.

The grid uses **pointy-top axial coordinates**. Picking uses the inverse transform followed by **cube rounding**, so clicking near hex edges selects the correct tile.

Install Pygame:

```bash
pip install pygame
```

Save this as `hex_wargame.py`, then run `python hex_wargame.py`.

```python
import math
import random
import heapq
from dataclasses import dataclass

import pygame


# ---------------------------------------------------------------------
# Hex geometry
# ---------------------------------------------------------------------

HEX_SIZE = 32
SQRT3 = math.sqrt(3)
ORIGIN = (52, 74)

# Axial neighbors: cube coordinates would be (q, -q-r, r).
DIRECTIONS = (
    (1, 0), (1, -1), (0, -1),
    (-1, 0), (-1, 1), (0, 1),
)


def hex2pixel(q, r):
    """Pointy-top axial coordinates -> pixel center."""
    x = HEX_SIZE * SQRT3 * (q + r / 2)
    y = HEX_SIZE * 1.5 * r
    return x + ORIGIN[0], y + ORIGIN[1]


def cube_round(q, r):
    """Round fractional axial coordinates while preserving x+y+z=0."""
    x, z = q, r
    y = -x - z

    rx, ry, rz = round(x), round(y), round(z)
    dx, dy, dz = abs(rx - x), abs(ry - y), abs(rz - z)

    if dx > dy and dx > dz:
        rx = -ry - rz
    elif dy > dz:
        ry = -rx - rz
    else:
        rz = -rx - ry

    return int(rx), int(rz)


def pixel2hex(x, y):
    """Pixel position -> nearest axial hex, using the inverse transform."""
    x -= ORIGIN[0]
    y -= ORIGIN[1]

    q = (SQRT3 / 3 * x - y / 3) / HEX_SIZE
    r = (2 / 3 * y) / HEX_SIZE
    return cube_round(q, r)


def hex_corners(q, r):
    """Vertices matching the pointy-top center spacing exactly."""
    cx, cy = hex2pixel(q, r)
    return [
        (
            round(cx + HEX_SIZE * math.cos(math.radians(60 * i - 30))),
            round(cy + HEX_SIZE * math.sin(math.radians(60 * i - 30))),
        )
        for i in range(6)
    ]


def neighbors(pos):
    q, r = pos
    for dq, dr in DIRECTIONS:
        yield q + dq, r + dr


def hex_distance(a, b):
    dq = a[0] - b[0]
    dr = a[1] - b[1]
    return max(abs(dq), abs(dr), abs(dq + dr))


def offset_to_axial(col, row):
    """Odd-row offset layout, used only to construct a rectangular map."""
    return col - row // 2, row


# ---------------------------------------------------------------------
# Rules and presentation
# ---------------------------------------------------------------------

WIDTH, HEIGHT = 1060, 740
PANEL_X = 750
COLS, ROWS = 12, 12

BG = (24, 29, 36)
PANEL = (32, 39, 49)
TEXT = (230, 235, 241)
MUTED = (163, 177, 190)
BLUE = (72, 158, 247)
RED = (230, 88, 83)
YELLOW = (255, 222, 92)
GREEN = (128, 235, 171)

TERRAIN_COLOR = {
    "plain": (124, 153, 98),
    "forest": (65, 111, 76),
    "hill": (165, 148, 104),
    "water": (60, 107, 146),
}
MOVE_COST = {"plain": 1, "forest": 2, "hill": 2}
DEFENSE = {"plain": 0, "forest": 1, "hill": 1, "water": 0}

# HP, movement points, attack range, damage
STATS = {
    "Infantry": (10, 3, 1, 4),
    "Scout": (7, 5, 1, 3),
    "Artillery": (8, 2, 3, 3),
}
SYMBOLS = {"Infantry": "I", "Scout": "S", "Artillery": "A"}


@dataclass
class Unit:
    team: int
    kind: str
    pos: tuple
    hp: int = 0
    moved: bool = False
    attacked: bool = False

    def __post_init__(self):
        self.hp = STATS[self.kind][0]

    @property
    def alive(self):
        return self.hp > 0

    @property
    def movement(self):
        return STATS[self.kind][1]

    @property
    def attack_range(self):
        return STATS[self.kind][2]

    @property
    def damage(self):
        return STATS[self.kind][3]


class Game:
    def __init__(self):
        pygame.init()
        pygame.display.set_caption("Hex Front")
        self.screen = pygame.display.set_mode((WIDTH, HEIGHT))
        self.clock = pygame.time.Clock()
        self.font = pygame.font.Font(None, 24)
        self.small = pygame.font.Font(None, 20)
        self.large = pygame.font.Font(None, 36)
        self.end_button = pygame.Rect(PANEL_X + 20, 648, 270, 45)
        self.restart_button = pygame.Rect(PANEL_X + 20, 701, 270, 28)
        self.reset()

    def reset(self):
        rng = random.Random(7)
        self.board = {}

        for row in range(ROWS):
            for col in range(COLS):
                value = rng.random()
                terrain = (
                    "water" if value < 0.10 else
                    "forest" if value < 0.31 else
                    "hill" if value < 0.47 else
                    "plain"
                )

                # Clear deployment lanes and two connecting routes.
                if col in (0, 1, 10, 11) or row in (5, 6):
                    terrain = "plain"

                self.board[offset_to_axial(col, row)] = terrain

        self.polygons = {
            pos: hex_corners(*pos) for pos in self.board
        }

        self.units = []
        deployment = (
            (2, "Infantry"),
            (4, "Scout"),
            (7, "Artillery"),
            (9, "Infantry"),
        )
        for team, col in ((0, 1), (1, 10)):
            for row, kind in deployment:
                self.units.append(Unit(team, kind, offset_to_axial(col, row)))

        self.selected = None
        self.reachable_tiles = {}
        self.turn = 0
        self.round_number = 1
        self.winner = None
        self.ai_queue = []
        self.next_ai_time = 0
        self.messages = ["Select a blue unit to begin."]

        # Basic geometry sanity checks.
        for pos in self.board:
            assert pixel2hex(*hex2pixel(*pos)) == pos
        for dq, dr in DIRECTIONS:
            a = hex2pixel(0, 0)
            b = hex2pixel(dq, dr)
            assert math.isclose(
                math.hypot(b[0] - a[0], b[1] - a[1]),
                SQRT3 * HEX_SIZE,
            )

    def log(self, message):
        self.messages.append(message)
        self.messages = self.messages[-5:]

    def living(self, team):
        return [u for u in self.units if u.alive and u.team == team]

    def unit_at(self, pos):
        return next(
            (u for u in self.units if u.alive and u.pos == pos),
            None,
        )

    def movement_search(self, unit, budget=None):
        """Dijkstra search: forests/hills cost two; units block movement."""
        occupied = {
            u.pos for u in self.units if u.alive and u is not unit
        }
        distances = {unit.pos: 0}
        queue = [(0, unit.pos)]

        while queue:
            cost, current = heapq.heappop(queue)
            if cost != distances[current]:
                continue

            for nxt in neighbors(current):
                terrain = self.board.get(nxt)
                if terrain not in MOVE_COST or nxt in occupied:
                    continue

                new_cost = cost + MOVE_COST[terrain]
                if budget is not None and new_cost > budget:
                    continue
                if new_cost < distances.get(nxt, math.inf):
                    distances[nxt] = new_cost
                    heapq.heappush(queue, (new_cost, nxt))

        return distances

    def select(self, unit):
        self.selected = unit
        self.refresh_reachable()

    def refresh_reachable(self):
        unit = self.selected
        if unit and unit.alive and not unit.moved and not unit.attacked:
            self.reachable_tiles = self.movement_search(
                unit, unit.movement
            )
        else:
            self.reachable_tiles = {}

    def can_attack(self, attacker, defender):
        return (
            attacker.alive
            and defender.alive
            and attacker.team != defender.team
            and not attacker.attacked
            and hex_distance(attacker.pos, defender.pos)
            <= attacker.attack_range
        )

    def attack(self, attacker, defender):
        if not self.can_attack(attacker, defender):
            return

        damage = max(
            1, attacker.damage - DEFENSE[self.board[defender.pos]]
        )
        defender.hp = max(0, defender.hp - damage)

        # Attacking ends this unit's activation: no move-after-fire.
        attacker.attacked = True
        attacker.moved = True
        side = "Blue" if attacker.team == 0 else "Red"
        self.log(f"{side} {attacker.kind}: {damage} damage.")

        if not defender.alive:
            self.log(f"{defender.kind} destroyed.")

        for team in (0, 1):
            if not self.living(team):
                self.winner = 1 - team
                self.selected = None
                self.reachable_tiles = {}
                return

        self.refresh_reachable()

    def click_map(self, pos):
        if self.turn != 0 or self.winner is not None:
            return
        if pos not in self.board:
            return

        target = self.unit_at(pos)

        if target and target.team == 0:
            self.select(target)
            return

        unit = self.selected
        if not unit:
            return

        if target:
            if self.can_attack(unit, target):
                self.attack(unit, target)
            else:
                self.log("Target out of range, or unit spent.")
            return

        if pos != unit.pos and pos in self.reachable_tiles:
            unit.pos = pos
            unit.moved = True
            self.refresh_reachable()

    def end_turn(self):
        if self.turn != 0 or self.winner is not None:
            return

        self.turn = 1
        self.selected = None
        self.reachable_tiles = {}
        self.ai_queue = self.living(1)[:]

        for unit in self.ai_queue:
            unit.moved = False
            unit.attacked = False

        self.next_ai_time = pygame.time.get_ticks() + 350
        self.log("Red advances.")

    def ai_destination(self, unit, enemies):
        """
        Find attack positions, then route toward them using a reverse
        multi-source Dijkstra search. This avoids getting stuck at water.
        """
        occupied = {
            u.pos for u in self.units if u.alive and u is not unit
        }
        passable = {
            pos for pos, terrain in self.board.items()
            if terrain in MOVE_COST and pos not in occupied
        }

        goals = {
            pos for pos in passable
            if any(
                hex_distance(pos, enemy.pos) <= unit.attack_range
                for enemy in enemies
            )
        }

        remaining = {pos: 0 for pos in goals}
        queue = [(0, pos) for pos in goals]
        heapq.heapify(queue)

        while queue:
            cost, current = heapq.heappop(queue)
            if cost != remaining[current]:
                continue

            for previous in neighbors(current):
                if previous not in passable:
                    continue

                # Forward movement previous -> current pays current's cost.
                new_cost = cost + MOVE_COST[self.board[current]]
                if new_cost < remaining.get(previous, math.inf):
                    remaining[previous] = new_cost
                    heapq.heappush(queue, (new_cost, previous))

        reachable = self.movement_search(unit, unit.movement)
        return min(
            reachable,
            key=lambda pos: (
                remaining.get(pos, math.inf),
                min(hex_distance(pos, e.pos) for e in enemies),
                reachable[pos],
            ),
        )

    def ai_action(self, unit):
        enemies = self.living(0)
        if not unit.alive or not enemies:
            return

        targets = [e for e in enemies if self.can_attack(unit, e)]
        if not targets:
            unit.pos = self.ai_destination(unit, enemies)
            unit.moved = True
            targets = [e for e in enemies if self.can_attack(unit, e)]

        if targets:
            target = min(targets, key=lambda e: (e.hp, e.kind))
            self.attack(unit, target)

        unit.moved = True
        unit.attacked = True

    def update_ai(self):
        if self.turn != 1 or self.winner is not None:
            return

        now = pygame.time.get_ticks()
        if now < self.next_ai_time:
            return

        if self.ai_queue:
            self.ai_action(self.ai_queue.pop(0))
            self.next_ai_time = now + 550
        else:
            self.turn = 0
            self.round_number += 1
            for unit in self.living(0):
                unit.moved = False
                unit.attacked = False
            self.log("Your turn.")

    def cycle_selection(self):
        candidates = [u for u in self.living(0) if not u.attacked]
        if not candidates:
            return

        if self.selected in candidates:
            index = (candidates.index(self.selected) + 1) % len(candidates)
        else:
            index = 0
        self.select(candidates[index])

    # -----------------------------------------------------------------
    # Rendering
    # -----------------------------------------------------------------

    def text(self, message, x, y, color=TEXT, font=None):
        image = (font or self.font).render(message, True, color)
        self.screen.blit(image, (x, y))

    def outline(self, pos, color, width=3):
        pygame.draw.polygon(
            self.screen, color, self.polygons[pos], width
        )

    def draw_terrain_symbol(self, pos, terrain):
        x, y = map(round, hex2pixel(*pos))
        if terrain == "forest":
            pygame.draw.polygon(
                self.screen, (43, 79, 54),
                [(x, y - 13), (x - 10, y + 7), (x + 10, y + 7)],
            )
        elif terrain == "hill":
            pygame.draw.lines(
                self.screen, (113, 98, 68), False,
                [(x - 13, y + 6), (x, y - 10), (x + 13, y + 6)], 3,
            )
        elif terrain == "water":
            for dy in (-5, 5):
                pygame.draw.line(
                    self.screen, (91, 148, 184),
                    (x - 11, y + dy), (x + 11, y + dy), 2,
                )

    def draw(self):
        self.screen.fill(BG)

        # Full-size polygons; no arbitrary gaps or reduced hex radii.
        # Draw all fills first, then borders, so tiles share their edges.
        for pos, terrain in self.board.items():
            pygame.draw.polygon(
                self.screen, TERRAIN_COLOR[terrain], self.polygons[pos]
            )
            self.draw_terrain_symbol(pos, terrain)

        for pos in self.board:
            self.outline(pos, (51, 65, 56), 1)

        for pos in self.reachable_tiles:
            if self.selected and pos != self.selected.pos:
                self.outline(pos, GREEN, 2)

        if self.selected:
            for enemy in self.living(1):
                if self.can_attack(self.selected, enemy):
                    self.outline(enemy.pos, RED, 4)
            self.outline(self.selected.pos, YELLOW, 4)

        hover = pixel2hex(*pygame.mouse.get_pos())
        if hover in self.board:
            self.outline(hover, (238, 242, 230), 2)

        for unit in self.units:
            if not unit.alive:
                continue

            x, y = map(round, hex2pixel(*unit.pos))
            color = BLUE if unit.team == 0 else RED
            if unit.attacked:
                color = tuple(int(channel * 0.58) for channel in color)

            pygame.draw.circle(self.screen, (21, 27, 34), (x, y), 20)
            pygame.draw.circle(self.screen, color, (x, y), 17)

            label = self.font.render(SYMBOLS[unit.kind], True, TEXT)
            self.screen.blit(label, label.get_rect(center=(x, y - 2)))

            max_hp = STATS[unit.kind][0]
            pygame.draw.rect(self.screen, (42, 34, 34), (x - 18, y + 20, 36, 5))
            pygame.draw.rect(
                self.screen, GREEN,
                (x - 18, y + 20, round(36 * unit.hp / max_hp), 5),
            )

            if unit.moved and not unit.attacked:
                pygame.draw.circle(self.screen, YELLOW, (x + 14, y - 14), 4)

        self.text("HEX FRONT", 25, 16, font=self.large)
        self.text("Green: legal moves   Red: legal targets", 25, 653, GREEN)
        self.text("Click a blue unit, then a destination or enemy.", 25, 680)
        self.text("Right-click: deselect   Tab: next unit   Space: wait", 25, 706, MUTED)

        pygame.draw.rect(
            self.screen, PANEL, (PANEL_X, 0, WIDTH - PANEL_X, HEIGHT)
        )
        x = PANEL_X + 20
        self.text(f"Round {self.round_number}", x, 22, font=self.large)

        if self.winner is not None:
            status = "VICTORY!" if self.winner == 0 else "DEFEAT"
            status_color = GREEN if self.winner == 0 else RED
        else:
            status = "Your turn" if self.turn == 0 else "Red is thinking..."
            status_color = BLUE if self.turn == 0 else RED

        self.text(status, x, 65, status_color)
        self.text(
            f"Blue: {len(self.living(0))}    Red: {len(self.living(1))}",
            x, 98,
        )

        unit = self.selected
        if unit:
            self.text(unit.kind, x, 145, YELLOW, self.large)
            self.text(f"HP: {unit.hp}/{STATS[unit.kind][0]}", x, 183)
            self.text(f"Movement: {unit.movement} points", x, 209)
            self.text(
                f"Range: {unit.attack_range}   Damage: {unit.damage}",
                x, 235,
            )
            action = (
                "Spent" if unit.attacked else
                "Moved; may still attack" if unit.moved else
                "Ready to move or attack"
            )
            self.text(action, x, 266, MUTED)
        else:
            self.text("No unit selected", x, 153, MUTED)

        self.text("TERRAIN", x, 310, YELLOW)
        terrain_help = [
            ("plain", "Plain: 1 movement"),
            ("forest", "Forest: 2 movement, +1 armor"),
            ("hill", "Hill: 2 movement, +1 armor"),
            ("water", "Water: impassable"),
        ]
        for i, (terrain, description) in enumerate(terrain_help):
            y = 340 + i * 25
            pygame.draw.rect(
                self.screen, TERRAIN_COLOR[terrain], (x, y, 14, 14)
            )
            self.text(description, x + 23, y - 1, font=self.small)

        self.text("Move once, then attack once.", x, 452, font=self.small)
        self.text("Attacking first forfeits movement.", x, 474, font=self.small)
        self.text("Artillery ignores line of sight.", x, 496, font=self.small)
        self.text("Destroy every red unit to win.", x, 518, font=self.small)

        for i, message in enumerate(self.messages):
            self.text(message, x, 546 + i * 18, MUTED, self.small)

        enabled = self.turn == 0 and self.winner is None
        pygame.draw.rect(
            self.screen,
            (49, 101, 160) if enabled else (61, 68, 78),
            self.end_button,
            border_radius=6,
        )
        self.text("End turn  [Enter]", x + 59, 662)

        pygame.draw.rect(
            self.screen, (65, 74, 88), self.restart_button,
            border_radius=5,
        )
        self.text("Restart  [R]", x + 94, 707, font=self.small)

        pygame.display.flip()

    def run(self):
        running = True
        while running:
            self.clock.tick(60)

            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    running = False

                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_ESCAPE:
                        running = False
                    elif event.key == pygame.K_r:
                        self.reset()
                    elif event.key == pygame.K_RETURN:
                        self.end_turn()
                    elif self.turn == 0 and self.winner is None:
                        if event.key == pygame.K_TAB:
                            self.cycle_selection()
                        elif event.key == pygame.K_SPACE and self.selected:
                            self.selected.moved = True
                            self.selected.attacked = True
                            self.select(None)

                elif event.type == pygame.MOUSEBUTTONDOWN:
                    if event.button == 3:
                        self.select(None)
                    elif event.button == 1:
                        if self.restart_button.collidepoint(event.pos):
                            self.reset()
                        elif self.end_button.collidepoint(event.pos):
                            self.end_turn()
                        elif event.pos[0] < PANEL_X:
                            self.click_map(pixel2hex(*event.pos))

            self.update_ai()
            self.draw()

        pygame.quit()


if __name__ == "__main__":
    Game().run()
```

**Why these hexes tile correctly:** for pointy-top hexagons of radius `s`, horizontal center spacing is `√3 × s`, and row spacing is `1.5 × s`. The axial transform applies the necessary half-column shift. `pixel2hex` reverses that same transform and rounds in cube space—not independently along the two axial axes, which would produce incorrect selections near corners.

`filter: blur()` blurs the element **and all its children**. Put the content in a separate wrapper and position the lock icon above it.

