import SwiftUI

// MARK: - App

@main
struct TennisScoreTrackerApp: App {
    var body: some Scene {
        WindowGroup {
            MatchView()
        }
    }
}

// MARK: - Stored Models

enum PointOutcome: String, Codable, CaseIterable, Identifiable {
    case unspecified = "Unspecified"
    case winner = "Winner"
    case unforcedError = "Unforced error"
    case forcedError = "Forced error"
    case ace = "Ace"
    case returnWinner = "Return winner"
    case serveWinner = "Serve winner"

    var id: String { rawValue }

    var isError: Bool {
        self == .unforcedError || self == .forcedError
    }

    /// Keep the categories mutually exclusive.
    /// For example, record an ace as "Ace", not also as "Winner".
    func isAllowed(pointWinner: Int, server: Int) -> Bool {
        switch self {
        case .ace, .serveWinner:
            return pointWinner == server

        case .returnWinner:
            return pointWinner != server

        default:
            return true
        }
    }
}

struct PointEvent: Identifiable, Codable {
    var id = UUID()
    var timestamp = Date()

    /// Player indexes: 0 or 1.
    var winner: Int
    var outcome: PointOutcome
}

struct MatchData: Codable {
    var playerNames = ["Player 1", "Player 2"]
    var firstServer = 0
    var events: [PointEvent] = []

    func name(for player: Int) -> String {
        let name = playerNames[player]
            .trimmingCharacters(in: .whitespacesAndNewlines)

        return name.isEmpty ? "Player \(player + 1)" : name
    }
}

struct CompletedSet {
    let games: [Int]
    let tiebreakPoints: [Int]?

    var winner: Int {
        games[0] > games[1] ? 0 : 1
    }

    var display: String {
        let result = "\(games[0])–\(games[1])"

        if let tiebreakPoints {
            return result
                + "  (TB \(tiebreakPoints[0])–\(tiebreakPoints[1]))"
        }

        return result
    }
}

// MARK: - Tennis Scoring Engine

struct TennisScore {
    private(set) var completedSets: [CompletedSet] = []
    private(set) var games = [0, 0]

    /// During a normal game these are raw points: 0, 1, 2, 3, etc.
    /// During a tiebreak these are the actual tiebreak scores.
    private(set) var points = [0, 0]

    /// Normal-game server, or the first server of the current tiebreak.
    private var gameServer: Int

    init(firstServer: Int) {
        gameServer = firstServer
    }

    var setWins: [Int] {
        completedSets.reduce(into: [0, 0]) { totals, set in
            totals[set.winner] += 1
        }
    }

    var matchWinner: Int? {
        setWins.firstIndex(where: { $0 == 2 })
    }

    var isFinished: Bool {
        matchWinner != nil
    }

    var isTiebreak: Bool {
        !isFinished && games == [6, 6]
    }

    var currentSetNumber: Int {
        completedSets.count + 1
    }

    var server: Int {
        guard isTiebreak else {
            return gameServer
        }

        // Tiebreak sequence:
        // A serves point 1.
        // B serves points 2–3.
        // A serves points 4–5, and so on.
        let pointsPlayed = points[0] + points[1]
        let serverOffset = ((pointsPlayed + 1) / 2) % 2

        return (gameServer + serverOffset) % 2
    }

    func pointLabel(for player: Int) -> String {
        guard !isFinished else {
            return "—"
        }

        if isTiebreak {
            return String(points[player])
        }

        if points[0] >= 3 && points[1] >= 3 {
            return points[player] > points[1 - player] ? "AD" : "40"
        }

        return ["0", "15", "30", "40"][min(points[player], 3)]
    }

    var positionDescription: String {
        if isFinished {
            return "Final: "
                + completedSets.map(\.display).joined(separator: ", ")
        }

        let gameScore = "\(games[0])–\(games[1])"

        if isTiebreak {
            return "Set \(currentSetNumber) · \(gameScore)"
                + " · TB \(points[0])–\(points[1])"
        }

        return "Set \(currentSetNumber) · \(gameScore)"
            + " · \(pointLabel(for: 0))–\(pointLabel(for: 1))"
    }

    mutating func awardPoint(to player: Int) {
        guard !isFinished, (0...1).contains(player) else {
            return
        }

        points[player] += 1
        let opponent = 1 - player

        if isTiebreak {
            if points[player] >= 7,
               points[player] - points[opponent] >= 2 {

                let finalTiebreakPoints = points
                games[player] += 1

                // The receiver of the first tiebreak point serves
                // first in the following set.
                gameServer = 1 - gameServer

                finishSet(tiebreakPoints: finalTiebreakPoints)
            }

            return
        }

        let wonGame =
            points[player] >= 4
            && points[player] - points[opponent] >= 2

        guard wonGame else {
            return
        }

        games[player] += 1
        points = [0, 0]
        gameServer = 1 - gameServer

        let wonSet =
            games[player] >= 6
            && games[player] - games[opponent] >= 2

        if wonSet {
            finishSet(tiebreakPoints: nil)
        }
    }

    private mutating func finishSet(tiebreakPoints: [Int]?) {
        completedSets.append(
            CompletedSet(
                games: games,
                tiebreakPoints: tiebreakPoints
            )
        )

        games = [0, 0]
        points = [0, 0]
    }
}

// MARK: - History

struct PointHistoryItem: Identifiable {
    let event: PointEvent
    let number: Int
    let server: Int
    let scoreBefore: String
    let scoreAfter: String

    var id: UUID { event.id }
}

// MARK: - Match Store

@MainActor
final class MatchStore: ObservableObject {
    private static let storageKey = "TennisScoreTracker.match.v1"

    @Published private(set) var match: MatchData {
        didSet {
            save()
        }
    }

    init() {
        if let data = UserDefaults.standard.data(
            forKey: Self.storageKey
        ),
           let savedMatch = try? JSONDecoder().decode(
               MatchData.self,
               from: data
           ),
           savedMatch.playerNames.count == 2,
           (0...1).contains(savedMatch.firstServer),
           savedMatch.events.allSatisfy({
               (0...1).contains($0.winner)
           }) {
            match = savedMatch
        } else {
            match = MatchData()
        }
    }

    /// Derive the score from the point log.
    /// This makes undo reliable, including across games and sets.
    var score: TennisScore {
        var result = TennisScore(firstServer: match.firstServer)

        for event in match.events {
            result.awardPoint(to: event.winner)
        }

        return result
    }

    var history: [PointHistoryItem] {
        var result = TennisScore(firstServer: match.firstServer)
        var items: [PointHistoryItem] = []

        for (index, event) in match.events.enumerated() {
            let server = result.server
            let before = result.positionDescription

            result.awardPoint(to: event.winner)

            items.append(
                PointHistoryItem(
                    event: event,
                    number: index + 1,
                    server: server,
                    scoreBefore: before,
                    scoreAfter: result.positionDescription
                )
            )
        }

        return items
    }

    func setName(_ name: String, for player: Int) {
        guard match.events.isEmpty else { return }
        match.playerNames[player] = name
    }

    func setFirstServer(_ player: Int) {
        guard match.events.isEmpty else { return }
        match.firstServer = player
    }

    func awardPoint(to player: Int, outcome: PointOutcome) {
        guard (0...1).contains(player) else { return }

        let currentScore = score

        guard !currentScore.isFinished,
              outcome.isAllowed(
                  pointWinner: player,
                  server: currentScore.server
              ) else {
            return
        }

        match.events.append(
            PointEvent(winner: player, outcome: outcome)
        )
    }

    func undo() {
        guard !match.events.isEmpty else { return }
        match.events.removeLast()
    }

    func startNewMatch() {
        var newMatch = MatchData()
        newMatch.playerNames = match.playerNames
        newMatch.firstServer = match.firstServer
        match = newMatch
    }

    func totalPointsWon(by player: Int) -> Int {
        match.events.filter { $0.winner == player }.count
    }

    func statistic(
        _ outcome: PointOutcome,
        for player: Int
    ) -> Int {
        match.events.filter { event in
            guard event.outcome == outcome else {
                return false
            }

            // Errors belong to the point loser.
            // Other categories belong to the point winner.
            let attributedPlayer = event.outcome.isError
                ? 1 - event.winner
                : event.winner

            return attributedPlayer == player
        }.count
    }

    private func save() {
        guard let data = try? JSONEncoder().encode(match) else {
            return
        }

        UserDefaults.standard.set(data, forKey: Self.storageKey)
    }
}

