## 2. Recording service

Create `VoiceRecordingService.swift`.

This layer owns the audio session, recorder, recording files, permissions, and interruption handling.

```swift
import AVFoundation
import Foundation

enum RecordingEvent: Sendable {
    case interrupted
    case failure(String)
}

enum VoiceRecordingError: LocalizedError {
    case microphonePermissionDenied
    case alreadyRecording
    case unableToStart
    case noActiveRecording
    case emptyRecording

    var errorDescription: String? {
        switch self {
        case .microphonePermissionDenied:
            return """
            Microphone access is disabled. Enable it in \
            Settings → Privacy & Security → Microphone.
            """

        case .alreadyRecording:
            return "A recording is already in progress."

        case .unableToStart:
            return "The audio recorder could not start."

        case .noActiveRecording:
            return "There is no active recording to save."

        case .emptyRecording:
            return "The recording did not contain any audio."
        }
    }
}

@MainActor
protocol VoiceRecording: AnyObject {
    var onEvent: ((RecordingEvent) -> Void)? { get set }

    func start() async throws
    func stop() throws -> URL

    /// Stops recording and deletes the unfinished file.
    func cancel()

    /// A normalized display level between 0 and 1.
    func currentLevel() -> Float

    var elapsedTime: TimeInterval { get }
}

@MainActor
final class VoiceRecordingService: NSObject, VoiceRecording {
    var onEvent: ((RecordingEvent) -> Void)?

    private let audioSession = AVAudioSession.sharedInstance()
    private let fileManager: FileManager

    private var recorder: AVAudioRecorder?
    private var activeURL: URL?
    private var interruptionObserver: NSObjectProtocol?
    private var ownsAudioSession = false

    init(fileManager: FileManager = .default) {
        self.fileManager = fileManager
        super.init()
    }

    var elapsedTime: TimeInterval {
        recorder?.currentTime ?? 0
    }

    func start() async throws {
        guard recorder == nil else {
            throw VoiceRecordingError.alreadyRecording
        }

        let permissionGranted =
            await AVAudioApplication.requestRecordPermission()

        // Permission prompts cannot be dismissed programmatically.
        // If the screen disappeared while waiting, do not start recording.
        try Task.checkCancellation()

        guard permissionGranted else {
            throw VoiceRecordingError.microphonePermissionDenied
        }

        // Recheck after suspension.
        guard recorder == nil else {
            throw VoiceRecordingError.alreadyRecording
        }

        do {
            try audioSession.setCategory(
                .record,
                mode: .default
            )

            try audioSession.setActive(true)
            ownsAudioSession = true

            let url = try makeRecordingURL()
            activeURL = url

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100.0,
                AVNumberOfChannelsKey: 1,
                AVEncoderBitRateKey: 128_000,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let newRecorder = try AVAudioRecorder(
                url: url,
                settings: settings
            )

            newRecorder.delegate = self
            newRecorder.isMeteringEnabled = true

            recorder = newRecorder
            observeInterruptions()

            guard newRecorder.prepareToRecord(),
                  newRecorder.record() else {
                throw VoiceRecordingError.unableToStart
            }
        } catch {
            cancel()
            throw error
        }
    }

    func stop() throws -> URL {
        guard let finishedRecorder = recorder,
              let url = activeURL else {
            throw VoiceRecordingError.noActiveRecording
        }

        let duration = finishedRecorder.currentTime

        // Detach before stopping so intentional completion is not treated
        // as an unexpected delegate event.
        recorder = nil
        activeURL = nil
        finishedRecorder.delegate = nil

        finishedRecorder.stop()
        removeInterruptionObserver()
        deactivateAudioSession()

        guard duration > 0,
              fileManager.fileExists(atPath: url.path) else {
            try? fileManager.removeItem(at: url)
            throw VoiceRecordingError.emptyRecording
        }

        return url
    }

    func cancel() {
        let unfinishedRecorder = recorder
        let unfinishedURL = activeURL

        recorder = nil
        activeURL = nil

        unfinishedRecorder?.delegate = nil
        unfinishedRecorder?.stop()

        removeInterruptionObserver()
        deactivateAudioSession()

        if let unfinishedURL {
            try? fileManager.removeItem(at: unfinishedURL)
        }
    }

    func currentLevel() -> Float {
        guard let recorder, recorder.isRecording else {
            return 0
        }

        recorder.updateMeters()

        let decibels = recorder.averagePower(forChannel: 0)

        // Map -60...0 dB into a display-friendly 0...1 range.
        // This is a visual meter, not a calibrated loudness measurement.
        let floor: Float = -60
        let normalized = (decibels - floor) / -floor

        return min(max(normalized, 0), 1)
    }

    private func makeRecordingURL() throws -> URL {
        let documents = try fileManager.url(
            for: .documentDirectory,
            in: .userDomainMask,
            appropriateFor: nil,
            create: true
        )

        let directory = documents.appendingPathComponent(
            "Recordings",
            isDirectory: true
        )

        try fileManager.createDirectory(
            at: directory,
            withIntermediateDirectories: true
        )

        return directory.appendingPathComponent(
            "\(UUID().uuidString).m4a"
        )
    }

    private func observeInterruptions() {
        removeInterruptionObserver()

        interruptionObserver = NotificationCenter.default.addObserver(
            forName: AVAudioSession.interruptionNotification,
            object: audioSession,
            queue: .main
        ) { [weak self] notification in
            guard
                let rawValue = notification.userInfo?[
                    AVAudioSessionInterruptionTypeKey
                ] as? UInt,
                let type = AVAudioSession.InterruptionType(
                    rawValue: rawValue
                ),
                type == .began
            else {
                return
            }

            Task { @MainActor [weak self] in
                guard let self, self.recorder != nil else {
                    return
                }

                self.onEvent?(.interrupted)
            }
        }
    }

    private func removeInterruptionObserver() {
        if let interruptionObserver {
            NotificationCenter.default.removeObserver(
                interruptionObserver
            )
            self.interruptionObserver = nil
        }
    }

    private func deactivateAudioSession() {
        guard ownsAudioSession else {
            return
        }

        ownsAudioSession = false

        // Deactivation failure should not invalidate an already saved file.
        try? audioSession.setActive(
            false,
            options: .notifyOthersOnDeactivation
        )
    }

    private func reportFailure(
        recorderID: ObjectIdentifier,
        message: String
    ) {
        guard let recorder,
              ObjectIdentifier(recorder) == recorderID else {
            return
        }

        cancel()
        onEvent?(.failure(message))
    }
}

// AVAudioRecorder delegate callbacks are not assumed to run on MainActor.
// Transfer only Sendable values into the MainActor task.
extension VoiceRecordingService: AVAudioRecorderDelegate {
    nonisolated func audioRecorderEncodeErrorDidOccur(
        _ recorder: AVAudioRecorder,
        error: (any Error)?
    ) {
        let recorderID = ObjectIdentifier(recorder)
        let message = error?.localizedDescription
            ?? "An audio encoding error occurred."

        Task { @MainActor [weak self] in
            self?.reportFailure(
                recorderID: recorderID,
                message: message
            )
        }
    }

    nonisolated func audioRecorderDidFinishRecording(
        _ recorder: AVAudioRecorder,
        successfully flag: Bool
    ) {
        let recorderID = ObjectIdentifier(recorder)

        Task { @MainActor [weak self] in
            self?.reportFailure(
                recorderID: recorderID,
                message: flag
                    ? "Recording ended unexpectedly."
                    : "The audio recorder could not finish recording."
            )
        }
    }
}
```

