## 3. View model

Create `RecordingViewModel.swift`.

The view model manages UI state and samples the microphone meter at 20 frames per second. It stores recent samples to create a scrolling waveform.

```swift
import Combine
import Foundation

@MainActor
final class RecordingViewModel: ObservableObject {
    enum State: Equatable {
        case idle
        case preparing
        case recording
        case saved
        case failed
    }

    @Published private(set) var state: State = .idle
    @Published private(set) var levels: [Float] =
        Array(repeating: 0, count: 40)

    @Published private(set) var elapsedTime: TimeInterval = 0
    @Published private(set) var savedURL: URL?
    @Published private(set) var errorMessage: String?
    @Published private(set) var informationMessage: String?

    private let recordingService: any VoiceRecording

    private var startTask: Task<Void, Never>?
    private var meteringTask: Task<Void, Never>?

    init(recordingService: any VoiceRecording) {
        self.recordingService = recordingService

        recordingService.onEvent = { [weak self] event in
            self?.handle(event)
        }
    }

    var canStart: Bool {
        state != .preparing && state != .recording
    }

    var canStop: Bool {
        state == .recording
    }

    var statusText: String {
        switch state {
        case .idle:
            return "Ready to record"
        case .preparing:
            return "Preparing microphone…"
        case .recording:
            return "Recording"
        case .saved:
            return "Recording saved"
        case .failed:
            return "Recording unavailable"
        }
    }

    var formattedElapsedTime: String {
        let seconds = Int(elapsedTime)

        return String(
            format: "%02d:%02d",
            seconds / 60,
            seconds % 60
        )
    }

    func startRecording() {
        guard canStart else {
            return
        }

        state = .preparing
        errorMessage = nil
        informationMessage = nil
        savedURL = nil
        elapsedTime = 0
        levels = Array(repeating: 0, count: levels.count)

        startTask = Task { @MainActor [weak self] in
            guard let self else {
                return
            }

            do {
                try await recordingService.start()

                guard !Task.isCancelled else {
                    return
                }

                state = .recording
                startMetering()
            } catch {
                // A cancelled preparation must not overwrite a newer UI state.
                guard !Task.isCancelled else {
                    return
                }

                errorMessage = error.localizedDescription
                state = .failed
            }

            startTask = nil
        }
    }

    func stopRecording() {
        finishRecording()
    }

    /// Called when the recording screen is dismissed.
    /// Active recordings are saved; pending permission requests are cancelled.
    func screenDidDisappear() {
        startTask?.cancel()
        startTask = nil

        if state == .recording {
            finishRecording()
        } else {
            stopMetering()
            recordingService.cancel()

            if state == .preparing {
                state = .idle
            }
        }
    }

    private func finishRecording(
        information: String? = nil
    ) {
        guard state == .recording else {
            return
        }

        stopMetering()
        elapsedTime = recordingService.elapsedTime

        do {
            savedURL = try recordingService.stop()
            informationMessage = information
            state = .saved
        } catch {
            recordingService.cancel()
            errorMessage = error.localizedDescription
            state = .failed
        }
    }

    private func startMetering() {
        stopMetering()

        meteringTask = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                self?.sampleMeter()

                do {
                    try await Task.sleep(
                        for: .milliseconds(50)
                    )
                } catch {
                    return
                }
            }
        }
    }

    private func stopMetering() {
        meteringTask?.cancel()
        meteringTask = nil
    }

    private func sampleMeter() {
        guard state == .recording else {
            return
        }

        levels.removeFirst()
        levels.append(recordingService.currentLevel())
        elapsedTime = recordingService.elapsedTime
    }

    private func handle(_ event: RecordingEvent) {
        switch event {
        case .interrupted:
            // For a voice recorder, saving is generally safer than silently
            // resuming after a phone call or another audio interruption.
            finishRecording(
                information: """
                Recording was interrupted. The captured audio was saved.
                """
            )

        case .failure(let message):
            stopMetering()
            errorMessage = message
            state = .failed
        }
    }
}
```

