## 4. Waveform view

Create `RecordingWaveformView.swift`.

Each bar represents a recent microphone level. The latest level appears on the right.

```swift
import SwiftUI

struct RecordingWaveformView: View {
    let levels: [Float]
    let isRecording: Bool

    @Environment(\.accessibilityReduceMotion)
    private var reduceMotion

    var body: some View {
        GeometryReader { geometry in
            let spacing: CGFloat = 3

            let availableWidth = geometry.size.width
                - spacing * CGFloat(max(levels.count - 1, 0))

            let barWidth = max(
                1,
                availableWidth / CGFloat(max(levels.count, 1))
            )

            HStack(alignment: .center, spacing: spacing) {
                ForEach(levels.indices, id: \.self) { index in
                    Capsule()
                        .fill(
                            isRecording
                                ? Color.accentColor
                                : Color.secondary.opacity(0.4)
                        )
                        .frame(
                            width: barWidth,
                            height: max(
                                4,
                                CGFloat(levels[index])
                                    * geometry.size.height
                            )
                        )
                }
            }
            .frame(
                width: geometry.size.width,
                height: geometry.size.height
            )
            .animation(
                reduceMotion
                    ? nil
                    : .linear(duration: 0.05),
                value: levels
            )
        }
        .accessibilityHidden(true)
    }
}
```

This is an **amplitude waveform-style visualization**, not a frequency-spectrum equalizer. A true frequency spectrum would require audio-buffer analysis, typically using `AVAudioEngine` and an FFT.

