Use a fixed **72-byte UDP packet** containing 18 `(event_index, event_value)` pairs:

- Both fields are signed 16-bit integers.
- Both use **little-endian** byte order.
- Each pair occupies 4 bytes, in the order shown in your example.
- Send one `SYN_REPORT` after applying the whole packet.

Explicit serialization avoids differences in C integer sizes, native byte order, or memory layout.

## Client changes

Keep your enum, initialization, and keyboard handling. Replace `sendControllerState` with:

```zig
const EVENT_COUNT: usize = @intFromEnum(ControllerEvents.START) + 1;
const PACKET_SIZE: usize = EVENT_COUNT * 4;

fn sendControllerState(
    sock: posix.fd_t,
    addr: *const net.Address,
    controllerState: []const i16,
) !void {
    if (controllerState.len != EVENT_COUNT) {
        return error.InvalidControllerStateLength;
    }

    var packet: [PACKET_SIZE]u8 = undefined;

    for (controllerState, 0..) |value, index| {
        const offset = index * 4;

        // Each pair is: int16 index, int16 value, both little-endian.
        mem.writeInt(
            i16,
            packet[offset..][0..2],
            @intCast(index),
            .little,
        );
        mem.writeInt(
            i16,
            packet[offset + 2 ..][0..2],
            value,
            .little,
        );
    }

    const sent = try posix.sendto(
        sock,
        packet[0..],
        0,
        &addr.any,
        addr.getOsSockLen(),
    );

    if (sent != packet.len) {
        return error.IncompleteDatagramSend;
    }
}
```

