After `REGISTERED_EVENTS`, add the packet constants and decoder:

```c
#define EVENT_COUNT \
    (sizeof(REGISTERED_EVENTS) / sizeof(REGISTERED_EVENTS[0]))

#define PAIR_SIZE 4
#define PACKET_SIZE (EVENT_COUNT * PAIR_SIZE)

/* Decode a signed 16-bit little-endian integer without alignment assumptions. */
static int read_i16_le(const uint8_t *p) {
    uint32_t value = (uint32_t)p[0] | ((uint32_t)p[1] << 8);

    return (value & 0x8000u)
        ? (int)value - 65536
        : (int)value;
}
```

