Replace `udp_server` with:

```c
static void udp_server(void) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd,
             (struct sockaddr *)&serv_addr,
             sizeof(serv_addr)) < 0) {
        perror("bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /*
     * One extra byte allows oversized datagrams to be rejected,
     * even if recvfrom truncates them.
     */
    uint8_t buffer[PACKET_SIZE + 1];

    for (;;) {
        ssize_t n = recvfrom(
            sockfd,
            buffer,
            sizeof(buffer),
            0,
            NULL,
            NULL
        );

        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }

            perror("recvfrom");
            break;
        }

        if ((size_t)n != PACKET_SIZE) {
            fprintf(stderr,
                    "Invalid packet size: %zd (expected %zu)\n",
                    n, (size_t)PACKET_SIZE);
            continue;
        }

        int values[EVENT_COUNT];
        int valid = 1;

        /*
         * Validate the complete packet before emitting any events.
         * Require exactly one pair per event, in enum order.
         */
        for (size_t i = 0; i < EVENT_COUNT; ++i) {
            size_t offset = i * PAIR_SIZE;
            int event_index = read_i16_le(buffer + offset);
            int event_value = read_i16_le(buffer + offset + 2);

            if (event_index != (int)i) {
                valid = 0;
                break;
            }

            /* Button state must be released (0) or pressed (1). */
            if (REGISTERED_EVENTS[i].type == EV_KEY &&
                event_value != 0 && event_value != 1) {
                valid = 0;
                break;
            }

            values[i] = event_value;
        }

        if (!valid) {
            fprintf(stderr, "Invalid controller packet\n");
            continue;
        }

        for (size_t i = 0; i < EVENT_COUNT; ++i) {
            int rc = libevdev_uinput_write_event(
                controller,
                REGISTERED_EVENTS[i].type,
                REGISTERED_EVENTS[i].code,
                values[i]
            );

            if (rc < 0) {
                fprintf(stderr,
                        "Failed to write %s: %s\n",
                        REGISTERED_EVENTS[i].name,
                        strerror(-rc));
            }
        }

        /* Commit the entire controller state as one input frame. */
        int rc = libevdev_uinput_write_event(
            controller,
            EV_SYN,
            SYN_REPORT,
            0
        );

        if (rc < 0) {
            fprintf(stderr,
                    "Failed to write SYN_REPORT: %s\n",
                    strerror(-rc));
        }
    }

    close(sockfd);
}
```

For example, the first two pairs in your sample now appear on the wire as:

```text
00 00 FF 7F   # index 0, value 32767
01 00 00 00   # index 1, value 0
```

The original client sent only state values, while the server interpreted the first bytes as two C `int`s. Both sides now agree on field widths, ordering, byte order, and packet length.

**Note:** This server still accepts unauthenticated input from any reachable sender. If only local clients should control it, bind to `INADDR_LOOPBACK` instead of `INADDR_ANY`.

В коде есть несколько причин больших задержек. Главные — **блокирующие `delay()` и редкая обработка micro-ROS**. Кроме того, если micro-ROS работает через `Serial`, отладочная печать использует тот же порт и может мешать обмену с агентом.

При этом **задержка на несколько минут не объясняется только одним `delay(300)`**: нужно проверить также накопление старых команд и состояние связи.

### 1. Управление моторами выполняется только раз в секунду

Весь код управления находится внутри:

```cpp
if (now - lastPrinted > 1000) {
    ...
    // Здесь и управление с пульта, и управление через cmd_vel
}
```

Таким образом, новые значения скорости применяются **не чаще одного раза в секунду**. Ограничивать этим условием нужно только вывод диагностики, а не управление.

### 2. В режиме ROS каждый цикл управления блокируется на 600 мс

В этой части:

```cpp
if (left_reverse) {
    digitalWrite(LEFT_REVERSE_PIN, HIGH);
    delay(300);
} else {
    digitalWrite(LEFT_REVERSE_PIN, LOW);
    delay(300);
}

if (right_reverse) {
    digitalWrite(RIGHT_REVERSE_PIN, HIGH);
    delay(300);
} else {
    digitalWrite(RIGHT_REVERSE_PIN, LOW);
    delay(300);
}
```

Всегда выполняются два `delay(300)`, даже если направление не изменилось.

Затем добавляются:

```cpp
delay(100);
rclc_executor_spin_some(&executor, RCL_MS_TO_NS(100));
```

`spin_some()` может ждать до указанного тайм-аута, если нет данных. Во время обычного `delay()` ваш executor вообще не вызывается, то есть callback подписки не обрабатывается.

Если драйвер мотора требует паузу при реверсе, **не стоит просто убирать защитную паузу**. Правильная последовательность зависит от драйвера, но обычно это:

1. Убрать тягу — записать ноль в DAC.
2. Выдержать необходимую паузу.
3. Переключить направление.
4. Восстановить тягу.

Это нужно делать **только при изменении направления**, желательно неблокирующим автоматом на `millis()`. Сейчас направление переключается при ещё действующем предыдущем значении DAC, а пауза идёт уже после переключения.

### 3. `Serial.print()` может конфликтовать с транспортом micro-ROS

У вас одновременно используются:

```cpp
set_microros_transports();
Serial.begin(115200);
```

и:

```cpp
Serial.print(" Channel values: ");
```

Если в вашей конфигурации `set_microros_transports()` использует этот же `Serial`, то туда поступают и протокольные данные micro-ROS, и обычный текст. Это может нарушать обмен и вызывать ошибки или повторные передачи.

**Первое, что я бы сделал для проверки: полностью убрал все `Serial.print()` и `Serial.println()`.**

Для диагностики используйте отдельный UART с отдельным адаптером, либо другой независимый канал. Если транспорт micro-ROS у вас сетевой, эта причина не относится к нему.

### 4. Возможно получение устаревших команд

Вы создаёте подписку с QoS по умолчанию:

```cpp
rclc_subscription_init_default(...)
```

Обычно это reliable-подписка с историей сообщений. Если `cmd_vel` публикуется часто, а executor обслуживается редко, в зависимости от настроек DDS и транспорта могут возникать очереди, повторные передачи и доставка устаревших команд.

Для управления движением обычно важнее **последняя команда**, чем доставка всех предыдущих.

Можно явно ограничить историю одним сообщением:

```cpp
#include <rmw/qos_profiles.h>

// В setup(), вместо rclc_subscription_init_default():
rmw_qos_profile_t qos = rmw_qos_profile_default;
qos.history = RMW_QOS_POLICY_HISTORY_KEEP_LAST;
qos.depth = 1;
qos.reliability = RMW_QOS_POLICY_RELIABILITY_BEST_EFFORT;

RCCHECK(rclc_subscription_init(
    &subscriber,
    &node,
    ROSIDL_GET_MSG_TYPE_SUPPORT(geometry_msgs, msg, Twist),
    TOPIC_NAME,
    &qos));
```

Best effort допускает потерю сообщений, поэтому это имеет смысл для **регулярно обновляемых команд с тайм-аутом остановки**. Изменение QoS не заменяет исправление блокировок и проблем транспорта.

### Как изменить структуру `loop()`

Обработку связи нужно выполнять часто, а управление и диагностику — по отдельным таймерам:

```cpp
void loop() {
    RCCHECK(rclc_executor_spin_some(
        &executor, RCL_MS_TO_NS(1)));

    uint32_t now = millis();

    static uint32_t lastControl = 0;

    if (now - lastControl >= 20) {  // 50 Гц
        lastControl = now;

        uint16_t ppm[CHANNEL_COUNT];

        noInterrupts();
        for (int i = 0; i < CHANNEL_COUNT; i++) {
            ppm[i] = ppmValues[i];
        }
        interrupts();

        // Здесь выбор режима и расчёт скоростей.
        // Перенесите сюда существующую логику управления,
        // но без блокирующих delay().
        //
        // Реверс, если требуется пауза по документации драйвера,
        // обслуживайте неблокирующим автоматом.
    }

    delay(1);
}
```

Это схема перестройки, а не полная замена: в неё нужно перенести вашу логику управления.

### Обязательно добавьте остановку при потере команд

Сейчас последняя команда сохраняется навсегда. Если связь с Jetson пропадёт, робот продолжит движение.

Добавьте время получения команды:

```cpp
