bool haveCmdVel = false;

void subscription_callback(const void *msgin) {
    const geometry_msgs__msg__Twist *cmd =
        (const geometry_msgs__msg__Twist *)msgin;

    lastCmdVelTime = millis();
    haveCmdVel = true;

    // Далее расчёт скоростей из cmd.
