Below is a **Built-in Render Pipeline** example. It uses one input point per texture pixel; the geometry shader samples that pixel and emits an extruded quad—a box—if its alpha exceeds the cutoff.

- Pixel size controls each quad’s width and height in object space.
- Extrusion is a multiplier: `depth = pixelSize × extrusion`.
- Extrusion extends along local **+Z**.
- The result is unlit and preserves the sampled RGB color.

> Geometry shaders require a supported graphics API/GPU, such as desktop Direct3D 11. They are not supported on Metal and generally are not a good option for mobile.

## 1. Geometry shader

Save as `TexturePixelExtrusion.shader`:

```hlsl
Shader "Custom/TexturePixelExtrusion"
{
    Properties
    {
        _MainTex    ("Texture", 2D) = "white" {}
        _AlphaCutoff("Alpha Cutoff", Range(0, 1)) = 0.01
        _PixelSize  ("Pixel Size", Float) = 0.01
        _Extrusion  ("Extrusion Factor", Float) = 1
    }

    SubShader
    {
        Tags
        {
            "RenderType" = "Opaque"
            "Queue" = "Geometry"
        }

        Pass
        {
            Cull Back
            ZWrite On

            CGPROGRAM
            #pragma target 4.0
            #pragma vertex Vert
            #pragma geometry Geom
            #pragma fragment Frag

            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _AlphaCutoff;
            float _PixelSize;
            float _Extrusion;

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv         : TEXCOORD0;
            };

            struct VertexToGeometry
            {
                float4 positionOS : POSITION;
                float2 uv         : TEXCOORD0;
            };

            struct GeometryToFragment
            {
                float4 positionCS : SV_POSITION;
                float4 color      : COLOR0;
            };

            VertexToGeometry Vert(Attributes input)
            {
                VertexToGeometry output;
                output.positionOS = input.positionOS;
                output.uv = input.uv;
                return output;
            }

            void EmitVertex(
                float3 positionOS,
                float4 color,
                inout TriangleStream<GeometryToFragment> stream)
            {
                GeometryToFragment output;
                output.positionCS =
                    UnityObjectToClipPos(float4(positionOS, 1));

                output.color = color;
                stream.Append(output);
            }

            // a, b, c, d are perimeter-ordered corners.
            // Reorder them into a two-triangle strip.
            void EmitQuad(
                float3 a,
                float3 b,
                float3 c,
                float3 d,
                float4 color,
                inout TriangleStream<GeometryToFragment> stream)
            {
                EmitVertex(a, color, stream);
                EmitVertex(b, color, stream);
                EmitVertex(d, color, stream);
                EmitVertex(c, color, stream);
                stream.RestartStrip();
            }

            // Six faces, four vertices per face.
            [maxvertexcount(24)]
            void Geom(
                point VertexToGeometry input[1],
                inout TriangleStream<GeometryToFragment> stream)
            {
                // Geometry shaders must use an explicit mip level.
                float4 color = tex2Dlod(
                    _MainTex,
                    float4(input[0].uv, 0, 0));

                if (color.a <= _AlphaCutoff)
                    return;

                // Alpha selects whether geometry exists.
                // Surviving pixels render as opaque geometry.
                color.a = 1;

                float3 center = input[0].positionOS.xyz;
                float halfSize = _PixelSize * 0.5;
                float depth = _PixelSize * max(_Extrusion, 0);

                // Base face corners at z = 0.
                float3 p0 = center + float3(-halfSize, -halfSize, 0);
                float3 p1 = center + float3( halfSize, -halfSize, 0);
                float3 p2 = center + float3( halfSize,  halfSize, 0);
                float3 p3 = center + float3(-halfSize,  halfSize, 0);

                // Extruded face corners.
                float3 offset = float3(0, 0, depth);
                float3 q0 = p0 + offset;
                float3 q1 = p1 + offset;
                float3 q2 = p2 + offset;
                float3 q3 = p3 + offset;

                if (depth <= 0)
                {
                    // Flat quad, visible from either side.
                    EmitQuad(p0, p1, p2, p3, color, stream);
                    EmitQuad(p1, p0, p3, p2, color, stream);
                    return;
                }

                // Outward-facing box faces.
                EmitQuad(q0, q1, q2, q3, color, stream); // +Z
                EmitQuad(p1, p0, p3, p2, color, stream); // -Z

                EmitQuad(p0, p1, q1, q0, color, stream); // -Y
                EmitQuad(p3, q3, q2, p2, color, stream); // +Y

                EmitQuad(p0, q0, q3, p3, color, stream); // -X
                EmitQuad(p1, p2, q2, q1, color, stream); // +X
            }

            float4 Frag(GeometryToFragment input) : SV_Target
            {
                return input.color;
            }
            ENDCG
        }
    }

    Fallback Off
}
```

## 2. Generate one input point per texture pixel

A geometry shader cannot independently iterate over all texture pixels. Supply a point mesh containing one point at each pixel’s center.

Save as `TexturePixelExtrusion.cs`:

```csharp
using UnityEngine;
using UnityEngine.Rendering;

[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class TexturePixelExtrusion : MonoBehaviour
{
    public Texture2D texture;
    public Material material;

    [Min(0.0001f)]
    public float pixelSize = 0.01f;

    [Min(0f)]
    public float extrusion = 1f;

    [Range(0f, 1f)]
    public float alphaCutoff = 0.01f;

    private Mesh generatedMesh;
    private MeshRenderer meshRenderer;
    private MaterialPropertyBlock properties;

    private int textureWidth;
    private int textureHeight;
    private float builtPixelSize;

    private void Start()
    {
        if (texture == null || material == null)
        {
            Debug.LogError("Assign a texture and material.", this);
            enabled = false;
            return;
        }

        textureWidth = texture.width;
        textureHeight = texture.height;
        builtPixelSize = Mathf.Max(pixelSize, 0.0001f);

        int count = checked(textureWidth * textureHeight);

        var positions = new Vector3[count];
        var uvs = new Vector2[count];
        var indices = new int[count];

        for (int y = 0; y < textureHeight; y++)
        {
            for (int x = 0; x < textureWidth; x++)
            {
                int index = y * textureWidth + x;

                // Center the complete texture around the local origin.
                positions[index] = new Vector3(
                    (x + 0.5f - textureWidth * 0.5f) * builtPixelSize,
                    (y + 0.5f - textureHeight * 0.5f) * builtPixelSize,
                    0f);

                // Sample the center of this texel.
                uvs[index] = new Vector2(
                    (x + 0.5f) / textureWidth,
                    (y + 0.5f) / textureHeight);

                indices[index] = index;
            }
        }

        generatedMesh = new Mesh
        {
            name = "Texture Pixel Points",
            indexFormat = count > 65535
                ? IndexFormat.UInt32
                : IndexFormat.UInt16
        };

        generatedMesh.vertices = positions;
        generatedMesh.uv = uvs;
        generatedMesh.SetIndices(
            indices, MeshTopology.Points, 0, false);

        GetComponent<MeshFilter>().sharedMesh = generatedMesh;

        meshRenderer = GetComponent<MeshRenderer>();
        meshRenderer.sharedMaterial = material;

        properties = new MaterialPropertyBlock();
        UpdateShaderProperties();
    }

    private void LateUpdate()
    {
        if (generatedMesh != null)
            UpdateShaderProperties();
    }

    private void UpdateShaderProperties()
    {
        float factor = Mathf.Max(extrusion, 0f);
        float depth = builtPixelSize * factor;

        meshRenderer.GetPropertyBlock(properties);
        properties.SetTexture("_MainTex", texture);
        properties.SetFloat("_PixelSize", builtPixelSize);
        properties.SetFloat("_Extrusion", factor);
        properties.SetFloat("_AlphaCutoff", alphaCutoff);
        meshRenderer.SetPropertyBlock(properties);

        // Unity cannot infer the geometry shader's expanded bounds.
        generatedMesh.bounds = new Bounds(
            new Vector3(0f, 0f, depth * 0.5f),
            new Vector3(
                textureWidth * builtPixelSize,
                textureHeight * builtPixelSize,
                Mathf.Max(depth, 0.001f)));
    }

    private void OnDestroy()
    {
        if (generatedMesh != null)
            Destroy(generatedMesh);
    }
}
```

## Setup

1. Create a material using **Custom/TexturePixelExtrusion**.
2. Attach the C# component to an empty GameObject.
3. Assign the texture and material.
4. Set the texture’s **Filter Mode** to **Point** for exact pixel sampling. **Read/Write Enabled is not required**.
5. Set pixel size before entering Play mode; adjust extrusion and alpha cutoff at runtime.

**Notes:** This uses transparency as a geometry mask, not translucent blending. It emits all six faces for every surviving pixel, including internal faces between neighbors. Start with small textures: a fully opaque `256 × 256` texture produces **786,432 triangles**. This minimal shader does not include lighting or a shadow-caster pass.

