For a true inline **“See more”**, `numberOfLines={1}` alone is not enough: React Native may truncate the button too. You need to measure the text and find the longest prefix that fits **together with the button**.

The component below:

- Displays one line when collapsed.
- Only shows “See more” when the text overflows.
- Keeps “See more” inline.
- Handles different widths, font sizes, and accessibility font scaling.
- Avoids splitting emoji and combined Unicode characters.
- Supports controlled or uncontrolled expansion.
- Hides measurement text from accessibility.

### 1. Install the Unicode helper

```bash
npm install graphemer
```

### 2. Create `ExpandableText.tsx`

```tsx
import React, {
  useLayoutEffect,
  useMemo,
  useState,
} from 'react';
import {
  LayoutChangeEvent,
  NativeSyntheticEvent,
  StyleProp,
  StyleSheet,
  Text,
  TextLayoutEventData,
  TextStyle,
  useWindowDimensions,
  View,
  ViewStyle,
} from 'react-native';
import Graphemer from 'graphemer';

const graphemer = new Graphemer();

/**
 * Restrict these styles to typography.
 * Put padding, margins, widths, backgrounds, etc. on containerStyle.
 */
export type ExpandableTextTypography = Pick<
  TextStyle,
  | 'color'
  | 'fontFamily'
  | 'fontSize'
  | 'fontStyle'
  | 'fontWeight'
  | 'fontVariant'
  | 'letterSpacing'
  | 'lineHeight'
  | 'textAlign'
  | 'textDecorationColor'
  | 'textDecorationLine'
  | 'textDecorationStyle'
  | 'textTransform'
  | 'writingDirection'
  | 'includeFontPadding'
>;

export interface ExpandableTextProps {
  text: string;
  moreLabel?: string;

  containerStyle?: StyleProp<ViewStyle>;
  textStyle?: StyleProp<ExpandableTextTypography>;
  moreTextStyle?: StyleProp<ExpandableTextTypography>;

  /** Pass this to control expansion from the parent. */
  expanded?: boolean;
  defaultExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;

  allowFontScaling?: boolean;
  maxFontSizeMultiplier?: number;

  testID?: string;
}

interface CollapsedTextProps {
  text: string;
  width: number;
  moreLabel: string;
  textStyle?: StyleProp<ExpandableTextTypography>;
  moreTextStyle?: StyleProp<ExpandableTextTypography>;
  allowFontScaling: boolean;
  maxFontSizeMultiplier?: number;
  onExpand: () => void;
  testID?: string;
}

type MeasurementState = {
  revision: object;
  phase: 'full' | 'search' | 'done';
  low: number;
  high: number;
  best: number;
  fitsWithoutTruncation: boolean;
};

function initialMeasurement(
  revision: object,
  characterCount: number,
): MeasurementState {
  return {
    revision,
    phase: 'full',
    low: 0,
    high: Math.max(0, characterCount - 1),
    best: 0,
    fitsWithoutTruncation: false,
  };
}

function CollapsedText({
  text,
  width,
  moreLabel,
  textStyle,
  moreTextStyle,
  allowFontScaling,
  maxFontSizeMultiplier,
  onExpand,
  testID,
}: CollapsedTextProps) {
  const { fontScale } = useWindowDimensions();

  const characters = useMemo(
    () => graphemer.splitGraphemes(text),
    [text],
  );

  // Any change that can affect wrapping starts a new measurement.
  const revision = useMemo(
    () => ({}),
    [
      text,
      width,
      moreLabel,
      textStyle,
      moreTextStyle,
      allowFontScaling,
      maxFontSizeMultiplier,
      fontScale,
    ],
  );

  const [measurement, setMeasurement] = useState<MeasurementState>(
    () => initialMeasurement(revision, characters.length),
  );

  useLayoutEffect(() => {
    setMeasurement(current =>
      current.revision === revision
        ? current
        : initialMeasurement(revision, characters.length),
    );
  }, [revision, characters.length]);

  const isCurrent = measurement.revision === revision;
  const isReady = isCurrent && measurement.phase === 'done';

  const showMore =
    isReady && !measurement.fitsWithoutTruncation;

  const middle = Math.floor(
    (measurement.low + measurement.high) / 2,
  );

  function renderTruncatedContent(characterCount: number) {
    const prefix = characters
      .slice(0, characterCount)
      .join('')
      .trimEnd();

    return (
      <>
        {prefix ? `${prefix}\u2026\u00A0` : null}
        <Text style={[styles.more, moreTextStyle]}>
          {moreLabel}
        </Text>
      </>
    );
  }

  function handleMeasurement(
    event: NativeSyntheticEvent<TextLayoutEventData>,
  ) {
    const { lines } = event.nativeEvent;

    const fits =
      lines.length <= 1 &&
      (lines[0]?.width ?? 0) <= width + 0.5;

    setMeasurement(current => {
      // Ignore callbacks from obsolete probes or older inputs.
      if (
        current.revision !== revision ||
        current.phase !== measurement.phase ||
        current.low !== measurement.low ||
        current.high !== measurement.high ||
        current.phase === 'done'
      ) {
        return current;
      }

      if (current.phase === 'full') {
        return fits
          ? {
              ...current,
              phase: 'done',
              fitsWithoutTruncation: true,
            }
          : {
              ...current,
              phase: 'search',
            };
      }

      const candidate = Math.floor(
        (current.low + current.high) / 2,
      );

      const low = fits ? candidate + 1 : current.low;
      const high = fits ? current.high : candidate - 1;
      const best = fits ? candidate : current.best;

      return {
        ...current,
        low,
        high,
        best,
        phase: low > high ? 'done' : 'search',
      };
    });
  }

  return (
    <>
      <Text
        testID={testID}
        style={[styles.text, textStyle]}
        numberOfLines={1}
        ellipsizeMode="tail"
        allowFontScaling={allowFontScaling}
        maxFontSizeMultiplier={maxFontSizeMultiplier}
        accessible
        accessibilityRole={showMore ? 'button' : undefined}
        accessibilityLabel={text}
        accessibilityHint={showMore ? moreLabel : undefined}
        accessibilityState={
          showMore ? { expanded: false } : undefined
        }
        onPress={showMore ? onExpand : undefined}
      >
        {showMore
          ? renderTruncatedContent(measurement.best)
          : text}
      </Text>

      {isCurrent && measurement.phase !== 'done' && (
        <View
          style={styles.measurement}
          pointerEvents="none"
          accessible={false}
          accessibilityElementsHidden
          importantForAccessibility="no-hide-descendants"
        >
          <Text
            // Remount each probe so native layout is measured even
            // when adjacent candidates produce identical strings.
            key={[
              measurement.phase,
              measurement.low,
              measurement.high,
            ].join(':')}
            style={[styles.text, textStyle]}
            allowFontScaling={allowFontScaling}
            maxFontSizeMultiplier={maxFontSizeMultiplier}
            onTextLayout={handleMeasurement}
            accessible={false}
          >
            {measurement.phase === 'full'
              ? text
              : renderTruncatedContent(middle)}
          </Text>
        </View>
      )}
    </>
  );
}

export function ExpandableText({
  text,
  moreLabel = 'See more',
  containerStyle,
  textStyle,
  moreTextStyle,
  expanded,
  defaultExpanded = false,
  onExpandedChange,
  allowFontScaling = true,
  maxFontSizeMultiplier,
  testID,
}: ExpandableTextProps) {
  const [internalExpanded, setInternalExpanded] =
    useState(defaultExpanded);

  const [width, setWidth] = useState(0);

  const isExpanded = expanded ?? internalExpanded;
  const label = moreLabel.trim() || 'See more';

  function handleLayout(event: LayoutChangeEvent) {
    const nextWidth = event.nativeEvent.layout.width;

    setWidth(current =>
      current === nextWidth ? current : nextWidth,
    );
  }

  function handleExpand() {
    if (isExpanded) {
      return;
    }

    if (expanded === undefined) {
      setInternalExpanded(true);
    }

    onExpandedChange?.(true);
  }

  return (
    <View style={containerStyle}>
      {/* Measure inside the container so its padding is excluded. */}
      <View
        style={styles.content}
        onLayout={handleLayout}
      >
        {isExpanded || width <= 0 ? (
          <Text
            testID={testID}
            style={[styles.text, textStyle]}
            numberOfLines={isExpanded ? undefined : 1}
            ellipsizeMode="tail"
            allowFontScaling={allowFontScaling}
            maxFontSizeMultiplier={maxFontSizeMultiplier}
          >
            {text}
          </Text>
        ) : (
          <CollapsedText
            text={text}
            width={width}
            moreLabel={label}
            textStyle={textStyle}
            moreTextStyle={moreTextStyle}
            allowFontScaling={allowFontScaling}
            maxFontSizeMultiplier={maxFontSizeMultiplier}
            onExpand={handleExpand}
            testID={testID}
          />
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  content: {
    alignSelf: 'stretch',
    position: 'relative',
  },
  text: {
    fontSize: 16,
    lineHeight: 24,
    color: '#111827',
  },
  more: {
    color: '#2563EB',
    fontWeight: '600',
  },
  measurement: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    opacity: 0,
  },
});
```

