  #taskbar {
    position: fixed;
    bottom: 0;
    width: 100%;
    height: var(--taskbar-height);
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 7px 10px;
    background: #101a2bea;
    border-top: 1px solid var(--border);
    backdrop-filter: blur(18px);
    z-index: 100000;
  }

  #start-button { background: #315994; font-weight: 700; }
  #tasks { display: flex; gap: 6px; flex: 1; overflow-x: auto; }
  .task { white-space: nowrap; }
  .task.active { border-bottom: 3px solid var(--accent); }
  #clock { white-space: nowrap; color: var(--muted); padding: 0 6px; }

  #start-menu {
    position: fixed;
    bottom: 62px;
    left: 10px;
    width: 245px;
    padding: 14px;
    background: #172238f5;
    border: 1px solid var(--border);
    border-radius: 12px;
    box-shadow: 0 15px 50px #0008;
    z-index: 100001;
  }

  #start-menu[hidden] { display: none; }
  #start-menu h3 { margin: 2px 8px 12px; }
  #start-menu button {
    display: block;
    text-align: left;
    width: 100%;
    margin: 5px 0;
    background: transparent;
  }

  .window {
    position: absolute;
    display: flex;
    flex-direction: column;
    width: 650px;
    height: 420px;
    min-width: 280px;
    min-height: 200px;
    max-width: 100%;
    max-height: 100%;
    background: var(--panel);
    border: 1px solid #ffffff30;
    border-radius: 11px;
    box-shadow: 0 20px 60px #0007;
    overflow: hidden;
    resize: both;
  }

  .window[hidden] { display: none; }
  .window.focused { border-color: #6ba7ff99; }

  .window.maximized {
    inset: 0 !important;
    width: 100% !important;
    height: 100% !important;
    border-radius: 0;
    resize: none;
  }

  .titlebar {
    height: 40px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-left: 12px;
    background: #ffffff08;
    border-bottom: 1px solid var(--border);
    cursor: grab;
    user-select: none;
    touch-action: none;
  }

  .window-title {
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    padding-right: 8px;
  }

  .window-controls { display: flex; height: 100%; }
  .window-controls button {
    width: 39px;
    border: 0;
    border-radius: 0;
    padding: 0;
    background: transparent;
  }

  .window-controls .close:hover { background: #c74455; }
  .window-body { flex: 1; min-height: 0; overflow: auto; }

  .toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    padding: 10px;
    border-bottom: 1px solid var(--border);
  }

  .file-list { padding: 10px; display: grid; gap: 5px; }
  .file-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    text-align: left;
    gap: 12px;
    padding: 12px;
    background: transparent;
  }

  .file-row.selected { background: #6ba7ff25; border-color: var(--accent); }
  .file-row small { color: var(--muted); white-space: nowrap; }
  .file-name { overflow-wrap: anywhere; }
  .hint { color: var(--muted); padding: 12px; margin: 0; }

  .editor { display: flex; flex-direction: column; height: 100%; }
  .editor textarea {
    flex: 1;
    min-height: 0;
    resize: none;
    border: 0;
    border-radius: 0;
    padding: 15px;
    line-height: 1.6;
    font-family: ui-monospace, monospace;
    outline-offset: -2px;
  }

  .status { padding: 7px 12px; color: var(--muted); font-size: 12px; }

  .terminal {
    height: 100%;
    display: flex;
    flex-direction: column;
    padding: 12px;
    background: #080f1b;
    font: 13px/1.6 ui-monospace, monospace;
  }

  .terminal-output {
    flex: 1;
    overflow: auto;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    margin: 0 0 8px;
    color: #b5efce;
  }

  .terminal form { display: flex; gap: 8px; align-items: center; }
  .terminal input {
    flex: 1;
    min-width: 0;
    background: transparent;
    border: 0;
    padding: 4px;
    font: inherit;
  }

  .page { padding: 22px; line-height: 1.7; }
  .page h2 { margin-top: 0; }
  .page code { color: #a6caff; }

  #toast {
    position: fixed;
    left: 50%;
    bottom: 70px;
    transform: translateX(-50%);
    padding: 10px 18px;
    border-radius: 9px;
    background: #253c5e;
    box-shadow: 0 5px 25px #0006;
    z-index: 100002;
    max-width: 90vw;
    text-align: center;
  }

  #toast[hidden] { display: none; }

  @media (max-width: 520px) {
    #clock { font-size: 12px; }
    .task { max-width: 100px; overflow: hidden; text-overflow: ellipsis; }
    .window { min-width: 240px; }
  }
</style>
</head>
<body>
<main id="desktop" aria-label="Desktop">
  <div id="desktop-icons"></div>
</main>

<nav id="start-menu" aria-label="Applications" hidden>
  <h3>✨ MiniOS</h3>
</nav>

<footer id="taskbar">
  <button id="start-button" aria-expanded="false">▦ Start</button>
  <div id="tasks"></div>
  <time id="clock"></time>
</footer>

<div id="toast" role="status" hidden></div>

<script>
"use strict";

const $ = selector => document.querySelector(selector);
const desktop = $("#desktop");
const windows = new Map();
const STORAGE_KEY = "minios.files.v1";

let topZ = 10;
let activeApp = null;
let selectedFile = null;
let editorFile = null;
let editorDirty = false;
let toastTimer;

function uid() {
  return globalThis.crypto?.randomUUID?.()
    || Date.now().toString(36) + Math.random().toString(36).slice(2);
}

function loadFiles() {
  try {
    const stored = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (Array.isArray(stored) && stored.every(file =>
      file && typeof file.id === "string" &&
      typeof file.name === "string" &&
      typeof file.content === "string"
    )) return stored;
  } catch {}
  return [{
    id: uid(),
    name: "Welcome.txt",
    content:
`Welcome to MiniOS!

• Click a desktop icon or use the Start menu.
• Drag window title bars to move windows.
• Double-click a title bar to maximize.
• Resize windows using their bottom-right corner.
• Open Files to create, rename, download, or delete text files.
• Press Ctrl+S / Cmd+S in the editor to save.
• Open Terminal and type help.

Your virtual files stay in this browser using localStorage.
They are not files on your real operating system.`
  }];
}

let files = loadFiles();

function toast(message) {
  $("#toast").textContent = message;
  $("#toast").hidden = false;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => $("#toast").hidden = true, 2800);
}

// Commit only when browser storage succeeds.
function commitFiles(nextFiles) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(nextFiles));
    files = nextFiles;
    renderFiles();
    return true;
  } catch {
    toast("Unable to save: browser storage is unavailable or full.");
    return false;
  }
}

function validName(name, exceptId = null) {
  if (!name || /[\\/\x00-\x1f]/.test(name)) {
    toast("Enter a name without slashes or control characters.");
    return false;
  }
  if (files.some(f => f.name === name && f.id !== exceptId)) {
    toast("A file with that name already exists.");
    return false;
  }
  return true;
}

function createFile(name, content = "") {
  name = name.trim();
  if (!validName(name)) return null;
  const file = { id: uid(), name, content };
  return commitFiles([...files, file]) ? file : null;
}

function setStart(open) {
  $("#start-menu").hidden = !open;
  $("#start-button").setAttribute("aria-expanded", String(open));
}

$("#start-button").onclick = () => setStart($("#start-menu").hidden);

document.addEventListener("pointerdown", event => {
  if (!event.target.closest("#start-menu, #start-button")) setStart(false);
});

function focusWindow(id) {
  const item = windows.get(id);
  if (!item) return;
  item.el.hidden = false;
  item.el.style.zIndex = ++topZ;
  activeApp = id;
  windows.forEach((window, key) => {
    window.el.classList.toggle("focused", key === id);
    window.task.classList.toggle("active", key === id);
  });
}

function focusTopWindow() {
  const visible = [...windows.entries()]
    .filter(([, item]) => !item.el.hidden)
    .sort((a, b) => Number(b[1].el.style.zIndex) - Number(a[1].el.style.zIndex));
  activeApp = null;
  windows.forEach(item => {
    item.el.classList.remove("focused");
    item.task.classList.remove("active");
  });
  if (visible.length) focusWindow(visible[0][0]);
}

function maximize(item) {
  item.el.classList.toggle("maximized");
}

function makeWindow(id, title, width = 650, height = 420) {
  if (windows.has(id)) {
    focusWindow(id);
    return windows.get(id);
  }

  const el = document.createElement("section");
  el.className = "window";
  el.setAttribute("role", "dialog");
  el.setAttribute("aria-label", title);
  el.style.width = Math.min(width, desktop.clientWidth) + "px";
  el.style.height = Math.min(height, desktop.clientHeight) + "px";

  const offset = windows.size * 26;
  el.style.left = Math.max(0,
    Math.min(130 + offset, desktop.clientWidth - Math.min(width, desktop.clientWidth))
  ) + "px";
  el.style.top = Math.max(0,
    Math.min(45 + offset, desktop.clientHeight - Math.min(height, desktop.clientHeight))
  ) + "px";

  el.innerHTML = `
    <header class="titlebar">
      <span class="window-title"></span>
      <div class="window-controls">
        <button data-action="minimize" aria-label="Minimize">—</button>
        <button data-action="maximize" aria-label="Toggle maximize">□</button>
        <button data-action="close" class="close" aria-label="Close">×</button>
      </div>
    </header>
    <div class="window-body"></div>`;

  el.querySelector(".window-title").textContent = title;

  const task = document.createElement("button");
  task.className = "task";
  task.textContent = title;
  $("#tasks").append(task);
  desktop.append(el);

  const item = { el, task, body: el.querySelector(".window-body") };
  windows.set(id, item);

  el.addEventListener("pointerdown", () => focusWindow(id));
  task.onclick = () => {
    if (activeApp === id && !el.hidden) {
      el.hidden = true;
      focusTopWindow();
    } else {
      focusWindow(id);
    }
  };

  el.querySelector('[data-action="minimize"]').onclick = () => {
    el.hidden = true;
    focusTopWindow();
  };
  el.querySelector('[data-action="maximize"]').onclick = () => maximize(item);
  el.querySelector('[data-action="close"]').onclick = () => {
    if (id === "editor" && editorDirty &&
        !confirm("Discard unsaved changes?")) return;
    el.remove();
    task.remove();
    windows.delete(id);
    if (id === "editor") {
      editorFile = null;
      editorDirty = false;
    }
    focusTopWindow();
  };

  const titlebar = el.querySelector(".titlebar");
  titlebar.ondblclick = event => {
    if (!event.target.closest("button")) maximize(item);
  };

  titlebar.onpointerdown = event => {
    if (event.button !== 0 || event.target.closest("button") ||
        el.classList.contains("maximized")) return;

    const startX = event.clientX;
    const startY = event.clientY;
    const left = el.offsetLeft;
    const top = el.offsetTop;
    titlebar.setPointerCapture(event.pointerId);

    titlebar.onpointermove = move => {
      el.style.left = Math.max(0, Math.min(
        desktop.clientWidth - el.offsetWidth,
        left + move.clientX - startX
      )) + "px";
      el.style.top = Math.max(0, Math.min(
        desktop.clientHeight - 40,
        top + move.clientY - startY
      )) + "px";
    };

    const stop = () => {
      titlebar.onpointermove = null;
      titlebar.onpointerup = null;
      titlebar.onpointercancel = null;
    };
    titlebar.onpointerup = stop;
    titlebar.onpointercancel = stop;
  };

  focusWindow(id);
  return item;
}

function selected() {
  const file = files.find(f => f.id === selectedFile);
  if (!file) toast("Select a file first.");
  return file;
}

function openFiles() {
  if (windows.has("files")) return focusWindow("files");
  const { body } = makeWindow("files", "📁 Files");

  body.innerHTML = `
    <div class="toolbar">
      <button data-file-action="new">＋ New</button>
      <button data-file-action="open">Open</button>
      <button data-file-action="rename">Rename</button>
      <button data-file-action="download">Download</button>
      <button data-file-action="delete">Delete</button>
    </div>
    <p class="hint">Virtual disk / Documents — double-click a file to edit.</p>
    <div class="file-list"></div>`;

  body.querySelector('[data-file-action="new"]').onclick = () => {
    const name = prompt("New file name:", "Untitled.txt");
    if (name === null) return;
    const file = createFile(name);
    if (file) {
      selectedFile = file.id;
      renderFiles();
      openEditor(file.id);
    }
  };

  body.querySelector('[data-file-action="open"]').onclick = () => {
    const file = selected();
    if (file) openEditor(file.id);
  };

  body.querySelector('[data-file-action="rename"]').onclick = () => {
    const file = selected();
    if (!file) return;
    const answer = prompt("Rename file:", file.name);
    if (answer === null) return;
    const name = answer.trim();
    if (!validName(name, file.id)) return;
    if (commitFiles(files.map(f => f.id === file.id ? { ...f, name } : f))) {
      updateEditorTitle();
    }
  };

  body.querySelector('[data-file-action="delete"]').onclick = () => {
    const file = selected();
    if (file && confirm(`Delete "${file.name}"?`)) removeFile(file);
  };

  body.querySelector('[data-file-action="download"]').onclick = () => {
    const file = selected();
    if (!file) return;
    const url = URL.createObjectURL(
      new Blob([file.content], { type: "text/plain;charset=utf-8" })
    );
    const link = document.createElement("a");
    link.href = url;
    link.download = file.name;
    document.body.append(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  renderFiles();
}

function removeFile(file) {
  if (!commitFiles(files.filter(f => f.id !== file.id))) return false;
  if (editorFile === file.id) {
    editorFile = null;
    editorDirty = true; // Keep the editor's buffer recoverable.
    updateEditorTitle();
  }
  return true;
}

function renderFiles() {
  const list = windows.get("files")?.body.querySelector(".file-list");
  if (!list) return;
  list.replaceChildren();

  if (!files.length) {
    const empty = document.createElement("p");
    empty.className = "hint";
    empty.textContent = "No files yet. Create your first text file.";
    list.append(empty);
  }

  [...files].sort((a, b) => a.name.localeCompare(b.name)).forEach(file => {
    const row = document.createElement("button");
    row.className = "file-row";
    row.classList.toggle("selected", file.id === selectedFile);
    row.setAttribute("aria-pressed", String(file.id === selectedFile));

    const name = document.createElement("span");
    name.className = "file-name";
    name.textContent = "📄 " + file.name;

    const size = document.createElement("small");
    size.textContent = new Blob([file.content]).size + " bytes";

    row.append(name, size);
    row.onclick = () => {
      selectedFile = file.id;
      renderFiles();
    };
    row.ondblclick = () => openEditor(file.id);
    row.onkeydown = event => {
      if (event.key === "Enter") {
        event.preventDefault();
        openEditor(file.id);
      }
    };
    list.append(row);
  });
}

function updateEditorTitle() {
  const item = windows.get("editor");
  if (!item) return;
  const name = files.find(f => f.id === editorFile)?.name || "Untitled";
  item.el.querySelector(".window-title").textContent =
    `📝 ${name}${editorDirty ? " •" : ""} — Text Editor`;
}

function openEditor(fileId) {
  const existing = windows.get("editor");
  if (existing && fileId === undefined) {
    focusWindow("editor");
    existing.body.querySelector("textarea").focus();
    return;
  }

  if (existing && editorFile === fileId) {
    focusWindow("editor");
    return;
  }

  if (existing && editorDirty && !confirm("Discard unsaved changes?")) return;

  const item = existing || makeWindow("editor", "📝 Text Editor");
  if (!existing) {
    item.body.innerHTML = `
      <div class="editor">
        <div class="toolbar">
          <button data-editor-action="save">💾 Save</button>
          <button data-editor-action="new">New document</button>
        </div>
        <textarea aria-label="Document contents" spellcheck="false"></textarea>
        <div class="status">Ctrl+S / Cmd+S to save • Stored in this browser</div>
      </div>`;

    item.body.querySelector('[data-editor-action="save"]').onclick = saveEditor;
    item.body.querySelector('[data-editor-action="new"]').onclick = () => {
      if (editorDirty && !confirm("Discard unsaved changes?")) return;
      editorFile = null;
      editorDirty = false;
      item.body.querySelector("textarea").value = "";
      updateEditorTitle();
    };
    item.body.querySelector("textarea").oninput = () => {
      editorDirty = true;
      updateEditorTitle();
    };
  }

  const file = files.find(f => f.id === fileId);
  editorFile = file?.id || null;
  editorDirty = false;
  item.body.querySelector("textarea").value = file?.content || "";
  updateEditorTitle();
  focusWindow("editor");
  item.body.querySelector("textarea").focus();
}

function saveEditor() {
  const item = windows.get("editor");
  if (!item) return;
  const content = item.body.querySelector("textarea").value;
  const file = files.find(f => f.id === editorFile);

  if (file) {
    if (!commitFiles(files.map(f =>
      f.id === file.id ? { ...f, content } : f
    ))) return;
  } else {
    const name = prompt("Save as:", "Untitled.txt");
    if (name === null) return;
    const created = createFile(name, content);
    if (!created) return;
    editorFile = created.id;
  }

  editorDirty = false;
  updateEditorTitle();
  toast("File saved.");
}

document.addEventListener("keydown", event => {
  if ((event.ctrlKey || event.metaKey) &&
      event.key.toLowerCase() === "s" && activeApp === "editor") {
    event.preventDefault();
    saveEditor();
  }
  if (event.key === "Escape") setStart(false);
});

function openTerminal() {
  if (windows.has("terminal")) {
    focusWindow("terminal");
    windows.get("terminal").body.querySelector("input").focus();
    return;
  }

  const { body } = makeWindow("terminal", "⌨ Terminal", 610, 370);
  body.innerHTML = `
    <div class="terminal">
      <pre class="terminal-output" aria-live="polite"></pre>
      <form autocomplete="off">
        <span>guest@minios:~$</span>
        <input aria-label="Terminal command" spellcheck="false">
      </form>
    </div>`;

  const output = body.querySelector("pre");
  const input = body.querySelector("input");
  const print = text => {
    output.textContent += text + "\n";
    output.scrollTop = output.scrollHeight;
  };

  print("MiniOS Terminal\nType help for commands. Filenames are case-sensitive.\n");

  body.querySelector("form").onsubmit = event => {
    event.preventDefault();
    const line = input.value.trim();
    input.value = "";
    if (!line) return;

    print("$ " + line);
    const [, rawCommand, remainder = ""] = line.match(/^(\S+)(?:\s+(.*))?$/);
    const command = rawCommand.toLowerCase();
    const arg = remainder.trim();
    const file = files.find(f => f.name === arg);

    switch (command) {
      case "help":
        print(
`help          Show this help
ls            List virtual files
cat NAME      Read a file
touch NAME    Create an empty file
rm NAME       Delete a file (asks for confirmation)
edit NAME     Open a file in the editor
echo TEXT     Print text
date          Show date and time
whoami        Show current user
clear         Clear terminal
about         About MiniOS

Use the complete filename after a command; spaces are supported.
This terminal does not execute real system commands.`
        );
        break;
      case "ls":
        print(files.map(f => f.name).join("\n") || "(empty)");
        break;
      case "cat":
        print(file ? file.content : "File not found.");
        break;
      case "touch":
        if (!arg) print("Usage: touch NAME");
        else if (file) print("File already exists.");
        else print(createFile(arg) ? "File created." : "Could not create file.");
        break;
      case "rm":
        if (!file) print("File not found.");
        else if (confirm(`Delete "${file.name}"?`)) {
          print(removeFile(file) ? "File deleted." : "Could not delete file.");
        } else print("Canceled.");
        break;
      case "edit":
        if (file) openEditor(file.id);
        else print("File not found.");
        break;
      case "echo": print(arg); break;
      case "date": print(new Date().toLocaleString()); break;
      case "whoami": print("guest"); break;
      case "clear": output.textContent = ""; break;
      case "about": print("MiniOS 1.0 — a browser-based desktop simulation."); break;
      default: print(`Unknown command: ${rawCommand}. Type help.`);
    }
  };

  input.focus();
}

function openSettings() {
  if (windows.has("settings")) return focusWindow("settings");
  const { body } = makeWindow("settings", "⚙ Settings", 420, 280);
  body.innerHTML = `
    <div class="page">
      <h2>Personalization</h2>
      <p>Choose your desktop wallpaper.</p>
      <button data-theme="ocean">🌌 Ocean</button>
      <button data-theme="sunset">🌇 Sunset</button>
      <p class="hint">Virtual files and preferences are saved locally.
      Clearing browser data removes them.</p>
    </div>`;

  body.querySelectorAll("[data-theme]").forEach(button => {
    button.onclick = () => {
      const theme = button.dataset.theme;
      document.body.classList.toggle("sunset", theme === "sunset");
      try {
        localStorage.setItem("minios.theme", theme);
      } catch {
        toast("Theme changed, but could not be saved.");
      }
    };
  });
}

function openAbout() {
  if (windows.has("about")) return focusWindow("about");
  const { body } = makeWindow("about", "✨ About MiniOS", 450, 330);
  body.innerHTML = `
    <div class="page">
      <h2>✨ MiniOS</h2>
      <p>A tiny desktop built with HTML, CSS, and JavaScript.</p>
      <ul>
        <li>Draggable, resizable, minimizable windows</li>
        <li>Virtual text files with local persistence</li>
        <li>Text editor and simulated terminal</li>
        <li>Taskbar, application launcher, and themes</li>
      </ul>
      <p>This demo cannot run native programs or access your real
      filesystem. Download files to keep a separate backup.</p>
    </div>`;
}

const apps = [
  { name: "Files", icon: "📁", open: openFiles },
  { name: "Text Editor", icon: "📝", open: () => openEditor() },
  { name: "Terminal", icon: "⌨", open: openTerminal },
  { name: "Settings", icon: "⚙", open: openSettings },
  { name: "About", icon: "✨", open: openAbout }
];

apps.forEach(app => {
  const icon = document.createElement("button");
  icon.className = "desktop-icon";

  const symbol = document.createElement("span");
  symbol.textContent = app.icon;
  symbol.setAttribute("aria-hidden", "true");

  const label = document.createElement("span");
