  $("#desktop-icons").append(icon);

  const menuItem = document.createElement("button");
  menuItem.textContent = `${app.icon}  ${app.name}`;
  menuItem.onclick = () => {
    setStart(false);
    app.open();
  };
  $("#start-menu").append(menuItem);
});

function updateClock() {
