This version reads CSV columns `ip`, `device_id`, and `hostname`, uses at most **12 worker threads**, writes every result to a new CSV, and keeps the console summaries.

**Input CSV (`devices.csv`):**
```csv
ip,device_id,hostname
192.168.1.10,device-001,server01
192.168.1.11,device-002,server02
```

**Run:**
```bash
python check_ssh.py devices.csv results.csv --port 22 --timeout 2
```

```python
import argparse
import csv
import ipaddress
import socket
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

MAX_THREADS = 12

VULNERABLE_VERSIONS = {
    f"SSH-2.0-OpenSSH_{version}p1"
    for version in (
        "8.5", "8.6", "8.7", "8.8", "8.9",
        "9.0", "9.1", "9.2", "9.3", "9.4",
        "9.5", "9.6", "9.7",
    )
}

OUTPUT_FIELDS = [
    "ip", "device_id", "hostname", "port", "status", "banner", "message"
]


def is_port_open(ip, port, timeout):
    try:
        with socket.create_connection((ip, port), timeout=timeout):
            return True
    except OSError:
        return False


def get_ssh_banner(ip, port, timeout):
    try:
        with socket.create_connection((ip, port), timeout=timeout) as sock:
            return sock.recv(1024).decode(
                "utf-8", errors="replace"
            ).strip()
    except OSError as exc:
        return str(exc)


def check_vulnerability(device, port, timeout):
    ip = device["ip"]

    result = {
        **device,
        "port": port,
        "status": "",
        "banner": "",
        "message": "",
    }

    try:
        ipaddress.ip_address(ip)
    except ValueError:
        result.update(
            status="failed",
            message=f"Invalid IP address: {ip!r}",
        )
        return result

    if not is_port_open(ip, port, timeout):
        result.update(
            status="closed",
            message="Port closed or unreachable",
        )
        return result

    banner = get_ssh_banner(ip, port, timeout)

    if "SSH-2.0-OpenSSH" not in banner:
        result.update(
            status="failed",
            message=f"Failed to retrieve SSH banner: {banner}",
        )
        return result

    result["banner"] = banner

    if any(version in banner for version in VULNERABLE_VERSIONS):
        result["status"] = "vulnerable"
    else:
        result["status"] = "not_vulnerable"

    result["message"] = f"(running {banner})"
    return result


def read_devices(csv_path):
    with open(csv_path, "r", newline="", encoding="utf-8-sig") as file:
        reader = csv.DictReader(file)
        required = {"ip", "device_id", "hostname"}
        missing = required - set(reader.fieldnames or [])

        if missing:
            raise ValueError(
                f"Missing required CSV columns: {', '.join(sorted(missing))}"
            )

        return [
            {
                "ip": (row.get("ip") or "").strip(),
                "device_id": (row.get("device_id") or "").strip(),
                "hostname": (row.get("hostname") or "").strip(),
            }
            for row in reader
        ]


def device_label(result):
    return (
        f"{result['ip']} "
        f"[device_id={result['device_id']}, "
        f"hostname={result['hostname']}]"
    )


def main():
    parser = argparse.ArgumentParser(
        description="Check OpenSSH banners for potentially vulnerable versions."
    )
    parser.add_argument(
        "input_csv",
        help="Input CSV with columns: ip,device_id,hostname.",
    )
    parser.add_argument(
        "output_csv",
        help="New CSV file for results; must not already exist.",
    )
    parser.add_argument(
        "--port",
        type=int,
        default=22,
        help="Port number to check (default: 22).",
    )
    parser.add_argument(
        "-t", "--timeout",
        type=float,
        default=1.0,
        help="Connection timeout in seconds (default: 1).",
    )

    args = parser.parse_args()

    if not 1 <= args.port <= 65535:
        parser.error("--port must be between 1 and 65535.")
    if args.timeout <= 0:
        parser.error("--timeout must be greater than zero.")
    if Path(args.input_csv).resolve() == Path(args.output_csv).resolve():
        parser.error("Input and output CSV paths must be different.")

    try:
        devices = read_devices(args.input_csv)
    except (OSError, ValueError, csv.Error) as exc:
        parser.error(f"Cannot read input CSV: {exc}")

    closed_ports = 0
    not_vulnerable = []
    vulnerable = []
    failed = 0

    print(
        f"Scanning {len(devices)} targets on port {args.port} "
        f"with at most {MAX_THREADS} worker threads..."
    )

    try:
        # Exclusive creation prevents overwriting an existing file.
        with open(
            args.output_csv, "x", newline="", encoding="utf-8"
        ) as output_file:
            writer = csv.DictWriter(output_file, fieldnames=OUTPUT_FIELDS)
            writer.writeheader()

            with ThreadPoolExecutor(max_workers=MAX_THREADS) as executor:
                results = executor.map(
                    lambda device: check_vulnerability(
                        device, args.port, args.timeout
                    ),
                    devices,
                )

                # Only the main thread writes CSV and prints.
                # executor.map preserves input row order.
                for result in results:
                    writer.writerow(result)

                    status = result["status"]
                    if status == "closed":
                        closed_ports += 1
                    elif status == "vulnerable":
                        vulnerable.append(result)
                    elif status == "not_vulnerable":
                        not_vulnerable.append(result)
                    else:
                        failed += 1
                        print(
                            f"⚠️ [!] Server at {device_label(result)} "
                            f"port {args.port}: {result['message']}"
                        )

    except (OSError, csv.Error) as exc:
        parser.exit(1, f"Error writing results CSV: {exc}\n")

    print(f"\n🛡️ Servers not flagged by banner: {len(not_vulnerable)}\n")
    for result in not_vulnerable:
        print(
            f"   [+] Server at {device_label(result)} "
            f"{result['message']}"
        )

    print(f"\n🚨 Servers likely vulnerable: {len(vulnerable)}\n")
    for result in vulnerable:
        print(
            f"   [+] Server at {device_label(result)} "
            f"{result['message']}"
        )

    print(
        f"\n🔒 Servers with port {args.port} closed "
        f"or unreachable: {closed_ports}"
    )
    print(f"\n⚠️ Failed checks: {failed}")
    print(f"\n📊 Total scanned targets: {len(devices)}")
    print(f"\n💾 Results written to: {args.output_csv}\n")


if __name__ == "__main__":
    main()
```

**Note:** This retains your version-matching logic. Banner checks cannot confirm vulnerability or safety: vendors may backport fixes without changing the upstream version. The CSV status `not_vulnerable` therefore means only “not matched by this version list.”

Your example skips weekends: **27/06/2024 + 4 working days = 03/07/2024**. In Laravel, you can use Carbon’s `addWeekdays()` to calculate this.

```php
use Carbon\Carbon;

function calculateProcessDates(
    string $orderCreatedDate,
    array $processes
): array {
    // Process items in sequence order.
    usort($processes, function ($a, $b) {
        return $a['sequence'] <=> $b['sequence'];
    });

    $startDate = Carbon::createFromFormat(
        '!d/m/Y h:i A',
        $orderCreatedDate
    );

    foreach ($processes as &$process) {
        // Copy so calculating the end date does not change the start date.
        $endDate = $startDate->copy()->addWeekdays(
            (int) $process['completed_days']
        );

        $process['start_date'] = $startDate->format('d/m/Y h:i A');
        $process['end_date'] = $endDate->format('d/m/Y h:i A');

        // The next process starts when the previous process ends.
        $startDate = $endDate->copy();
    }

    unset($process);

    return $processes;
}
```

### Usage

```php
$orderCreatedDate = '25/06/2024 10:45 AM';

$processes = [
    [
        'name' => 'process 1',
        'sequence' => 1,
        'completed_days' => 2,
    ],
    [
        'name' => 'process 2',
        'sequence' => 2,
        'completed_days' => 4,
    ],
];

$result = calculateProcessDates($orderCreatedDate, $processes);

dd($result);
```

### Result

```php
[
    [
        'name' => 'process 1',
        'sequence' => 1,
        'completed_days' => 2,
        'start_date' => '25/06/2024 10:45 AM',
        'end_date' => '27/06/2024 10:45 AM',
    ],
    [
        'name' => 'process 2',
        'sequence' => 2,
        'completed_days' => 4,
        'start_date' => '27/06/2024 10:45 AM',
        'end_date' => '03/07/2024 10:45 AM',
    ],
]
```

**Note:** `addWeekdays()` excludes Saturdays and Sundays, but not public holidays. If weekends should count, replace it with `addDays()`.

