This adds:
- Configurable method buttons for each tab.
- An editable POST URL and JSON request body.
- An editable JSON response that can be submitted as a mock response.
- Request errors, HTTP status, and mock-request details.

```javascript
// Match these names and default bodies to your actual API.
// Method names are used verbatim in the request URL.
const defaultMethods = [
  { name: "FindPosition", label: "Find Position", body: {} },
  { name: "detectObjects", label: "Detect Objects", body: {} },
  { name: "classifyImage", label: "Classify Image", body: {} },
];

// Optionally configure a different method list for individual tabs.
const methodsByPrefix = {
  // vision1: [
  //   { name: "FindPosition", label: "Find Position", body: { target: "" } },
  // ],
  // visionSystem: [
  //   { name: "GetStatus", label: "Get Status", body: {} },
  // ],
};

const formatJson = (value) => JSON.stringify(value, null, 2);

const readResponse = async (response) => {
  const text = await response.text();

  // Display non-JSON responses too, so server errors remain visible.
  try {
    return formatJson(JSON.parse(text));
  } catch {
    return text;
  }
};

const MethodApiPanel = ({ apiPrefix, methods }) => {
  const initialMethod = methods[0];

  const [apiName, setApiName] = useState(initialMethod.name);
  const [postUri, setPostUri] = useState(
    `/api/${apiPrefix}/${initialMethod.name}`
  );
  const [postBody, setPostBody] = useState(
    formatJson(initialMethod.body ?? {})
  );
  const [responseJson, setResponseJson] = useState("");
  const [status, setStatus] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  const [mockRequest, setMockRequest] = useState(null);
  const [mockResult, setMockResult] = useState("");
  const [mockStatus, setMockStatus] = useState("");

  const selectMethod = (method) => {
    setApiName(method.name);
    setPostUri(`/api/${apiPrefix}/${method.name}`);
    setPostBody(formatJson(method.body ?? {}));
    setResponseJson("");
    setStatus("");
    setError("");
    setMockRequest(null);
    setMockResult("");
    setMockStatus("");
  };

  const formatEditor = (text, setter) => {
    try {
      setter(formatJson(JSON.parse(text)));
      setError("");
    } catch (err) {
      setError(`Invalid JSON: ${err.message}`);
    }
  };

  const sendPostRequest = async () => {
    setError("");
    setStatus("");
    setBusy(true);

    try {
      if (!postUri.trim()) {
        throw new Error("Enter a POST URL.");
      }

      let body;
      try {
        body = JSON.parse(postBody);
      } catch (err) {
        throw new Error(`Invalid request JSON: ${err.message}`);
      }

      setPostBody(formatJson(body));
      setResponseJson("");

      const response = await fetch(postUri.trim(), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });

      setStatus(`${response.status} ${response.statusText}`);
      setResponseJson(await readResponse(response));

      if (!response.ok) {
        setError(`API request failed with HTTP ${response.status}.`);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  };

  const setMockResponse = async () => {
    setError("");
    setMockRequest(null);
    setMockResult("");
    setMockStatus("");
    setBusy(true);

    try {
      if (!apiName.trim()) {
        throw new Error("Enter the API method name for the mock.");
      }

      let mockResponse;
      try {
        mockResponse = JSON.parse(responseJson);
      } catch (err) {
        throw new Error(`Invalid response JSON: ${err.message}`);
      }

      // Uses the same mock API contract as your SetMockResponsePanel.
      const url = `/api/${apiPrefix}/setResponse`;
      const body = {
        api: apiName.trim(),
        response: mockResponse,
      };

      setResponseJson(formatJson(mockResponse));
      setMockRequest({
        url,
        body: formatJson(body),
      });

      const response = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });

      setMockStatus(`${response.status} ${response.statusText}`);
      setMockResult(await readResponse(response));

      if (!response.ok) {
        setError(`Setting the mock failed with HTTP ${response.status}.`);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  };

  return html`
    <div class="panel">
      <div class="panel-header">
        <h4 class="panel-title">API Methods</h4>
      </div>

      <div class="panel-body">
        <div class="form-group">
          ${methods.map(
            (method) => html`
              <button
                key=${method.name}
                type="button"
                class=${`btn ${apiName === method.name ? "btn-primary" : ""}`}
                disabled=${busy}
                onClick=${() => selectMethod(method)}
              >
                ${method.label}
              </button>
            `
          )}
        </div>

        <div class="form-group">
          <label class="form-label" for=${`${apiPrefix}-post-url`}>
            POST URL
          </label>
          <input
            id=${`${apiPrefix}-post-url`}
            class="form-input"
            type="text"
            value=${postUri}
            disabled=${busy}
            onInput=${(e) => setPostUri(e.target.value)}
          />
          <p class="form-input-hint">
            POST ${postUri}
          </p>
        </div>

        <div class="form-group">
          <label class="form-label" for=${`${apiPrefix}-request`}>
            Request JSON
          </label>
          <textarea
            id=${`${apiPrefix}-request`}
            class="form-input json-editor"
            rows="10"
            spellcheck=${false}
            value=${postBody}
            disabled=${busy}
            onInput=${(e) => setPostBody(e.target.value)}
          ></textarea>
        </div>

        <div class="form-group">
          <button
            type="button"
            class="btn btn-primary"
            disabled=${busy}
            onClick=${sendPostRequest}
          >
            Send POST
          </button>
          <button
            type="button"
            class="btn"
            disabled=${busy}
            onClick=${() => formatEditor(postBody, setPostBody)}
          >
            Format Request
          </button>
        </div>

        <div class="divider"></div>

        <div class="form-group">
          <label class="form-label" for=${`${apiPrefix}-response`}>
            Response JSON
          </label>

          ${status && html`
            <p><span class="label">${status}</span></p>
          `}

          <textarea
            id=${`${apiPrefix}-response`}
            class="form-input json-editor"
            rows="12"
            spellcheck=${false}
            placeholder="Send a request, or enter JSON to configure a mock."
            value=${responseJson}
            disabled=${busy}
            onInput=${(e) => setResponseJson(e.target.value)}
          ></textarea>

          <p class="form-input-hint">
            Edit this JSON, then click Set Mock Response.
            Edit the request above and click Send POST to call the API again.
          </p>
        </div>

        <div class="form-group">
          <label class="form-label" for=${`${apiPrefix}-mock-method`}>
            Mock API method name
          </label>
          <input
            id=${`${apiPrefix}-mock-method`}
            class="form-input"
            type="text"
            value=${apiName}
            disabled=${busy}
            onInput=${(e) => setApiName(e.target.value)}
          />
          <p class="form-input-hint">
            If you manually change the POST URL, update this method name too.
          </p>
        </div>

        <div class="form-group">
          <button
            type="button"
            class="btn btn-primary"
            disabled=${busy || !responseJson.trim()}
            onClick=${setMockResponse}
          >
            Set Mock Response
          </button>
          <button
            type="button"
            class="btn"
            disabled=${busy || !responseJson.trim()}
            onClick=${() => formatEditor(responseJson, setResponseJson)}
          >
            Format Response
          </button>
        </div>

        ${busy && html`<div class="loading"></div>`}

        ${error && html`
          <div class="toast toast-error" role="alert">${error}</div>
        `}

        ${mockRequest && html`
          <div class="divider"></div>
          <h6>Mock Configuration Request</h6>
          <pre class="code">POST ${mockRequest.url}</pre>
          <pre class="code" data-lang="JSON">${mockRequest.body}</pre>

          <h6>Mock Configuration Response</h6>
          ${mockStatus && html`
            <p><span class="label">${mockStatus}</span></p>
          `}
          <pre class="code">${mockResult}</pre>
        `}
      </div>
    </div>
  `;
};

const VisionPage = ({ apiPrefix }) => {
  const methods = methodsByPrefix[apiPrefix] ?? defaultMethods;

  return html`
    <div class="container">
