Below is a single-replica deployment with **Home Assistant and nginx in the same Pod**. nginx proxies to Home Assistant over loopback; Home Assistant’s state is stored on a PVC.

The CUE separates user settings, reusable configuration, and Kubernetes resources. It exports a standard Kubernetes `List`.

### `cluster.cue`

```cue
package cluster

// ── User settings ────────────────────────────────────────────────────

#Settings: {
	namespace: string
	name:      string
	timezone:  string

	images: {
		homeAssistant: string
		nginx:         string
	}

	storage: {
		size: string

		// Omit to use the cluster's default StorageClass.
		className?: string
	}
}

settings: #Settings & {
	namespace: "home-automation"
	name:      "home-assistant"
	timezone:  "Etc/UTC"

	// Convenient defaults. Pin tested versions or digests in production.
	images: {
		homeAssistant: "ghcr.io/home-assistant/home-assistant:stable"
		nginx:         "nginx:stable-alpine"
	}

	storage: {
		size: "10Gi"
		// className: "your-storage-class"
	}
}

// Aliases avoid ambiguity inside nested Kubernetes objects.
let cfg = settings

let appLabels = {
	"app.kubernetes.io/name":     cfg.name
	"app.kubernetes.io/instance": cfg.name
}

let configName = "\(cfg.name)-config"
let dataName   = "\(cfg.name)-data"

#NamespacedMetadata: {
	name:      string
	namespace: cfg.namespace
	labels:    appLabels
}

// ── Application configuration ────────────────────────────────────────

configuration: {
	homeAssistant: """
		default_config:

		homeassistant:
		  time_zone: "\(cfg.timezone)"

		http:
		  use_x_forwarded_for: true
		  trusted_proxies:
		    - 127.0.0.1
		"""

	nginx: """
		worker_processes auto;
		pid /tmp/nginx.pid;
		error_log /dev/stderr warn;

		events {
		    worker_connections 1024;
		}

		http {
		    access_log /dev/stdout;

		    client_body_temp_path /tmp/client_temp;
		    proxy_temp_path       /tmp/proxy_temp;

		    map $http_upgrade $connection_upgrade {
		        default upgrade;
		        ''      close;
		    }

		    server {
		        listen 8080;
		        server_name _;

		        client_max_body_size 100m;

		        location = /healthz {
		            access_log off;
		            default_type text/plain;
		            return 200 "ok";
		        }

		        location / {
		            proxy_pass http://127.0.0.1:8123;
		            proxy_http_version 1.1;

		            proxy_set_header Host              $http_host;
		            proxy_set_header X-Real-IP         $remote_addr;
		            proxy_set_header X-Forwarded-For   $remote_addr;
		            proxy_set_header X-Forwarded-Proto $scheme;

		            proxy_set_header Upgrade    $http_upgrade;
		            proxy_set_header Connection $connection_upgrade;

		            proxy_buffering off;
		            proxy_read_timeout 3600s;
		            proxy_send_timeout 3600s;
		        }
		    }
		}
		"""
}

let appConfig = configuration

// ── Kubernetes resources ─────────────────────────────────────────────

resources: {
	namespace: {
		apiVersion: "v1"
		kind:       "Namespace"
		metadata: {
			name:   cfg.namespace
			labels: appLabels
		}
	}

	config: {
		apiVersion: "v1"
		kind:       "ConfigMap"
		metadata: #NamespacedMetadata & {
			name: configName
		}
		data: {
			"configuration.yaml": appConfig.homeAssistant
			"nginx.conf":         appConfig.nginx
		}
	}

	data: {
		apiVersion: "v1"
		kind:       "PersistentVolumeClaim"
		metadata: #NamespacedMetadata & {
			name: dataName
		}
		spec: {
			accessModes: ["ReadWriteOnce"]
			resources: requests: storage: cfg.storage.size

			if cfg.storage.className != _|_ {
