### Combined script

```python
from __future__ import annotations

import difflib
import json
import math
import queue
import re
import threading
import unicodedata
from collections import Counter
from pathlib import Path

import numpy as np
from scipy.optimize import Bounds, LinearConstraint, milp
from scipy.sparse import coo_matrix

import tkinter as tk
from tkinter import messagebox, ttk
from tkinter.scrolledtext import ScrolledText


# ============================================================
# CONFIGURATION
# ============================================================

DECK_FOLDER = Path(r"C:\Users\Braiks\Downloads\ManualMH3Decks")

DRAFT_LOG = Path(
    r"C:\Users\Braiks\AppData\Roaming"
    r"\untapped-companion\drafts.json"
)

ID_FILE = Path(
    r"C:\Users\Braiks\Downloads\mtga bot\mh3ids.txt"
)

POLL_MS = 1000
SOLVER_TIME_LIMIT_SECONDS = 120

DECK_SIZE = 40

# These are statistical smoothing settings, NOT land-count rules.
APPEARANCE_PSEUDOCOUNT = 1.0
PAIR_PRIOR_DECKS = 1.0

# Scale pairwise association by the number of other cards in a deck.
PAIR_WEIGHT = 1.0 / (DECK_SIZE - 1)

BASIC_NAMES = ("Forest", "Mountain", "Island", "Plains", "Swamp")


def normalize(name):
    """Normalize spelling format, without inspecting card characteristics."""
    name = unicodedata.normalize("NFKC", str(name))
    name = name.replace("\u2019", "'").replace("\u2018", "'")
    return " ".join(name.split()).casefold()


BASICS = frozenset(normalize(x) for x in BASIC_NAMES)


def read_text(path):
    return path.read_text(encoding="utf-8-sig")


def pair_key(a, b):
    return (a, b) if a <= b else (b, a)


def pool_signature(pool):
    return tuple(sorted((k, int(v)) for k, v in pool.items() if v > 0))


# ============================================================
# CARD NAME / ARENA ID RESOLUTION
# ============================================================

class CardNames:
    def __init__(self, path):
        self.id_to_key = {}
        self.display = {}
        self.aliases = {}

        for name in BASIC_NAMES:
            self.display[normalize(name)] = name

        for line_no, line in enumerate(read_text(path).splitlines(), 1):
            if not line.strip():
                continue

            # Only the FIRST comma separates the ID and the name.
            parts = line.split(",", 1)
            if len(parts) != 2:
                raise ValueError(
                    f"{path.name}, line {line_no}: expected ID, Card Name"
                )

            arena_id, name = (x.strip() for x in parts)

            if not arena_id.isdigit() or not name:
                raise ValueError(
                    f"{path.name}, line {line_no}: invalid ID or name"
                )

            key = normalize(name)

            old = self.id_to_key.get(arena_id)
            if old is not None and old != key:
                raise ValueError(
                    f"Arena ID {arena_id} has conflicting names."
                )

            self.id_to_key[arena_id] = key
            self.display.setdefault(key, name)

        if not self.id_to_key:
            raise ValueError("The Arena ID mapping file is empty.")

        # Match front-face-only deck exports to full "Front // Back" names,
        # but ONLY when the name match is unambiguous.
        # This is name matching, not card metadata.
        fronts = {}
        for key in set(self.id_to_key.values()):
            if " // " in key:
                front = key.split(" // ", 1)[0]
                fronts.setdefault(front, set()).add(key)

        for front, targets in fronts.items():
            if len(targets) == 1 and front not in self.display:
                self.aliases[front] = next(iter(targets))

    def resolve_name(self, name):
        key = normalize(name)
        return self.aliases.get(key, key)

    def resolve_id(self, arena_id):
        return self.id_to_key.get(str(arena_id))

    def pretty(self, key):
        return self.display.get(key, key)

    def suggestions(self, key):
        candidates = list(self.display) + list(self.aliases)
        matches = difflib.get_close_matches(
            key, candidates, n=2, cutoff=0.76
        )
        return [
            self.pretty(self.aliases.get(match, match))
            for match in matches
        ]


def parse_deck_text(text, names, require_known=False):
    result = Counter()
    original_names = {}

    for line_no, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue

        match = re.fullmatch(r"\s*(\d+)\s+(.+?)\s*", line)
        if not match:
            raise ValueError(
                f"Line {line_no}: expected a quantity followed by a card name."
            )

        count = int(match.group(1))
        original = match.group(2)
        key = names.resolve_name(original)

        if count <= 0:
            raise ValueError(f"Line {line_no}: quantity must be positive.")

        if require_known and key not in names.display:
            raise ValueError(
                f"Unknown card name on line {line_no}: {original}\n"
                "Check the ID mapping or correct the pool manually."
            )

        result[key] += count
        original_names.setdefault(key, original)

    return result, original_names


# ============================================================
# TRAINING: APPEARANCES AND COPY-AWARE CO-OCCURRENCES
# ============================================================

class CountModel:
    def __init__(self, names, appearances, cooccurrences, deck_count):
        self.names = names
        self.appearances = appearances
        self.cooccurrences = cooccurrences
        self.deck_count = deck_count

        self.total_cards = sum(appearances.values())
        self.total_ordered_pairs = (
            deck_count * DECK_SIZE * (DECK_SIZE - 1)
        )

        # Mapping-only cards remain possible, but have no observed evidence.
        self.vocabulary = (
            set(names.display) | set(appearances) | set(BASICS)
        )

        denominator = (
            self.total_cards
            + APPEARANCE_PSEUDOCOUNT * len(self.vocabulary)
        )

        self.probabilities = {
            key: (
                appearances[key] + APPEARANCE_PSEUDOCOUNT
            ) / denominator
            for key in self.vocabulary
        }

        self.pair_prior_mass = (
            PAIR_PRIOR_DECKS * DECK_SIZE * (DECK_SIZE - 1)
        )

    def cooccurrence(self, a, b):
        return self.cooccurrences.get(pair_key(a, b), 0)

    def draft_score(self, candidate, pool):
        return sum(
            count * self.cooccurrence(candidate, other)
            for other, count in pool.items()
            if other not in BASICS
        )

    def association(self, a, b):
        """
        Smoothed pointwise mutual-information-like association.

        Off-diagonal C(a,b) counts ordered positions in the a->b
        direction. The symmetric b->a count has the same value.

        Diagonal C(a,a) counts n(a)*(n(a)-1).
        """
        pa = self.probabilities[a]
        pb = self.probabilities[b]

        joint = (
            self.cooccurrence(a, b)
            + self.pair_prior_mass * pa * pb
        ) / (
            self.total_ordered_pairs + self.pair_prior_mass
        )

        return math.log(joint / (pa * pb))


def train_model():
    names = CardNames(ID_FILE)
    files = sorted(DECK_FOLDER.glob("*.txt"))

    if not files:
        raise ValueError(f"No .txt decks found in:\n{DECK_FOLDER}")

    appearances = Counter()
    cooccurrences = Counter()
    warnings = []
    unknown_names = {}
    used = 0

    for path in files:
        try:
            deck, originals = parse_deck_text(read_text(path), names)

            total = sum(deck.values())
            if total != DECK_SIZE:
                raise ValueError(
                    f"contains {total} cards, not {DECK_SIZE}"
                )

        except (ValueError, OSError, UnicodeError) as exc:
            warnings.append(f"SKIPPED {path.name}: {exc}")
            continue

        used += 1

        for key, original in originals.items():
            if key not in names.display:
                unknown_names.setdefault(key, original)

        appearances.update(deck)

        items = sorted(deck.items())

        for i, (a, count_a) in enumerate(items):
            if count_a > 1:
                cooccurrences[(a, a)] += count_a * (count_a - 1)

            for b, count_b in items[i + 1:]:
                cooccurrences[(a, b)] += count_a * count_b

    if used == 0:
        raise ValueError(
            "No valid 40-card training decks were found.\n"
            + "\n".join(warnings[:12])
        )

    # Do not silently fuzzy-correct card names.
    for key, original in sorted(unknown_names.items()):
        suggestions = names.suggestions(key)
        suffix = (
            " Possible match: " + " / ".join(suggestions)
            if suggestions else ""
        )
        warnings.append(
            f"Training name not in ID mapping: {original}.{suffix} "
            "It remains a separate card until corrected."
        )
        names.display.setdefault(key, original)

    model = CountModel(
        names, appearances, cooccurrences, used
    )

    summary = [
        f"Trained on {used} valid 40-card decks.",
        f"Skipped {len(files) - used} files.",
        f"Observed {len(appearances)} different card names.",
        f"Recorded {sum(appearances.values())} total card appearances.",
        "",
        "Only quantities, names, and co-occurrences were used.",
        "Basic lands remain in training, but are excluded from draft choices.",
    ]

    if warnings:
        summary += ["", "Warnings:"] + warnings

    return model, "\n".join(summary)


# ============================================================
# DECK OPTIMIZATION
#
# Maximize, for integer card counts x summing to 40:
#
#   sum_i [x_i log(p_i) - log(x_i!)]
#
#   + PAIR_WEIGHT * (
#       sum_{i<j} x_i*x_j*association(i,j)
#       + sum_i choose(x_i,2)*association(i,i)
#     )
#
# Pool cards are capped by drafted quantities.
# The five basics each have a cap of 40; the total-size constraint
# is the only reason a larger cap is unnecessary.
#
# Binary expansion + product linearization makes this an MILP.
# ============================================================

def optimize_deck(model, drafted_pool):
    pool = Counter({
        key: int(count)
        for key, count in drafted_pool.items()
        if count > 0 and key not in BASICS
    })

    for key in pool:
        if key not in model.vocabulary:
            raise ValueError(f"Unknown pool card: {key}")

    keys = sorted(
        set(pool) | set(BASICS),
        key=lambda k: model.names.pretty(k).casefold()
    )

    caps = {
        key: DECK_SIZE if key in BASICS else min(pool[key], DECK_SIZE)
        for key in keys
    }

    objective = []

    row_indices = []
    column_indices = []
    values = []
    lower = []
    upper = []

    def new_binary(reward=0.0):
        index = len(objective)
        # scipy.milp MINIMIZES, so negate our reward.
        objective.append(-float(reward))
        return index

    def constraint(terms, lo=-np.inf, hi=np.inf):
        row = len(lower)
        for column, coefficient in terms:
            if coefficient:
                row_indices.append(row)
                column_indices.append(column)
                values.append(float(coefficient))
        lower.append(float(lo))
        upper.append(float(hi))

    count_selectors = {}
    bits = {}
    size_terms = []

    for key in keys:
        cap = caps[key]
        log_p = math.log(model.probabilities[key])
        self_association = model.association(key, key)

        selectors = []

        # Exactly one count k is selected for each card.
        for k in range(cap + 1):
            reward = (
                k * log_p
                - math.lgamma(k + 1)
                + PAIR_WEIGHT
                * self_association
                * k * (k - 1) / 2
            )

            index = new_binary(reward)
            selectors.append(index)

            if k:
                size_terms.append((index, k))

        count_selectors[key] = selectors

        constraint(
            [(index, 1) for index in selectors],
            lo=1, hi=1
        )

        card_bits = [
            (new_binary(), 1 << position)
            for position in range(cap.bit_length())
        ]
        bits[key] = card_bits

        # Count chosen by the one-hot selectors equals binary count.
        terms = [
            (index, k)
            for k, index in enumerate(selectors)
            if k
        ]
        terms += [
            (index, -weight)
            for index, weight in card_bits
        ]
        constraint(terms, lo=0, hi=0)

    constraint(size_terms, lo=DECK_SIZE, hi=DECK_SIZE)

    for i, a in enumerate(keys):
        for b in keys[i + 1:]:
            coefficient = PAIR_WEIGHT * model.association(a, b)

            if abs(coefficient) < 1e-12:
                continue

            # x_a*x_b = sum weights * (binary_a AND binary_b).
            for bit_a, weight_a in bits[a]:
                for bit_b, weight_b in bits[b]:
                    product = new_binary(
                        coefficient * weight_a * weight_b
                    )

                    # product <= bit_a
                    constraint(
                        [(product, 1), (bit_a, -1)], hi=0
                    )
                    # product <= bit_b
                    constraint(
                        [(product, 1), (bit_b, -1)], hi=0
                    )
                    # product >= bit_a + bit_b - 1
                    constraint(
                        [(bit_a, 1), (bit_b, 1), (product, -1)],
                        hi=1
                    )

    variable_count = len(objective)

    matrix = coo_matrix(
        (
            np.asarray(values, dtype=float),
            (
                np.asarray(row_indices, dtype=np.int32),
                np.asarray(column_indices, dtype=np.int32)
            )
        ),
        shape=(len(lower), variable_count)
    ).tocsc()

    result = milp(
        c=np.asarray(objective, dtype=float),
        integrality=np.ones(variable_count, dtype=np.int32),
        bounds=Bounds(
            np.zeros(variable_count),
            np.ones(variable_count)
        ),
        constraints=LinearConstraint(
            matrix,
            np.asarray(lower),
            np.asarray(upper)
        ),
        options={
            "time_limit": SOLVER_TIME_LIMIT_SECONDS,
            "mip_rel_gap": 0.0,
            "presolve": True
        }
    )

    if result.x is None:
        raise RuntimeError(
            "The solver did not return a feasible deck within the limit.\n"
            "Increase SOLVER_TIME_LIMIT_SECONDS and try again.\n\n"
            + str(result.message)
        )

    solution = np.asarray(result.x)

    if (
        not np.all(np.isfinite(solution))
        or np.max(np.abs(solution - np.rint(solution))) > 1e-5
    ):
        raise RuntimeError(
            "The solver returned no usable integer deck. "
            "Increase the time limit."
        )

    rounded = np.rint(solution)
    activity = matrix @ rounded

    if (
        np.any(activity < np.asarray(lower) - 1e-5)
        or np.any(activity > np.asarray(upper) + 1e-5)
    ):
        raise RuntimeError("Solver result failed constraint validation.")

    deck = Counter()

    for key, selectors in count_selectors.items():
        selected_counts = [
            k for k, index in enumerate(selectors)
            if rounded[index] == 1
        ]

        if len(selected_counts) != 1:
            raise RuntimeError("Invalid card-count selection.")

        count = selected_counts[0]
        if count:
            deck[key] = count

    if sum(deck.values()) != DECK_SIZE:
        raise RuntimeError("Internal error: deck is not exactly 40 cards.")

    for key, count in deck.items():
        if key not in BASICS and count > pool[key]:
            raise RuntimeError("Internal error: pool quantity exceeded.")

    proven_optimal = result.status == 0
    gap = getattr(result, "mip_gap", None)

    if proven_optimal:
        report = "Optimal for this model, within solver tolerances."
    else:
        report = "Feasible deck; optimality was NOT proved."
        if gap is not None and math.isfinite(float(gap)):
            report += f" Solver-reported relative gap: {100 * gap:.2f}%."

    return deck, report


# ============================================================
# UNTAPPED SNAPSHOT READER
# ============================================================

def latest_snapshot(data):
    if not isinstance(data, dict):
        raise ValueError("Expected a JSON object containing draft records.")

    records = [
        (draft_id, record)
        for draft_id, record in data.items()
        if isinstance(record, dict)
        and isinstance(record.get("picks"), list)
        and record["picks"]
    ]

    if not records:
        return None

    def start_time(item):
        try:
            return float(item[1].get("startTime", 0))
        except (TypeError, ValueError):
            return 0.0

    draft_id, record = max(records, key=start_time)

    # PickedCards is authoritative. Never add up historical snapshots.
    usable = [
        entry for entry in record["picks"]
        if isinstance(entry, dict)
        and isinstance(entry.get("PickedCards"), list)
    ]

    if not usable:
        return None

    entry = usable[-1]

    before_ids = [str(x) for x in entry["PickedCards"]]

    raw_pack = entry.get("DraftPack", [])
    pack_ids = (
        [str(x) for x in raw_pack]
        if isinstance(raw_pack, list) else []
    )

    chosen = entry.get("PickedCard")

    if chosen is None or chosen == "" or chosen == 0 or chosen == "0":
        chosen = None
    elif isinstance(chosen, (str, int)):
        chosen = str(chosen)
    else:
        raise ValueError("Unexpected PickedCard format.")

    # The supplied format stores PickedCards BEFORE this entry's choice.
    # Add exactly one copy, even if the same card is already in the pool.
    after_ids = before_ids + ([chosen] if chosen is not None else [])

    return {
        "draft_id": str(draft_id),
        "pack_number": entry.get("PackNumber", "?"),
        "pick_number": entry.get("PickNumber", "?"),
        "before_ids": before_ids,
        "after_ids": after_ids,
        "pack_ids": pack_ids,
        "chosen": chosen,
        "status": str(entry.get("DraftStatus", "")),
    }


