    @staticmethod
    def replace_text(widget, text):
        widget.delete("1.0", "end")
        widget.insert("1.0", text)

    def refresh_buttons(self):
        self.reload_button.configure(
            state="disabled" if self.training or self.solving else "normal"
        )
        self.build_button.configure(
            state=(
                "normal"
                if self.model is not None
                and not self.training
                and not self.solving
                else "disabled"
            )
        )

    def start_training(self):
        if self.training or self.solving:
            return

        self.training = True
        self.refresh_buttons()
        self.status.set("Training from deck files...")

        def worker():
            try:
                self.events.put(("trained", train_model()))
            except Exception as exc:
                self.events.put(("training_error", str(exc)))

        threading.Thread(target=worker, daemon=True).start()

    def process_events(self):
        try:
            while True:
                kind, payload = self.events.get_nowait()

                if kind == "trained":
                    self.model, diagnostics = payload
                    self.training = False
                    self.last_file_stamp = None
                    self.last_snapshot_signature = None
                    self.export_text = ""
                    self.export_pool_signature = None

                    self.replace_text(self.notes, diagnostics)
                    self.replace_text(self.deck_box, "")
                    self.status.set(
                        f"Ready. Trained on {self.model.deck_count} decks."
                    )

                elif kind == "training_error":
                    self.training = False
                    self.status.set("Training failed.")
                    messagebox.showerror("Training error", payload)

                elif kind == "built":
                    deck, report, signature, model = payload
                    self.solving = False

                    text = self.format_deck(deck, model)
                    basic_total = sum(deck[b] for b in BASICS)

                    try:
                        current = pool_signature(self.read_pool())
                    except ValueError:
                        current = None

                    stale = current != signature or model is not self.model

                    prefix = (
                        "POOL CHANGED WHILE SOLVING — rebuild before use.\n\n"
                        if stale else ""
                    )

                    self.replace_text(
                        self.deck_box,
                        prefix
                        + text
                        + f"\n\n40 cards; {basic_total} basic lands.\n"
                        + report
                    )

                    if stale:
                        self.export_text = ""
                        self.export_pool_signature = None
                    else:
                        self.export_text = "Deck\n" + text + "\n"
                        self.export_pool_signature = signature

                    self.status.set(report)

                elif kind == "build_error":
                    self.solving = False
                    self.status.set("Deck optimization failed.")
                    messagebox.showerror("Deckbuilding error", payload)

                self.refresh_buttons()

        except queue.Empty:
            pass

        self.root.after(100, self.process_events)

    def resolve_ids(self, ids):
        known = Counter()
        unknown = Counter()

        for arena_id in ids:
            key = self.model.names.resolve_id(arena_id)
            if key is None:
                unknown[arena_id] += 1
            else:
                known[key] += 1

        return known, unknown

    def poll_log(self):
        try:
            if self.model is None or self.training:
                return

            stat = DRAFT_LOG.stat()
            stamp = (stat.st_mtime_ns, stat.st_size)

            if stamp == self.last_file_stamp:
                return

            # If the writer changes the file while we read it, retry later.
            raw = read_text(DRAFT_LOG)
            stat_after = DRAFT_LOG.stat()
            after_stamp = (stat_after.st_mtime_ns, stat_after.st_size)

            if after_stamp != stamp:
                return

            data = json.loads(raw)
            snapshot = latest_snapshot(data)

            # Only mark a read successful after parsing succeeds.
            self.last_file_stamp = stamp

            if snapshot is None:
                self.draft_status.set("No usable draft snapshot found.")
                return

            signature = (
                snapshot["draft_id"],
                snapshot["pack_number"],
                snapshot["pick_number"],
                tuple(snapshot["before_ids"]),
                tuple(snapshot["pack_ids"]),
                snapshot["chosen"],
                snapshot["status"]
            )

            if signature != self.last_snapshot_signature:
                self.last_snapshot_signature = signature
                self.apply_snapshot(snapshot)

        except FileNotFoundError:
            self.draft_status.set(f"Waiting for log file: {DRAFT_LOG}")

        except (json.JSONDecodeError, UnicodeError):
            self.draft_status.set(
                "Log is being written or is incomplete; retrying..."
            )

        except (OSError, ValueError, TypeError) as exc:
            self.draft_status.set(f"Log read warning: {exc}")

        finally:
            self.root.after(POLL_MS, self.poll_log)

    def apply_snapshot(self, snapshot):
        before_pool, unknown_before = self.resolve_ids(
            snapshot["before_ids"]
        )
        after_pool, unknown_after = self.resolve_ids(
            snapshot["after_ids"]
        )

        # Basic lands are unlimited deckbuilding resources, not pool limits.
        after_pool = Counter({
            key: count for key, count in after_pool.items()
            if key not in BASICS
        })

        lines = [
            f"{count} {self.model.names.pretty(key)}"
            for key, count in sorted(
                after_pool.items(),
                key=lambda item: self.model.names.pretty(item[0]).casefold()
            )
        ]

        for arena_id, count in sorted(unknown_after.items()):
            lines.append(f"{count} [Unmapped Arena ID {arena_id}]")

        self.replace_text(self.pool_box, "\n".join(lines))

        self.export_text = ""
        self.export_pool_signature = None
        self.replace_text(
            self.deck_box,
            "Pool updated. After the draft, verify the pool and click "
            "'Build best 40 from displayed pool'."
        )

        for row in self.pack_tree.get_children():
            self.pack_tree.delete(row)

        pack_cards = Counter()
        unmapped_pack = Counter()

        for arena_id in snapshot["pack_ids"]:
            key = self.model.names.resolve_id(arena_id)

            if key is None:
                unmapped_pack[arena_id] += 1
            elif key not in BASICS:
                pack_cards[key] += 1

        ranked = []

        for key, quantity in pack_cards.items():
            score = self.model.draft_score(key, before_pool)
            appearances = self.model.appearances[key]
            name = self.model.names.pretty(key)

            if score > 0:
                sort_key = (0, -score, name.casefold())
                label = str(score)
            else:
                sort_key = (1, -appearances, name.casefold())
                label = f"A{appearances}"

            ranked.append((sort_key, name, quantity, label))

        for arena_id, quantity in unmapped_pack.items():
            ranked.append((
                (2, 0, arena_id),
                f"[Unmapped Arena ID {arena_id}]",
                quantity,
                "UNMAPPED"
            ))

        for _, name, quantity, label in sorted(ranked):
            self.pack_tree.insert(
                "", "end", values=(name, quantity, label)
            )

        if snapshot["chosen"] is not None:
            phase = (
                "Historical pack: its choice is already recorded. "
                "Waiting for the next pack snapshot."
            )
        elif snapshot["pack_ids"]:
            phase = "Live/unselected pack snapshot."
        else:
            phase = "No pack listed in this snapshot."

        warning = ""
        if unknown_before or unknown_after or unmapped_pack:
            warning += (
                " WARNING: unmapped IDs; ranking may be incomplete. "
                "Add missing IDs and reload."
            )

        zero_evidence = [
            key for key in after_pool
            if self.model.appearances[key] == 0
        ]

        if zero_evidence:
            warning += (
                f" {len(zero_evidence)} pool card names have no training "
                "appearances."
            )

        self.draft_status.set(
            f"Draft {snapshot['draft_id'][:8]} | "
            f"Pack {snapshot['pack_number']}, "
            f"pick {snapshot['pick_number']} | "
            f"Pool: {sum(after_pool.values())} mapped nonbasic cards. "
            f"{phase}{warning}"
        )

    def read_pool(self):
        if self.model is None:
            raise ValueError("Train the model first.")

        pool, _ = parse_deck_text(
            self.pool_box.get("1.0", "end"),
            self.model.names,
            require_known=True
        )

        # Ignore typed/drafted basic quantities: the supply is unlimited.
        return Counter({
            key: count for key, count in pool.items()
            if key not in BASICS
        })

    def start_build(self):
        if self.training or self.solving or self.model is None:
            return

        try:
            pool = self.read_pool()
        except ValueError as exc:
            messagebox.showerror("Pool error", str(exc))
            return

        if not pool:
            messagebox.showwarning(
                "Empty pool",
                "No nonbasic cards are present in the displayed pool."
            )
            return

        signature = pool_signature(pool)
        model = self.model

        self.solving = True
        self.export_text = ""
        self.export_pool_signature = None
        self.refresh_buttons()

        self.status.set(
            "Optimizing all card counts and all five basic-land counts "
            f"(up to {SOLVER_TIME_LIMIT_SECONDS} seconds of solver time)..."
        )
        self.replace_text(
            self.deck_box,
            "Optimizing in the background. The window remains usable."
        )

        def worker():
            try:
                deck, report = optimize_deck(model, pool)
                self.events.put((
                    "built", (deck, report, signature, model)
                ))
            except Exception as exc:
                self.events.put(("build_error", str(exc)))

        threading.Thread(target=worker, daemon=True).start()

    @staticmethod
    def format_deck(deck, model):
        keys = sorted(
            deck,
            key=lambda key: (
                key in BASICS,
                model.names.pretty(key).casefold()
            )
        )

        return "\n".join(
            f"{deck[key]} {model.names.pretty(key)}"
            for key in keys if deck[key] > 0
        )

    def copy_deck(self):
        if not self.export_text:
            messagebox.showinfo(
                "No current deck",
                "Build a deck from the current pool first."
            )
            return

        try:
            current = pool_signature(self.read_pool())
        except ValueError as exc:
            messagebox.showerror("Pool error", str(exc))
            return

        if current != self.export_pool_signature:
            messagebox.showwarning(
                "Pool changed",
                "The pool was edited after optimization. Rebuild first."
            )
            return

        self.root.clipboard_clear()
        self.root.clipboard_append(self.export_text)
        self.status.set("Deck copied to clipboard in Arena import format.")


def main():
    root = tk.Tk()
    DraftBotApp(root)
    root.mainloop()


if __name__ == "__main__":
    main()
