## 2. Create the Pinia store

The store tracks the offset, prevents overlapping requests, and exposes loading, error, and end-of-list state.

```js
// src/stores/users.js
import { defineStore } from 'pinia'
import { ref } from 'vue'

export const useUsersStore = defineStore('users', () => {
  const rows = ref([])
  const loading = ref(false)
  const error = ref(null)
  const hasMore = ref(true)

  const pageSize = 50

  async function loadNextPage() {
    if (loading.value || !hasMore.value) {
      return false
    }

    loading.value = true
    error.value = null

    try {
      const params = new URLSearchParams({
        start: String(rows.value.length),
        count: String(pageSize),
      })

      const response = await fetch(`/api/users?${params}`)

      if (!response.ok) {
        throw new Error(`Request failed: ${response.status}`)
      }

      const data = await response.json()

      if (!Array.isArray(data.items)) {
        throw new Error('Invalid API response: expected an items array')
      }

      rows.value.push(...data.items)

      // An empty page always stops further requests.
      if (data.items.length === 0) {
        hasMore.value = false
      } else if (Number.isFinite(data.total)) {
        hasMore.value = rows.value.length < data.total
      } else {
        hasMore.value = data.items.length === pageSize
      }

      return true
    } catch (err) {
      error.value =
        err instanceof Error ? err.message : 'Unable to load rows'

      return false
    } finally {
      loading.value = false
    }
  }

  return {
    rows,
    loading,
    error,
    hasMore,
    loadNextPage,
  }
})
```

## 3. Create the infinite-scrolling table

The important part is `fillIfNeeded()`. It continues fetching until:

- There are enough rows to fill the viewport plus a small buffer.
- The API has no more rows.
- A request fails.

```vue
<!-- src/components/InfiniteUsersTable.vue -->
<script setup>
import { ref, nextTick, onMounted, onBeforeUnmount } from 'vue'
import { useUsersStore } from '../stores/users'

const store = useUsersStore()
const scrollContainer = ref(null)

// Begin loading before the user reaches the exact bottom.
const bottomThreshold = 160

let filling = false
let disposed = false
let resizeObserver

function isNearBottom() {
  const element = scrollContainer.value

  if (!element || element.clientHeight === 0) {
    return false
  }

  const remaining =
    element.scrollHeight - element.scrollTop - element.clientHeight

  return remaining <= bottomThreshold
}

async function fillIfNeeded() {
  // Scroll and resize events can fire while a request is running.
  if (filling || disposed || store.error) {
    return
  }

  filling = true

  try {
    // Wait for previously added rows to be rendered before measuring.
    await nextTick()

    while (
      !disposed &&
      store.hasMore &&
      !store.error &&
      isNearBottom()
    ) {
      const loaded = await store.loadNextPage()

      if (!loaded) {
        break
      }

      // Recalculate the available space using the newly rendered rows.
      await nextTick()
    }
  } finally {
    filling = false
  }
}

function retry() {
  store.error = null
  void fillIfNeeded()
}

onMounted(() => {
  resizeObserver = new ResizeObserver(() => {
    void fillIfNeeded()
  })

  resizeObserver.observe(scrollContainer.value)

  void fillIfNeeded()
})

onBeforeUnmount(() => {
  disposed = true
  resizeObserver?.disconnect()
})
</script>

<template>
  <div
    ref="scrollContainer"
    class="table-scroll"
    role="region"
    aria-label="Users"
    tabindex="0"
    @scroll.passive="fillIfNeeded"
  >
    <table :aria-busy="store.loading">
      <thead>
        <tr>
          <th scope="col">ID</th>
          <th scope="col">Name</th>
          <th scope="col">Email</th>
        </tr>
      </thead>

      <tbody>
        <tr v-for="row in store.rows" :key="row.id">
          <td>{{ row.id }}</td>
          <td>{{ row.name }}</td>
          <td>{{ row.email }}</td>
        </tr>
      </tbody>
    </table>

    <div v-if="store.loading" class="table-status" role="status">
      Loading more rows…
    </div>

    <div v-else-if="store.error" class="table-status" role="alert">
      <span>{{ store.error }}</span>
      <button type="button" @click="retry">Retry</button>
    </div>

    <div
      v-else-if="!store.hasMore"
      class="table-status"
      role="status"
    >
      {{ store.rows.length ? 'All rows loaded.' : 'No rows found.' }}
    </div>
  </div>
</template>

<style scoped>
