### Why this works

- **Fixed-looking header:** `position: sticky` keeps the header visible inside the scrolling container.
- **Fills available space:** the initial load loop requests additional pages until the container has enough content.
- **Dynamic loading:** scrolling within 160 pixels of the bottom starts the next request.
- **Responsive layout:** `ResizeObserver` triggers another fill check when the available space changes.
- **Safe retries:** failed requests pause automatic loading until the user selects Retry.

The API should return rows in a stable order for offset pagination. For very large datasets, consider adding row virtualization: infinite loading reduces request size, but this example still keeps every loaded row in the DOM.

### 解题思路

使用**扫描线 + 线段树**计算矩形并集面积。

1. 每个矩形生成两个事件：
   - 在 `x1` 处，将纵向区间 `[y1, y2)` 的覆盖次数加一。
   - 在 `x2` 处，将纵向区间 `[y1, y2)` 的覆盖次数减一。
2. 将所有纵坐标排序去重，进行离散化。
3. 按横坐标从小到大处理事件。相邻事件之间的覆盖情况不变，新增面积为：
   \[
   \text{当前覆盖的纵向长度}\times\text{横坐标差}
   \]
4. 用线段树维护当前所有矩形在纵向上的覆盖总长度。

线段树节点维护：
- `cover`：完整覆盖该节点区间的次数。
- `len`：该节点区间内被覆盖的实际长度。

若 `cover > 0`，整个区间均被覆盖；否则，覆盖长度等于两个子节点的覆盖长度之和。

### C++ 代码

```cpp
#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

struct Event {
    ll x, y1, y2;
    int delta;

    bool operator<(const Event& other) const {
        return x < other.x;
    }
};

class SegmentTree {
private:
    int n;
    const vector<ll>& ys;
    vector<int> cover;
    vector<ll> len;

    // 节点 [l, r] 表示实际区间 [ys[l], ys[r + 1])
    void pushUp(int p, int l, int r) {
        if (cover[p] > 0) {
            len[p] = ys[r + 1] - ys[l];
        } else if (l == r) {
            len[p] = 0;
        } else {
            len[p] = len[p * 2] + len[p * 2 + 1];
        }
    }

    void update(int p, int l, int r,
                int ql, int qr, int delta) {
        if (ql <= l && r <= qr) {
            cover[p] += delta;
            pushUp(p, l, r);
            return;
        }

        int mid = (l + r) / 2;
        if (ql <= mid) {
            update(p * 2, l, mid, ql, qr, delta);
        }
        if (qr > mid) {
            update(p * 2 + 1, mid + 1, r, ql, qr, delta);
        }

        pushUp(p, l, r);
    }

public:
    explicit SegmentTree(const vector<ll>& coordinates)
        : n(static_cast<int>(coordinates.size()) - 1),
          ys(coordinates),
          cover(4 * max(1, n), 0),
          len(4 * max(1, n), 0) {}

    void update(int l, int r, int delta) {
        if (n > 0 && l <= r) {
            update(1, 0, n - 1, l, r, delta);
        }
    }

    ll coveredLength() const {
        return n > 0 ? len[1] : 0;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Event> events;
    vector<ll> ys;

    for (int i = 0; i < n; ++i) {
        ll x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;

        // 面积为零的矩形不影响答案
        if (x1 == x2 || y1 == y2) {
            continue;
        }

        events.push_back({x1, y1, y2, 1});
        events.push_back({x2, y1, y2, -1});
        ys.push_back(y1);
        ys.push_back(y2);
    }

    if (events.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    sort(events.begin(), events.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    SegmentTree tree(ys);

    ll answer = 0;
    ll previousX = events[0].x;

    for (const auto& event : events) {
        ll width = event.x - previousX;

        // 先计算前一条扫描线到当前扫描线之间的面积
        answer = (answer + tree.coveredLength() * width % MOD) % MOD;

        int l = lower_bound(ys.begin(), ys.end(), event.y1) - ys.begin();
        int r = lower_bound(ys.begin(), ys.end(), event.y2) - ys.begin();

        // [y1, y2) 对应基本区间下标 [l, r - 1]
        tree.update(l, r - 1, event.delta);

        previousX = event.x;
    }

    cout << answer << '\n';
    return 0;
}
```

### 复杂度分析

- **时间复杂度：** \(O(n\log n)\)，排序及每次线段树更新均满足此总复杂度。
- **空间复杂度：** \(O(n)\)，用于存储事件、离散化坐标和线段树。

## 思路

设字符串 `a` 中有 `k` 个 `#`，那么 `b` 中就有 `m-k` 个 `#`。

所有操作依次使用的字母构成字符串：

```text
abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyz...
```

取其前 `m` 个字符，记为 `s`。

每次操作选择 `a`，就相当于把当前字母分配给 `a` 的下一个 `#`。因此：

- 分配给 `a` 的字母，是 `s` 中一个长度为 `k` 的子序列；
- 其余 `m-k` 个字母分配给 `b`；
- 任意这样的子序列都对应一种合法操作方案。

由于 `a` 中原有字母的位置和值都不变，要让最终的 `a` 字典序最小，只需要让填入其 `#` 的字母序列字典序最小。

问题转化为：

> 从长度为 `m` 的字符串 `s` 中删除 `m-k` 个字符，使剩下的字符串字典序最小。

## 单调栈贪心

用栈维护当前保留的字符，剩余可删除次数为 `del=m-k`。

依次枚举 `s` 中的字符 `c`：

1. 如果栈顶字符大于 `c`，并且还有删除次数，就删除栈顶。
2. 重复上述过程，直到不能继续删除。
3. 将 `c` 入栈。

这样可以尽量让较小的字符出现在靠前的位置。

遍历结束后，如果还有删除次数，则从末尾删除。代码中直接保留栈的前 `k` 个字符即可。

最后，将得到的字符依次填入 `a` 的 `#`。

## 正确性说明

首先，选择分配给 `a` 的操作编号，与选择 `s` 中长度为 `k` 的子序列一一对应。因此，只需求字典序最小的长度为 `k` 的子序列。

当栈顶字符大于当前字符，且仍能删除字符时，删除栈顶可以使更小的当前字符向前移动，从而使结果在尽可能靠前的位置变小。字典序优先比较靠前的位置，因此这种删除是最优的。

如果栈顶字符不大于当前字符，删除它不会使当前前缀更优，所以暂时保留。

遍历结束后，如果还有删除次数，说明保留的字符已经单调不降。此时删除末尾字符，可以保留尽可能小的前缀，因而最优。

所以算法得到的是字典序最小的填充序列，将其依次填入 `a` 后，得到的 `a` 也具有最小字典序。

## 复杂度分析

每个字符至多入栈、出栈一次：

- 时间复杂度：`O(n+m)`，由于 `m≤2n`，也就是 `O(n)`。
- 空间复杂度：`O(n+m)`，也就是 `O(n)`。

## C++17 代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    string a, b;
    cin >> a >> b;

    int k = 0;
    for (char c : a) {
        if (c == '#') {
            ++k;
        }
    }

    int del = m - k;
    string st;
    st.reserve(m);

    for (int i = 0; i < m; ++i) {
        char c = char('a' + i % 26);

        while (del > 0 && !st.empty() && st.back() > c) {
            st.pop_back();
            --del;
        }

        st.push_back(c);
    }

    // 若还有删除次数，从末尾删除，只保留前 k 个字符。
    st.resize(k);

    int pos = 0;
    for (char &c : a) {
        if (c == '#') {
            c = st[pos++];
        }
    }

    cout << a << '\n';
    return 0;
}
```

Below is a complete, self-contained browser game—no libraries or external assets required.

**Run it:** Save the code as `index.html`, then open it in a modern desktop browser.

**Controls**
- **A / D** or **← / →** — Move
- **Space** — Jump; jump again after landing
- **J / X** or **left click** — Attack
- **E** or **right click** — Attach/release grappling hook; aim with the mouse
- **W / S** — Shorten/lengthen the rope
- **Space while grappling** — Release and jump
- **P / Esc** — Pause
- **R** — Restart

Collect loot, fight or stomp enemies, activate checkpoints, and reach the golden flag.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Skyhook Sprint</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    background: #101827;
    color: white;
    font-family: system-ui, sans-serif;
  }
  main { width: min(1100px, 100vw); }
  canvas {
    display: block;
    width: 100%;
    aspect-ratio: 1100 / 620;
    background: #8cd6ff;
    border: 2px solid #354662;
    border-radius: 10px;
    box-shadow: 0 12px 60px #0008;
    touch-action: none;
    cursor: crosshair;
  }
  p {
    margin: 12px;
    text-align: center;
    color: #bdcde0;
    font-size: 13px;
    line-height: 1.6;
  }
  kbd {
    background: #26364e;
    border-radius: 4px;
    padding: 2px 5px;
  }
</style>
</head>
<body>
<main>
  <canvas id="game" aria-label="Skyhook Sprint platform game"></canvas>
  <p>
    <kbd>A D</kbd> move · <kbd>Space</kbd> jump ·
    <kbd>J</kbd> / left click attack ·
    <kbd>E</kbd> / right click hook ·
    <kbd>W S</kbd> reel rope · <kbd>P</kbd> pause · <kbd>R</kbd> restart
  </p>
</main>

<script>
"use strict";

const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
const W = 1100;
const H = 620;
const DPR = Math.min(window.devicePixelRatio || 1, 2);
canvas.width = W * DPR;
canvas.height = H * DPR;

const WORLD_W = 5300;
const WORLD_H = 1040;
const GRAVITY = 1800;
const HOOK_RANGE = 620;
const STEP = 1 / 120;

const keys = new Set();
const mouse = { x: 780, y: 180, active: false };
const camera = { x: 0, y: 0 };

let state = "title";
let platforms = [];
let enemies = [];
let loot = [];
let particles = [];
let checkpoints = [];
let player;
let rope = null;
let coins = 0;
let kills = 0;
let deaths = 0;
let elapsed = 0;
let time = 0;
let toast = "";
let toastTime = 0;
let jumpBuffer = 0;
let shake = 0;

const goal = { x: 5100, y: 620, w: 48, h: 140 };

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const lerp = (a, b, t) => a + (b - a) * t;
const rand = (a, b) => a + Math.random() * (b - a);
const overlap = (a, b) =>
  a.x < b.x + b.w && a.x + a.w > b.x &&
  a.y < b.y + b.h && a.y + a.h > b.y;
const center = b => ({ x: b.x + b.w / 2, y: b.y + b.h / 2 });

function say(text, duration = 3) {
  toast = text;
  toastTime = duration;
}

function addPlatform(x, y, w, h = 26, ground = false) {
  const p = { x, y, w, h, ground };
  platforms.push(p);
  return p;
}

function addLoot(x, y, type = "coin") {
  loot.push({
    x, y, type, r: type === "gem" ? 11 : 9,
    phase: Math.random() * Math.PI * 2,
    taken: false
  });
}

function coinRow(x, y, count, spacing = 36) {
  for (let i = 0; i < count; i++) addLoot(x + i * spacing, y);
}

function addEnemy(x, surfaceY, type = "walker") {
  enemies.push({
    x, y: surfaceY - 32, w: 34, h: 32,
    vx: 0, vy: 0, dir: Math.random() < 0.5 ? -1 : 1,
    speed: type === "armored" ? 85 : 65,
    hp: type === "armored" ? 2 : 1,
    type, grounded: true, invuln: 0, dead: false
  });
}

function buildLevel() {
  platforms = [];
  enemies = [];
  loot = [];
  particles = [];

  // Main route. Every gap can be crossed by jumping or grappling.
  [
    [0, 720],
    [870, 620],
    [1670, 700],
    [2570, 690],
    [3480, 660],
    [4360, 940]
  ].forEach(([x, w]) => addPlatform(x, 760, w, 280, true));

  // Upper routes, stepping stones, and grapple surfaces.
  [
    [240, 644, 150],
    [470, 535, 170],
    [715, 450, 150],
    [915, 610, 190],
    [1175, 505, 180],
    [1430, 620, 150],
    [1670, 540, 190],
    [1910, 425, 200],
    [2190, 580, 170],
    [2400, 650, 155],
    [2630, 550, 190],
    [2870, 440, 180],
    [3110, 595, 190],
    [3340, 510, 160],
    [3550, 625, 160],
    [3750, 515, 190],
    [4010, 405, 210],
    [4200, 635, 190],
    [4470, 550, 180],
    [4720, 645, 150]
  ].forEach(([x, y, w]) => addPlatform(x, y, w));

  coinRow(175, 714, 6);
  coinRow(985, 714, 5);
  coinRow(1790, 714, 6);
  coinRow(2695, 714, 5);
  coinRow(3590, 714, 5);
  coinRow(4570, 714, 8);

  for (const p of platforms) {
    if (!p.ground) {
      const n = Math.floor((p.w - 30) / 36);
      coinRow(p.x + 24, p.y - 35, n);
    }
  }

  [
    [788, 405], [2008, 380], [2960, 395], [4115, 360]
  ].forEach(([x, y]) => addLoot(x, y, "gem"));

  addLoot(1810, 504, "heart");
  addLoot(3820, 477, "heart");
  addLoot(4795, 605, "heart");

  [
    [510, 760], [1080, 760], [1290, 760],
    [1880, 760], [2140, 760], [2760, 760],
    [3050, 760], [3630, 760], [3910, 760],
    [4570, 760], [4830, 760]
  ].forEach(([x, y], i) =>
    addEnemy(x, y, i % 3 === 2 ? "armored" : "walker")
  );

  addEnemy(1220, 505);
  addEnemy(1950, 425, "armored");
  addEnemy(2910, 440);
  addEnemy(4050, 405, "armored");

  checkpoints = [
    { x: 1730, y: 760, active: false },
    { x: 3530, y: 760, active: false }
  ];
}

function newGame() {
  buildLevel();
  player = {
    x: 75, y: 712, w: 30, h: 44,
    vx: 0, vy: 0, face: 1, grounded: false,
    coyote: 0, hp: 5, maxHp: 5, invuln: 0,
    attack: 0, attackCooldown: 0, swingId: 0,
    spawnX: 75, spawnY: 712
  };
  rope = null;
  coins = kills = deaths = elapsed = 0;
  jumpBuffer = 0;
  shake = 0;
  camera.x = 0;
  camera.y = 400;
  state = "playing";
  say("Reach the golden flag! Aim at a platform and press E to grapple.", 5);
}

function burst(x, y, color, count = 12, speed = 160) {
  for (let i = 0; i < count; i++) {
    const angle = rand(0, Math.PI * 2);
    const velocity = rand(speed * 0.25, speed);
    particles.push({
      x, y,
      vx: Math.cos(angle) * velocity,
      vy: Math.sin(angle) * velocity - 70,
      life: rand(0.25, 0.65),
      maxLife: 0.65,
      size: rand(2, 5),
      color
    });
  }
}

function respawn() {
  deaths++;
  rope = null;
  player.x = player.spawnX;
  player.y = player.spawnY;
  player.vx = player.vy = 0;
  player.hp = player.maxHp;
  player.invuln = 1.5;
  player.attack = player.attackCooldown = 0;
  player.grounded = false;
  player.coyote = 0;
  jumpBuffer = 0;
  camera.x = clamp(player.x - W * 0.36, 0, WORLD_W - W);
  camera.y = clamp(player.y - H * 0.57, 0, WORLD_H - H);
  say("Back at your checkpoint. Collected loot is safe!");
}

function hurt(sourceX) {
  if (player.invuln > 0 || state !== "playing") return;
  player.hp--;
  player.invuln = 1.15;
  rope = null;
  player.vx = center(player).x < sourceX ? -340 : 340;
  player.vy = -370;
  player.grounded = false;
  shake = 0.22;
  burst(center(player).x, center(player).y, "#ff647c", 16);
  if (player.hp <= 0) respawn();
}

function killEnemy(e) {
  if (e.dead) return;
  e.dead = true;
  kills++;
  const c = center(e);
  burst(c.x, c.y, e.type === "armored" ? "#a8bdd1" : "#bf83ff", 18);
  addLoot(c.x - 14, c.y - 10);
  addLoot(c.x + 14, c.y - 20);
}

function damageEnemy(e, direction) {
  if (e.dead || e.invuln > 0) return;
  e.hp--;
  e.invuln = 0.25;
  burst(center(e).x, center(e).y, "#fff1a8", 7);
  if (e.hp <= 0) killEnemy(e);
  else e.dir = direction;
}

function attack() {
  if (state !== "playing" || player.attackCooldown > 0) return;
  player.attack = 0.18;
  player.attackCooldown = 0.32;
  player.swingId++;
}

// Move a body along each axis separately and resolve solid collisions.
function moveBody(body, dx, dy) {
  let hitX = false;
  let hitY = false;

  body.x += dx;
  for (const p of platforms) {
    if (!overlap(body, p)) continue;
    if (dx > 0) body.x = p.x - body.w;
    else if (dx < 0) body.x = p.x + p.w;
    else continue;
    body.vx = 0;
    hitX = true;
  }

  body.y += dy;
  body.grounded = false;
  for (const p of platforms) {
    if (!overlap(body, p)) continue;
    if (dy > 0) {
      body.y = p.y - body.h;
      body.grounded = true;
    } else if (dy < 0) {
      body.y = p.y + p.h;
    } else continue;
    body.vy = 0;
    hitY = true;
  }
  return { hitX, hitY };
}

// Return distance to the first intersection of a ray with a rectangle.
function rayRect(ox, oy, dx, dy, box, range) {
  let near = 0;
  let far = range;

  for (const [origin, direction, min, max] of [
    [ox, dx, box.x, box.x + box.w],
    [oy, dy, box.y, box.y + box.h]
  ]) {
    if (Math.abs(direction) < 0.000001) {
      if (origin < min || origin > max) return null;
    } else {
      let a = (min - origin) / direction;
      let b = (max - origin) / direction;
      if (a > b) [a, b] = [b, a];
      near = Math.max(near, a);
      far = Math.min(far, b);
      if (near > far) return null;
    }
  }
  return near >= 0 && near <= range ? near : null;
}

function castHook(tx, ty) {
  const c = center(player);
  let dx = tx - c.x;
  let dy = ty - c.y;
  const len = Math.hypot(dx, dy);
  if (len < 1) return null;
  dx /= len;
  dy /= len;

  let best = null;
  let distance = HOOK_RANGE;
  for (const p of platforms) {
    const d = rayRect(c.x, c.y, dx, dy, p, HOOK_RANGE);
    if (d !== null && d > 10 && d < distance) {
      distance = d;
      best = { x: c.x + dx * d, y: c.y + dy * d, distance: d };
    }
  }
  return best;
}

function getHookTarget() {
  if (mouse.active) {
    return castHook(mouse.x + camera.x, mouse.y + camera.y);
  }

  // Keyboard-only fallback: choose an overhead platform.
  const c = center(player);
  let best = null;
  let bestScore = Infinity;
  for (const p of platforms) {
    if (p.ground || p.y + p.h > c.y - 35) continue;
    const tx = clamp(c.x + player.face * 180, p.x + 8, p.x + p.w - 8);
    const ty = p.y + p.h;
    const hit = castHook(tx, ty);
    if (!hit) continue;
    const behind = (hit.x - c.x) * player.face < 0 ? 250 : 0;
    const score = hit.distance + behind;
    if (score < bestScore) {
      bestScore = score;
      best = hit;
    }
  }
  return best;
}

function toggleHook() {
  if (state !== "playing") return;
  if (rope) {
    rope = null;
    return;
  }
  const target = getHookTarget();
  if (!target) {
    say("No surface in range. Aim at a platform within the dotted line.", 2);
    return;
  }
  rope = {
    x: target.x, y: target.y,
    length: Math.max(55, target.distance)
  };
  burst(rope.x, rope.y, "#dcffff", 10, 100);
}

function updatePlayer(dt) {
  player.invuln = Math.max(0, player.invuln - dt);
  player.attack = Math.max(0, player.attack - dt);
  player.attackCooldown = Math.max(0, player.attackCooldown - dt);
  jumpBuffer = Math.max(0, jumpBuffer - dt);

  if (player.grounded) player.coyote = 0.11;
  else player.coyote = Math.max(0, player.coyote - dt);

  const left = keys.has("KeyA") || keys.has("ArrowLeft");
  const right = keys.has("KeyD") || keys.has("ArrowRight");
  const direction = Number(right) - Number(left);

  if (direction) player.face = direction;

  if (jumpBuffer > 0 && (player.coyote > 0 || rope)) {
    const wasHooked = !!rope;
    rope = null;
    player.vy = wasHooked ? Math.min(player.vy - 250, -580) : -660;
    player.grounded = false;
    player.coyote = 0;
    jumpBuffer = 0;
    burst(player.x + player.w / 2, player.y + player.h, "#e9f7fa", 7, 70);
  }

  if (rope) {
    player.vx += direction * 1150 * dt;
    player.vx *= Math.exp(-0.16 * dt);
    player.vx = clamp(player.vx, -760, 760);
    if (keys.has("KeyW")) rope.length -= 230 * dt;
    if (keys.has("KeyS")) rope.length += 230 * dt;
    rope.length = clamp(rope.length, 55, HOOK_RANGE);
  } else {
    const accel = player.grounded ? 2600 : 1700;
    if (direction) {
      // Preserve some grappling momentum while allowing normal acceleration.
      if (Math.abs(player.vx) <= 325 || Math.sign(player.vx) !== direction) {
        player.vx += direction * accel * dt;
        player.vx = clamp(player.vx, -325, 325);
      } else {
        player.vx *= Math.exp(-0.8 * dt);
      }
    } else {
      player.vx *= Math.exp(-(player.grounded ? 16 : 1.8) * dt);
    }
  }

  player.vy = Math.min(player.vy + GRAVITY * dt, 1150);

  moveBody(player, player.vx * dt, player.vy * dt);

  if (rope) {
    const c = center(player);
    const dx = c.x - rope.x;
    const dy = c.y - rope.y;
    const distance = Math.hypot(dx, dy);

    if (distance > rope.length && distance > 0) {
      const nx = dx / distance;
      const ny = dy / distance;
      const correction = distance - rope.length;

      // Collision-aware rope correction, split into short steps.
      const steps = Math.max(1, Math.ceil(correction / 8));
      for (let i = 0; i < steps; i++) {
        moveBody(player, -nx * correction / steps, -ny * correction / steps);
      }

      // Remove outward velocity, preserving tangential swing velocity.
      const outward = player.vx * nx + player.vy * ny;
      if (outward > 0) {
        player.vx -= outward * nx;
        player.vy -= outward * ny;
      }

      // If a wall prevents reeling, let the rope remain physically reachable.
      const actual = Math.hypot(
        center(player).x - rope.x,
        center(player).y - rope.y
      );
      rope.length = Math.max(rope.length, actual);
    }
  }

  player.x = clamp(player.x, 0, WORLD_W - player.w);
  if (player.y > WORLD_H + 100) {
    respawn();
    return;
  }

  if (player.attack > 0) {
    const hitbox = {
      x: player.face > 0 ? player.x + player.w - 5 : player.x - 65,
      y: player.y - 8,
      w: 70,
      h: player.h + 16
    };
    for (const e of enemies) {
      if (!e.dead && e.lastSwing !== player.swingId && overlap(hitbox, e)) {
        e.lastSwing = player.swingId;
        damageEnemy(e, player.face);
      }
    }
  }

  const pc = center(player);
  for (const item of loot) {
    if (item.taken) continue;
    if (Math.abs(pc.x - item.x) < 25 &&
        Math.abs(pc.y - item.y) < 33) {
      item.taken = true;
      if (item.type === "heart") {
        player.hp = Math.min(player.maxHp, player.hp + 1);
        say("+1 health", 1.4);
      } else {
        coins += item.type === "gem" ? 10 : 1;
      }
      burst(item.x, item.y,
        item.type === "heart" ? "#ff748f" :
        item.type === "gem" ? "#70f5ff" : "#ffdc62", 7, 100);
    }
  }

  for (const cp of checkpoints) {
    if (!cp.active && Math.abs(pc.x - cp.x) < 40 &&
        player.y + player.h > cp.y - 90) {
      cp.active = true;
      player.spawnX = cp.x + 22;
      player.spawnY = cp.y - player.h - 3;
      player.hp = player.maxHp;
      burst(cp.x, cp.y - 75, "#7effac", 25);
      say("Checkpoint activated — health restored!");
    }
  }

  if (overlap(player, goal)) {
    rope = null;
    state = "won";
    burst(goal.x + 20, goal.y + 20, "#ffdf6d", 70, 300);
  }
}

function updateEnemies(dt) {
  for (const e of enemies) {
    if (e.dead) continue;
    e.invuln = Math.max(0, e.invuln - dt);

    if (e.grounded) {
      const lookX = e.dir > 0 ? e.x + e.w + 9 : e.x - 9;
      const footY = e.y + e.h;
      const hasFloor = platforms.some(p =>
        lookX >= p.x && lookX <= p.x + p.w &&
        Math.abs(p.y - footY) < 8
      );
      if (!hasFloor) e.dir *= -1;
    }

    e.vx = e.dir * e.speed;
    e.vy = Math.min(e.vy + GRAVITY * dt, 1000);
    const hit = moveBody(e, e.vx * dt, e.vy * dt);
    if (hit.hitX) e.dir *= -1;
    if (e.y > WORLD_H + 100) {
      e.dead = true;
      continue;
    }

    if (state !== "playing" || !overlap(player, e)) continue;

    const feet = player.y + player.h;
    if (player.vy > 100 && feet - e.y < 24) {
      damageEnemy(e, player.face);
      player.y = e.y - player.h;
      player.vy = -460;
      player.grounded = false;
      rope = null;
      burst(player.x + player.w / 2, feet, "#fff4bc", 9);
    } else {
      hurt(center(e).x);
    }
  }
}

function updateParticles(dt) {
  for (const p of particles) {
    p.life -= dt;
    p.vy += 600 * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
  }
  particles = particles.filter(p => p.life > 0);
}

function update(dt) {
  time += dt;
  if (state !== "playing" && state !== "won") return;

  updateParticles(dt);
  if (state === "won") return;

  elapsed += dt;
  toastTime = Math.max(0, toastTime - dt);
  shake = Math.max(0, shake - dt);

  updatePlayer(dt);
  if (state === "playing") updateEnemies(dt);

  const targetX = clamp(player.x + player.w / 2 - W * 0.38, 0, WORLD_W - W);
  const targetY = clamp(player.y + player.h / 2 - H * 0.57, 0, WORLD_H - H);
  camera.x = lerp(camera.x, targetX, 1 - Math.exp(-7 * dt));
  camera.y = lerp(camera.y, targetY, 1 - Math.exp(-7 * dt));
}

function text(str, x, y, size = 20, color = "#fff", align = "left") {
  ctx.font = `bold ${size}px ui-monospace, SFMono-Regular, Consolas, monospace`;
  ctx.textAlign = align;
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(str, x, y);
}

function roundedBox(x, y, w, h, radius, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.roundRect(x, y, w, h, radius);
  ctx.fill();
}

function drawBackground() {
  const sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0, "#77c9f5");
  sky.addColorStop(1, "#d6f6ff");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);

  ctx.fillStyle = "#fff5b3";
  ctx.beginPath();
  ctx.arc(890 - camera.x * 0.025, 90, 40, 0, Math.PI * 2);
  ctx.fill();

  for (let i = 0; i < 13; i++) {
    const x = i * 240 - camera.x * 0.16;
    const y = 75 + (i % 4) * 34 - camera.y * 0.04;
    ctx.fillStyle = "#ffffffb5";
    ctx.beginPath();
    ctx.ellipse(x, y, 65, 19, 0, 0, Math.PI * 2);
    ctx.ellipse(x + 25, y - 14, 35, 24, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  for (let layer = 0; layer < 2; layer++) {
    const baseY = 490 + layer * 90 - camera.y * 0.15;
    const parallax = layer === 0 ? 0.20 : 0.34;
    ctx.fillStyle = layer === 0 ? "#86bfd0" : "#6eafb1";
    for (let i = -1; i < 18; i++) {
      const x = i * 380 - camera.x * parallax;
      ctx.beginPath();
      ctx.moveTo(x - 240, H);
      ctx.quadraticCurveTo(x + 100, baseY - 240, x + 430, H);
      ctx.closePath();
      ctx.fill();
    }
  }
}

function drawPlatform(p) {
  if (p.x + p.w < camera.x - 30 || p.x > camera.x + W + 30) return;

  ctx.fillStyle = p.ground ? "#805440" : "#62778a";
  ctx.fillRect(p.x, p.y, p.w, p.h);
  ctx.fillStyle = p.ground ? "#a3714d" : "#839bab";
  ctx.fillRect(p.x, p.y + 9, p.w, p.ground ? 15 : 7);
  ctx.fillStyle = p.ground ? "#62bd65" : "#b4d9d8";
  ctx.fillRect(p.x, p.y, p.w, 8);
  ctx.fillStyle = p.ground ? "#91e47c" : "#e3f7e7";
  ctx.fillRect(p.x, p.y, p.w, 3);

  if (p.ground) {
    ctx.fillStyle = "#553f353f";
    const start = Math.max(0, Math.floor((camera.x - p.x) / 40));
    const end = Math.min(Math.ceil(p.w / 40), start + 31);
    for (let i = start; i < end; i++) {
      for (let row = 0; row < 6; row++) {
        ctx.fillRect(p.x + i * 40 + (row % 2) * 12,
          p.y + 37 + row * 38, 14, 7);
      }
    }
  } else {
    ctx.fillStyle = "#344e65";
    ctx.fillRect(p.x + 8, p.y + 17, 5, 5);
    ctx.fillRect(p.x + p.w - 13, p.y + 17, 5, 5);
  }
}

function drawLoot(item) {
  if (item.taken || Math.abs(item.x - camera.x - W / 2) > W / 2 + 40) return;
  const y = item.y + Math.sin(time * 4 + item.phase) * 4;
  ctx.save();
  ctx.translate(item.x, y);

  if (item.type === "coin") {
    ctx.scale(0.72 + Math.abs(Math.sin(time * 3 + item.phase)) * 0.28, 1);
    ctx.fillStyle = "#ca8d1f";
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#ffda55";
    ctx.beginPath();
    ctx.arc(0, -1, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#fff3a1";
    ctx.fillRect(-2, -6, 3, 10);
  } else if (item.type === "gem") {
    ctx.fillStyle = "#22bfdc";
    ctx.beginPath();
    ctx.moveTo(0, -14);
    ctx.lineTo(12, -3);
    ctx.lineTo(0, 15);
    ctx.lineTo(-12, -3);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#a8ffff";
    ctx.beginPath();
    ctx.moveTo(0, -14);
    ctx.lineTo(3, -2);
    ctx.lineTo(0, 15);
    ctx.lineTo(-12, -3);
    ctx.closePath();
    ctx.fill();
  } else {
    text("♥", 0, 0, 27, "#ff527b", "center");
  }
  ctx.restore();
}

function drawEnemy(e) {
  if (e.dead || e.x < camera.x - 80 || e.x > camera.x + W + 80) return;
  ctx.save();
  ctx.translate(e.x + e.w / 2, e.y + e.h);
  if (e.invuln > 0) ctx.globalAlpha = 0.65;
  const bob = Math.sin(time * 12 + e.x) * 2;

  ctx.fillStyle = "#30334d";
  ctx.fillRect(-16, -6, 12, 6);
  ctx.fillRect(4, -6, 12, 6);
  roundedBox(-17, -31 + bob, 34, 27, 8,
    e.type === "armored" ? "#637890" : "#9660ba");

  if (e.type === "armored") {
    ctx.fillStyle = "#b7ced8";
    ctx.fillRect(-19, -31 + bob, 38, 9);
