  ctx.fillStyle = "#fff";
  ctx.fillRect(-11, -23 + bob, 8, 8);
  ctx.fillRect(4, -23 + bob, 8, 8);
  ctx.fillStyle = "#25243d";
  ctx.fillRect(-8 + e.dir * 2, -20 + bob, 4, 5);
  ctx.fillRect(7 + e.dir * 2, -20 + bob, 4, 5);
  ctx.fillRect(-6, -10 + bob, 13, 3);
  ctx.restore();
}

function drawPlayer() {
  const p = player;
  ctx.save();
  ctx.translate(p.x + p.w / 2, p.y + p.h / 2);
  ctx.scale(p.face, 1);

  if (p.invuln > 0 && Math.floor(time * 18) % 2) ctx.globalAlpha = 0.4;

  const stride = p.grounded ? Math.sin(time * 18) * Math.min(5, Math.abs(p.vx) / 60) : 3;

  // Boots and trousers.
  ctx.fillStyle = "#263c66";
  ctx.fillRect(-11, 8, 9, 11 + stride);
  ctx.fillRect(3, 8, 9, 11 - stride);
