  ctx.fillRect(-9, -6, 5, 17);
  ctx.fillStyle = "#f1b58b";
  ctx.fillRect(10, -2, 7, 12);

  // Head, eye, cap, and scarf.
  roundedBox(-10, -22, 23, 18, 5, "#ffd1a0");
  ctx.fillStyle = "#233f52";
  ctx.fillRect(6, -17, 4, 5);
  ctx.fillStyle = "#156e81";
  ctx.fillRect(-12, -25, 25, 8);
  ctx.fillRect(4, -19, 14, 4);
  ctx.fillStyle = "#ff735b";
  ctx.fillRect(-12, -7, 24, 5);
  ctx.beginPath();
  ctx.moveTo(-11, -6);
  ctx.lineTo(-30, -10 + Math.sin(time * 13) * 3);
  ctx.lineTo(-26, -1);
  ctx.lineTo(-11, -1);
  ctx.fill();

  if (p.attack > 0) {
    const progress = 1 - p.attack / 0.18;
    ctx.save();
    ctx.rotate(-0.9 + progress * 1.8);
    ctx.fillStyle = "#6b4938";
    ctx.fillRect(12, -3, 16, 7);
    ctx.fillStyle = "#ffd96e";
    ctx.fillRect(24, -10, 5, 20);
    ctx.fillStyle = "#e7fbff";
    ctx.beginPath();
    ctx.moveTo(29, -5);
    ctx.lineTo(71, -3);
    ctx.lineTo(81, 0);
    ctx.lineTo(71, 4);
    ctx.lineTo(29, 6);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    ctx.strokeStyle = "#ffffffa0";
    ctx.lineWidth = 5;
    ctx.beginPath();
