      ctx.stroke();
      ctx.setLineDash([]);
      ctx.strokeStyle = "#e5ffff";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(target.x, target.y, 8 + Math.sin(time * 6) * 2, 0, Math.PI * 2);
      ctx.stroke();
