  }
}

function formatTime(seconds) {
  return `${Math.floor(seconds / 60)}:${String(Math.floor(seconds % 60)).padStart(2, "0")}`;
}

function drawHUD() {
  roundedBox(16, 14, 420, 65, 12, "#10263bdb");
