  text(`LOOT ${coins}   ENEMIES ${kills}   ${formatTime(elapsed)}`,
    32, 61, 16, "#e6f3ff");

  roundedBox(W - 244, 14, 228, 65, 12, "#10263bdb");
  text("LEVEL PROGRESS", W - 228, 34, 14, "#c3e4ef");
  ctx.fillStyle = "#3c5367";
  ctx.fillRect(W - 228, 51, 196, 9);
  ctx.fillStyle = "#70e5be";
  ctx.fillRect(W - 228, 51, 196 * clamp(player.x / goal.x, 0, 1), 9);

