}

function drawOverlay() {
  if (state === "playing") return;

  ctx.fillStyle = "#081629bf";
  ctx.fillRect(0, 0, W, H);

  if (state === "title") {
    roundedBox(180, 98, 740, 427, 24, "#142d45ed");
    text("SKYHOOK SPRINT", W / 2, 158, 52, "#8df4dd", "center");
    text("An original 2D grappling platform adventure",
      W / 2, 208, 19, "#deefff", "center");

    const lines = [
      "A / D or ← / →    Move",
