      W / 2, 480, 24, "#ffdd83", "center");
  } else if (state === "paused") {
    text("PAUSED", W / 2, 265, 56, "#fff", "center");
    text("Press P or Esc to resume", W / 2, 326, 22, "#cce9ff", "center");
    text("R restarts the adventure", W / 2, 368, 17, "#b7cbd9", "center");
  } else if (state === "won") {
    roundedBox(245, 140, 610, 340, 24, "#142d45ed");
    text("LEVEL COMPLETE!", W / 2, 205, 43, "#ffdf75", "center");
    text("You reached the golden flag.", W / 2, 258, 22, "#dbf7ff", "center");
    text(`Loot: ${coins}     Enemies defeated: ${kills}`,
      W / 2, 309, 20, "#8bf0d7", "center");
    text(`Time: ${formatTime(elapsed)}     Respawns: ${deaths}`,
      W / 2, 348, 20, "#c8e4f4", "center");
    text("Press Enter, R, or click to play again",
      W / 2, 423, 20, "#ffdf75", "center");
