# 4. Implement server-side registration

Create `Pages/Register.cshtml.cs`:

```csharp
using System.ComponentModel.DataAnnotations;
using GuidedRegistration.Models;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;

namespace GuidedRegistration.Pages;

public class RegisterModel : PageModel
{
    private readonly UserManager<ApplicationUser> _userManager;

    public RegisterModel(UserManager<ApplicationUser> userManager)
    {
        _userManager = userManager;
    }

    [BindProperty]
    public RegistrationInput Input { get; set; } = new();

    public void OnGet()
    {
    }

    public async Task<IActionResult> OnPostFinishAsync()
    {
        if (!ModelState.IsValid)
        {
            return ValidationResponse();
        }

        var user = new ApplicationUser
        {
            FullName = Input.FullName.Trim(),
            Email = Input.Email.Trim(),
            UserName = Input.Email.Trim()
        };

        // Identity hashes the password. Never store a plaintext password.
        var result = await _userManager.CreateAsync(
            user,
            Input.Password);

        if (!result.Succeeded)
        {
            foreach (var error in result.Errors)
            {
                var field = error.Code.StartsWith(
                    "Password",
                    StringComparison.OrdinalIgnoreCase)
                    ? "Input.Password"
                    : "Input.Email";

                // Avoid exposing detailed account-existence information.
                var message = field == "Input.Password"
                    ? error.Description
                    : "Unable to register with this email address.";

                ModelState.AddModelError(field, message);
            }

            return ValidationResponse();
        }

        return new JsonResult(new
        {
            success = true,
            message = "Your account has been created."
        });
    }

    private JsonResult ValidationResponse()
    {
        var errors = ModelState
            .Where(entry => entry.Value?.Errors.Count > 0)
            .ToDictionary(
                entry => entry.Key,
                entry => entry.Value!.Errors
                    .Select(error =>
                        string.IsNullOrWhiteSpace(error.ErrorMessage)
                            ? "Invalid value."
                            : error.ErrorMessage)
                    .ToArray());

        return new JsonResult(new
        {
            success = false,
            errors
        })
        {
            StatusCode = StatusCodes.Status400BadRequest
        };
    }

    public class RegistrationInput
    {
        [Required]
        [StringLength(100, MinimumLength = 2)]
        public string FullName { get; set; } = "";

        [Required]
        [EmailAddress]
        [StringLength(254)]
        public string Email { get; set; } = "";

        [Required]
        [StringLength(128, MinimumLength = 12)]
        public string Password { get; set; } = "";

        [Required]
        [Compare(nameof(Password),
            ErrorMessage = "Passwords do not match.")]
        public string ConfirmPassword { get; set; } = "";
    }
}
```

**Important:** Never trust the step number sent by a browser. A user can bypass JavaScript and directly call the endpoint. This handler validates all fields regardless of the UI state.

