# 7. Implement the guided process controller

Create `wwwroot/js/guided-registration.js`:

```javascript
(() => {
    const form = document.getElementById("registration");
    const guide = document.getElementById("guide");
    const backdrop = document.getElementById("backdrop");
    const result = document.getElementById("result");

    const title = document.getElementById("guide-title");
    const instruction = document.getElementById("instruction");
    const progress = document.getElementById("progress");
    const error = document.getElementById("error");

    const backButton = document.getElementById("back");
    const nextButton = document.getElementById("next");

    /*
     * Declarative process definition.
     * Add or reorder steps here rather than rewriting navigation.
     */
    const steps = [
        {
            containerId: "step-name",
            inputId: "fullName",
            serverField: "Input.FullName",
            title: "Tell us your name",
            instruction:
                "Enter your full name. Select Next when you have entered at least two characters."
        },
        {
            containerId: "step-email",
            inputId: "email",
            serverField: "Input.Email",
            title: "Add your email address",
            instruction:
                "Enter a valid email address, such as alex@example.com, then select Next."
        },
        {
            containerId: "step-password",
            inputId: "password",
            serverField: "Input.Password",
            title: "Create a password",
            instruction:
                "Use at least 12 characters, including uppercase and lowercase letters and a number."
        },
        {
            containerId: "step-confirm",
            inputId: "confirmPassword",
            serverField: "Input.ConfirmPassword",
            title: "Confirm your password",
            instruction:
                "Enter the same password again. Select Create account to complete registration."
        }
    ].map(step => ({
        ...step,
        container: document.getElementById(step.containerId),
        input: document.getElementById(step.inputId)
    }));

    let currentIndex = 0;
    let submitting = false;

    function showStep(index) {
        currentIndex = index;
        error.textContent = "";

        steps.forEach((step, stepIndex) => {
            const active = stepIndex === currentIndex;

            step.container.disabled = !active;
            step.container.inert = !active;
            step.container.classList.toggle("active", active);
        });

        const current = steps[currentIndex];

        progress.textContent =
            `Step ${currentIndex + 1} of ${steps.length}`;

        title.textContent = current.title;
        instruction.textContent = current.instruction;

        updateButtons();

        current.container.scrollIntoView({
            behavior: "auto",
            block: "center"
        });

        current.input.focus({ preventScroll: true });
    }

    function updateButtons() {
        backButton.disabled = submitting || currentIndex === 0;
        nextButton.disabled = submitting;

        nextButton.textContent = submitting
            ? "Creating account..."
            : currentIndex === steps.length - 1
                ? "Create account"
                : "Next";
    }

    function validateCurrentStep() {
        const current = steps[currentIndex];
        const input = current.input;

        input.setCustomValidity("");

        if (input.id === "fullName") {
            input.value = input.value.trim();

            if (input.value.length < 2) {
                input.setCustomValidity(
                    "Enter at least two characters for your name."
                );
            }
        }

        if (input.id === "confirmPassword") {
            const password =
                document.getElementById("password").value;

            if (input.value !== password) {
                input.setCustomValidity(
                    "Passwords do not match."
                );
            }
        }

        if (!input.checkValidity()) {
            error.textContent = input.validationMessage;
            input.reportValidity();
            return false;
        }

        return true;
    }

    /*
     * Disabled controls are not included in FormData.
     *
     * Temporarily enable the fieldsets while taking the snapshot,
     * then immediately restore their previous state.
     *
     * This is synchronous, so the browser does not render an
     * intermediate state where all fields are editable.
     */
    function collectFormData() {
        const previousStates = steps.map(step =>
            step.container.disabled
        );

        try {
            steps.forEach(step => {
                step.container.disabled = false;
            });

            return new FormData(form);
        } finally {
            steps.forEach((step, index) => {
                step.container.disabled = previousStates[index];
            });
        }
    }

    function showServerErrors(errors) {
        const invalidStepIndex = steps.findIndex(step =>
            errors[step.serverField]?.length > 0
        );

        if (invalidStepIndex >= 0) {
            showStep(invalidStepIndex);
        }

        // Use textContent, not innerHTML, for server-provided text.
        error.textContent =
            Object.values(errors).flat().join(" ") ||
            "Please check your information and try again.";
    }

    function showSuccess(message) {
        form.reset();
        form.hidden = true;
        guide.hidden = true;
        backdrop.hidden = true;

        document.querySelectorAll("[data-outside]")
            .forEach(element => {
                element.inert = false;
            });

        result.textContent = message;
        result.hidden = false;
        result.focus();
    }

    async function finishRegistration() {
        submitting = true;
        updateButtons();
        error.textContent = "";

        try {
            const data = collectFormData();

            // Prevent editing the active field during submission.
            steps[currentIndex].container.disabled = true;

            const response = await fetch(form.action, {
                method: "POST",
                body: data,
                credentials: "same-origin",
                headers: {
                    "Accept": "application/json"
                }
            });

            const contentType =
                response.headers.get("content-type") || "";

            if (!contentType.includes("application/json")) {
                throw new Error("Unexpected server response.");
            }

            const body = await response.json();

            if (!response.ok || !body.success) {
                if (body.errors) {
                    showServerErrors(body.errors);
                    return;
                }

                throw new Error("Registration failed.");
            }

            showSuccess(body.message);
        } catch {
            error.textContent =
                "We could not complete registration. Please try again. " +
                "If the account was already created, use sign-in or account recovery.";
        } finally {
            submitting = false;

            if (!form.hidden) {
                steps[currentIndex].container.disabled = false;
                updateButtons();
            }
        }
    }

    backButton.addEventListener("click", () => {
        if (!submitting && currentIndex > 0) {
            showStep(currentIndex - 1);
        }
    });

    form.addEventListener("submit", async event => {
        event.preventDefault();

        if (submitting || !validateCurrentStep()) {
            return;
        }

        if (currentIndex < steps.length - 1) {
            showStep(currentIndex + 1);
        } else {
            await finishRegistration();
        }
    });

    steps.forEach(step => {
        step.input.addEventListener("input", () => {
            step.input.setCustomValidity("");
            error.textContent = "";
        });
    });

    showStep(0);
})();
```

Run the application and open:

```text
https://localhost:<port>/Register
```

