    --border: #dedfeb;
    --text: #292d43;
    --muted: #73788e;
    --accent: #7052d7;
    --accent-soft: #7052d712;
    --green: #258251;
    --red: #c54861;
    --selection: #a18be955;
    --keyword: #8451c5;
    --string: #438143;
    --number: #ba751c;
    --comment: #9195a6;
    --tag: #277ea9;
    --heading: #ac712b;
    --shadow: 0 20px 80px #25255020;
    color-scheme: light;
  }

  [data-theme="midnight"] {
    --bg: #070e16;
    --panel: #0c1722;
    --panel2: #132332;
    --editor: #09111b;
    --border: #203446;
    --text: #d7e7ef;
    --muted: #7a98ae;
    --accent: #60d7d0;
    --accent-soft: #60d7d015;
    --keyword: #81b5ff;
    --string: #8fe0b1;
    --tag: #68d0d6;
    --selection: #60d7d035;
  }

  * { box-sizing: border-box; }
  body {
    margin: 0;
    height: 100vh;
    height: 100dvh;
    overflow: hidden;
    background: var(--bg);
    color: var(--text);
    font: 13px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  }
  button, input, select { font: inherit; }
  button, select { cursor: pointer; }
  button {
    color: var(--muted);
    background: none;
    border: 1px solid transparent;
    border-radius: 7px;
    padding: 7px 10px;
    white-space: nowrap;
  }
  button:hover { background: var(--panel2); color: var(--text); }
  button:active { transform: translateY(1px); }
  button:disabled { opacity: .35; cursor: default; }
  button.active { background: var(--accent-soft); color: var(--accent); }
  button.primary {
    background: var(--accent);
    color: var(--bg);
    font-weight: 650;
  }
  button.primary:hover { filter: brightness(1.12); }
  button.danger { color: var(--red); }
  input, select {
    min-width: 0;
    padding: 8px 10px;
    color: var(--text);
    background: var(--editor);
    border: 1px solid var(--border);
    border-radius: 7px;
    outline: none;
  }
  input:focus, select:focus { border-color: var(--accent); }
  :focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  [hidden] { display: none !important; }
  kbd {
    font: 10px ui-monospace, monospace;
    border: 1px solid var(--border);
    padding: 2px 5px;
    border-radius: 4px;
    color: var(--muted);
  }
  .app { height: 100%; display: flex; flex-direction: column; }
  .topbar {
    display: flex;
    align-items: center;
    gap: 15px;
    min-height: 65px;
    padding: 10px 18px;
    background: var(--panel);
    border-bottom: 1px solid var(--border);
  }
  .brand { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
  .logo {
    width: 35px;
    height: 35px;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background: var(--accent);
    color: var(--bg);
    font: bold 21px Georgia, serif;
    box-shadow: 0 4px 18px var(--accent-soft);
  }
  .brand strong { font-size: 17px; letter-spacing: -.5px; }
  .brand small { display: block; color: var(--muted); font-size: 10px; letter-spacing: 1.7px; }
  .toolbar { display: flex; align-items: center; gap: 4px; flex: 1; overflow-x: auto; }
  .separator { height: 22px; width: 1px; background: var(--border); margin: 0 6px; flex-shrink: 0; }
  .toolbar-end { display: flex; gap: 3px; margin-left: auto; }
  .main { flex: 1; display: flex; min-height: 0; }
  .sidebar {
    width: 215px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    border-right: 1px solid var(--border);
    background: var(--panel);
  }
  .sidebar-head {
    padding: 18px 14px 10px;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  .eyebrow { color: var(--muted); font-size: 10px; letter-spacing: 1.5px; font-weight: 700; }
  .badge { background: var(--panel2); border-radius: 5px; padding: 2px 6px; color: var(--muted); font-size: 10px; }
  .documents { padding: 4px 8px; flex: 1; overflow: auto; }
  .document {
    width: 100%;
    display: flex;
    gap: 10px;
    align-items: center;
    text-align: left;
    margin-bottom: 4px;
    padding: 10px;
  }
  .file-icon {
    flex-shrink: 0;
    display: grid;
    place-items: center;
    width: 29px;
    height: 32px;
    background: var(--panel2);
    border: 1px solid var(--border);
    border-radius: 6px;
    color: var(--accent);
    font: bold 9px ui-monospace, monospace;
  }
  .doc-info { min-width: 0; }
  .doc-name { overflow: hidden; text-overflow: ellipsis; font-size: 12px; }
  .doc-meta { font-size: 10px; color: var(--muted); margin-top: 3px; }
  .sidebar-foot { padding: 14px; border-top: 1px solid var(--border); }
  .sidebar-foot p { color: var(--muted); font-size: 11px; margin: 8px 0 0; }
  .storage-dot {
    display: inline-block;
    width: 6px;
    height: 6px;
    background: var(--green);
    border-radius: 50%;
    margin-right: 5px;
  }
  .center { display: flex; flex-direction: column; flex: 1; min-width: 0; min-height: 0; }
  .tabs {
    display: flex;
    align-items: center;
    overflow-x: auto;
    min-height: 43px;
    background: var(--panel);
    border-bottom: 1px solid var(--border);
  }
  .tab {
    display: flex;
    align-items: center;
    flex-shrink: 0;
    border-right: 1px solid var(--border);
    border-bottom: 2px solid transparent;
    height: 43px;
    padding: 0 7px 0 3px;
  }
  .tab.active { background: var(--editor); border-bottom-color: var(--accent); }
  .tab .tab-name { max-width: 180px; overflow: hidden; text-overflow: ellipsis; font-size: 12px; }
  .tab.active .tab-name { color: var(--text); }
  .tab .close { padding: 1px 6px; font-size: 16px; }
  .breadcrumb {
    height: 35px;
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 0 18px;
    color: var(--muted);
    font-size: 11px;
    background: var(--editor);
    border-bottom: 1px solid var(--border);
  }
  .breadcrumb .filename { color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .breadcrumb .hint { margin-left: auto; white-space: nowrap; }
  .findbar {
    padding: 10px 14px;
    background: var(--panel);
    border-bottom: 1px solid var(--border);
  }
  .find-row { display: flex; gap: 5px; align-items: center; margin: 3px 0; }
  .find-row input { width: 230px; }
  .find-row .match-count { color: var(--muted); font-size: 11px; min-width: 90px; }
  .find-row .mini { padding: 6px 8px; font: 12px ui-monospace, monospace; }
  .find-error { font-size: 11px; color: var(--red); }
  .edit-area { display: flex; flex: 1; min-height: 0; }
  .editor-pane { display: flex; flex: 1; min-width: 0; background: var(--editor); position: relative; }
  .gutter {
    width: 58px;
    flex-shrink: 0;
    overflow: hidden;
    border-right: 1px solid var(--border);
    user-select: none;
  }
  .gutter-inner {
    padding-top: 18px;
    padding-bottom: 18px;
    color: var(--muted);
    text-align: right;
    font: var(--font-size)/var(--line-height) ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    opacity: .65;
  }
  .line-number { padding-right: 14px; }
  .line-number.current { color: var(--accent); opacity: 1; background: var(--accent-soft); }
  .code-stack { flex: 1; min-width: 0; overflow: hidden; position: relative; }
  .code-font {
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
    font-size: var(--font-size);
    line-height: var(--line-height);
    font-weight: 400;
    font-style: normal;
    letter-spacing: 0;
    font-variant-ligatures: none;
    tab-size: 2;
  }
  #highlight {
    position: absolute;
    top: 0;
    left: 0;
    margin: 0;
    padding: 18px;
    min-width: 100%;
    width: max-content;
    color: var(--text);
    pointer-events: none;
    white-space: pre;
    will-change: transform;
  }
  .code-line { min-height: var(--line-height); }
  #editor {
    position: absolute;
    inset: 0;
    resize: none;
    border: 0;
    border-radius: 0;
    margin: 0;
    padding: 18px;
    width: 100%;
    height: 100%;
    background: transparent;
    color: transparent;
    -webkit-text-fill-color: transparent;
    caret-color: var(--text);
    outline: none;
    white-space: pre;
    overflow: auto;
    overflow-wrap: normal;
    box-shadow: none;
  }
  #editor::selection { background: var(--selection); }
  .code-stack.wrap #highlight {
    width: 100%;
    min-width: 0;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    word-break: break-all;
  }
  .code-stack.wrap #editor {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    word-break: break-all;
  }
  .tok-keyword { color: var(--keyword); }
  .tok-string { color: var(--string); }
  .tok-number { color: var(--number); }
  .tok-comment { color: var(--comment); }
  .tok-tag { color: var(--tag); }
  .tok-heading { color: var(--heading); }
  .tok-operator { color: var(--accent); }
  .search-hit { background: #e5b45428; border-radius: 2px; box-shadow: inset 0 -1px #e5b45480; }
  .preview-pane {
    width: 43%;
    min-width: 220px;
    border-left: 1px solid var(--border);
    display: flex;
    flex-direction: column;
    background: var(--panel);
  }
  .preview-head { display: flex; align-items: center; padding: 7px 12px; border-bottom: 1px solid var(--border); }
  .preview-head span { flex: 1; color: var(--muted); font-size: 11px; }
  .preview-pane iframe { border: 0; width: 100%; flex: 1; background: white; }
  .statusbar {
    display: flex;
    align-items: center;
    gap: 15px;
    min-height: 31px;
    padding: 2px 14px;
    border-top: 1px solid var(--border);
    background: var(--panel);
    font-size: 10px;
    color: var(--muted);
    overflow-x: auto;
    white-space: nowrap;
  }
  .statusbar .spacer { flex: 1; }
  .statusbar button { font-size: 10px; padding: 2px 5px; }
  .statusbar select { padding: 2px 4px; background: transparent; border: 0; font-size: 10px; }
  #saveStatus { color: var(--green); }
  .modal {
    position: fixed;
    inset: 0;
    z-index: 30;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    padding: 12vh 20px 30px;
    background: #0007;
    backdrop-filter: blur(5px);
  }
  .dialog {
    width: 560px;
    max-width: 100%;
    max-height: 78vh;
    overflow: auto;
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 14px;
    box-shadow: var(--shadow);
  }
  .dialog-head { display: flex; align-items: center; justify-content: space-between; padding: 16px 22px; border-bottom: 1px solid var(--border); }
  .dialog-head h2 { font-size: 16px; margin: 0; }
  .dialog-body { padding: 12px 22px 22px; }
  .setting-row { display: flex; justify-content: space-between; align-items: center; gap: 15px; padding: 12px 0; border-bottom: 1px solid var(--border); }
  .setting-row small { display: block; color: var(--muted); font-size: 11px; margin-top: 3px; }
  .setting-row input[type=checkbox] { width: 17px; height: 17px; accent-color: var(--accent); }
  .setting-row input[type=number] { width: 76px; }
  .dialog-note { color: var(--muted); font-size: 11px; margin: 18px 0 0; }
  #commandInput { width: 100%; padding: 19px 22px; background: transparent; border: 0; border-bottom: 1px solid var(--border); border-radius: 0; font-size: 15px; }
  .commands { padding: 7px; max-height: 410px; overflow: auto; }
  .command { width: 100%; display: flex; justify-content: space-between; text-align: left; padding: 11px 13px; }
  .command.selected { background: var(--accent-soft); color: var(--accent); }
  .palette-footer { padding: 10px 20px; border-top: 1px solid var(--border); color: var(--muted); font-size: 10px; }
  .shortcut-row { display: flex; justify-content: space-between; gap: 15px; padding: 9px 0; border-bottom: 1px solid var(--border); }
  .toasts { position: fixed; bottom: 48px; right: 20px; z-index: 60; display: flex; flex-direction: column; gap: 8px; pointer-events: none; }
  .toast { background: var(--panel2); border: 1px solid var(--border); color: var(--text); padding: 12px 17px; border-radius: 10px; box-shadow: var(--shadow); max-width: 360px; animation: appear .18s ease-out; }
  .drop-overlay {
    position: fixed;
    inset: 12px;
    z-index: 70;
    border: 2px dashed var(--accent);
    border-radius: 18px;
    background: var(--bg);
    opacity: .96;
    display: grid;
    place-content: center;
    text-align: center;
    pointer-events: none;
  }
  .drop-overlay strong { font-size: 26px; color: var(--accent); }
  .drop-overlay p { color: var(--muted); }
  .focus-mode .topbar, .focus-mode .sidebar, .focus-mode .breadcrumb { display: none; }
  ::-webkit-scrollbar { width: 9px; height: 7px; }
  ::-webkit-scrollbar-thumb { background: var(--border); border: 2px solid transparent; background-clip: padding-box; border-radius: 9px; }
  ::-webkit-scrollbar-corner { background: transparent; }
  @keyframes appear { from { transform: translateY(6px); opacity: 0; } }
  @media (max-width: 950px) {
    .sidebar { display: none; }
    .brand small, .desktop-label { display: none; }
    .topbar { gap: 10px; padding: 10px; }
    .toolbar { gap: 2px; }
    .toolbar button { padding: 7px 8px; }
    .preview-pane { width: 45%; }
  }
  @media (max-width: 600px) {
    .brand strong { display: none; }
    .toolbar-end { margin-left: 0; }
    .topbar { min-height: 55px; }
    .logo { width: 30px; height: 30px; }
    .breadcrumb .hint, #wordCount, #encoding { display: none; }
    .find-row { flex-wrap: wrap; }
    .find-row input { flex: 1; min-width: 115px; }
    .edit-area { flex-direction: column; }
    .editor-pane { min-height: 130px; }
    .preview-pane { width: 100%; height: 45%; min-height: 100px; border-left: 0; border-top: 1px solid var(--border); }
    .gutter { width: 43px; }
    .statusbar { gap: 9px; padding: 2px 8px; }
    .modal { padding: 7vh 12px; }
    .dialog { max-height: 86vh; }
  }
</style>
</head>
<body>
<div class="app" id="app">
  <header class="topbar">
    <div class="brand">
      <div class="logo">N</div>
      <div><strong>notebox</strong><small>SPACE FOR YOUR IDEAS</small></div>
    </div>
    <nav class="toolbar" aria-label="Editor toolbar">
      <button id="newBtn" title="New document — Ctrl/⌘ Alt N">＋ New</button>
      <button id="openBtn" title="Open files — Ctrl/⌘ O">Open</button>
      <button id="saveBtn" class="primary" title="Download current file — Ctrl/⌘ S">↓ Save</button>
      <span class="separator"></span>
      <button id="undoBtn" title="Undo — Ctrl/⌘ Z">↶</button>
      <button id="redoBtn" title="Redo — Ctrl/⌘ Shift Z">↷</button>
      <button id="findBtn" title="Find and replace — Ctrl/⌘ F">Find</button>
      <button id="previewBtn" title="Toggle live preview">Preview</button>
      <div class="toolbar-end">
        <button id="paletteBtn" title="Command palette — Ctrl/⌘ K">⌘ <span class="desktop-label">Commands</span></button>
        <button id="settingsBtn" title="Settings">⚙</button>
      </div>
    </nav>
  </header>

  <div class="main">
    <aside class="sidebar" aria-label="Workspace documents">
      <div class="sidebar-head">
        <span class="eyebrow">WORKSPACE</span>
        <span class="badge" id="docCount">1</span>
      </div>
      <div class="documents" id="documents"></div>
      <div class="sidebar-foot">
        <button id="backupBtn" style="width:100%;text-align:left">↗ Export workspace</button>
        <button id="helpBtn" style="width:100%;text-align:left">⌨ Keyboard shortcuts</button>
        <p><span class="storage-dot"></span>Private by default. Stored locally.</p>
        <p>Double-click a tab to rename it.<br>Drop text files anywhere to open.</p>
      </div>
    </aside>

    <main class="center">
      <div class="tabs" id="tabs" aria-label="Open documents"></div>
      <div class="breadcrumb">
        <span>workspace</span><span>/</span><span class="filename" id="filename"></span>
        <span class="hint">Create something good. <kbd>Ctrl/⌘ K</kbd></span>
      </div>

      <section class="findbar" id="findbar" hidden aria-label="Find and replace">
        <div class="find-row">
          <input id="findInput" aria-label="Find text" placeholder="Find in document…" autocomplete="off">
          <button class="mini" id="caseBtn" title="Match case" aria-pressed="false">Aa</button>
          <button class="mini" id="wordBtn" title="Whole word" aria-pressed="false">W</button>
          <button class="mini" id="regexBtn" title="Regular expression" aria-pressed="false">.*</button>
          <span class="match-count" id="matchCount">No results</span>
          <button id="prevMatch" title="Previous match">↑</button>
          <button id="nextMatch" title="Next match">↓</button>
          <button id="closeFind" title="Close find">×</button>
        </div>
        <div class="find-row">
          <input id="replaceInput" aria-label="Replacement text" placeholder="Replace with…">
          <button id="replaceBtn">Replace</button>
          <button id="replaceAllBtn">Replace all</button>
        </div>
        <div class="find-error" id="findError"></div>
      </section>

      <div class="edit-area">
        <section class="editor-pane" aria-label="Text editor">
          <div class="gutter" id="gutter" aria-hidden="true"><div class="gutter-inner" id="lineNumbers"></div></div>
          <div class="code-stack" id="codeStack">
            <div id="highlight" class="code-font" aria-hidden="true"></div>
            <textarea id="editor" class="code-font" spellcheck="false" autocapitalize="off"
              autocomplete="off" autocorrect="off" wrap="off" aria-label="Document content"></textarea>
          </div>
        </section>

        <section class="preview-pane" id="previewPane" hidden aria-label="Document preview">
          <div class="preview-head">
            <span>LIVE PREVIEW · scripts disabled</span>
            <button id="closePreview" title="Close preview">×</button>
          </div>
          <iframe id="previewFrame" title="Sandboxed document preview" sandbox="" referrerpolicy="no-referrer"></iframe>
        </section>
      </div>

      <footer class="statusbar">
        <span id="saveStatus">● Saved locally</span>
        <span class="spacer"></span>
        <span id="wordCount">0 words</span>
        <span id="charCount">0 chars</span>
        <button id="cursorStatus" title="Go to line — Ctrl/⌘ G">Ln 1, Col 1</button>
        <button id="indentStatus" title="Change indentation settings">Spaces: 2</button>
        <button id="wrapStatus" title="Toggle word wrap — Alt Z">Wrap: Off</button>
        <span id="encoding">UTF-8 · LF</span>
        <select id="language" aria-label="Syntax language"></select>
      </footer>
    </main>
  </div>
</div>

<div class="modal" id="settingsModal" hidden>
  <section class="dialog" role="dialog" aria-modal="true" aria-labelledby="settingsTitle" tabindex="-1">
    <div class="dialog-head"><h2 id="settingsTitle">Make it yours</h2><button data-close title="Close settings">×</button></div>
    <div class="dialog-body">
      <label class="setting-row"><span>Color theme<small>A little change of scenery.</small></span>
        <select id="themeSetting"><option value="dark">Lavender dark</option><option value="midnight">Ocean midnight</option><option value="light">Paper light</option></select>
      </label>
      <label class="setting-row"><span>Font size<small>Zoom with Ctrl/⌘ + or −.</small></span><input id="fontSetting" type="number" min="10" max="30"></label>
      <label class="setting-row"><span>Indent size</span><select id="tabSetting"><option value="2">2 spaces</option><option value="4">4 spaces</option><option value="8">8 spaces</option></select></label>
      <label class="setting-row"><span>Word wrap</span><input id="wrapSetting" type="checkbox"></label>
      <label class="setting-row"><span>Line numbers</span><input id="linesSetting" type="checkbox"></label>
      <label class="setting-row"><span>Auto-close brackets & quotes</span><input id="pairsSetting" type="checkbox"></label>
      <label class="setting-row"><span>Autosave workspace<small>Saved in this browser, not to your disk.</small></span><input id="autosaveSetting" type="checkbox"></label>
      <p class="dialog-note">Save downloads the active document. Export workspace backs up all tabs. Browser storage can be cleared or unavailable in private browsing—keep backups of important work.</p>
      <div style="display:flex;gap:8px;margin-top:18px">
        <button id="fullscreenBtn">Toggle fullscreen</button>
        <button id="focusBtn">Focus mode</button>
      </div>
    </div>
  </section>
</div>

<div class="modal" id="paletteModal" hidden>
  <section class="dialog" role="dialog" aria-modal="true" aria-label="Command palette" tabindex="-1">
    <input id="commandInput" placeholder="What would you like to do?" aria-label="Search commands" autocomplete="off">
    <div class="commands" id="commands"></div>
    <div class="palette-footer">↑ ↓ navigate &nbsp; · &nbsp; Enter run &nbsp; · &nbsp; Esc close</div>
  </section>
</div>

<div class="modal" id="helpModal" hidden>
  <section class="dialog" role="dialog" aria-modal="true" aria-labelledby="helpTitle" tabindex="-1">
    <div class="dialog-head"><h2 id="helpTitle">Keyboard shortcuts</h2><button data-close title="Close shortcuts">×</button></div>
    <div class="dialog-body" id="shortcutList"></div>
  </section>
</div>

<div class="drop-overlay" id="dropOverlay" hidden>
  <strong>Drop it like a thought.</strong>
  <p>Open text files or restore a .notebox.json workspace</p>
</div>
<div class="toasts" id="toasts" role="status" aria-live="polite"></div>
<input type="file" id="fileInput" multiple hidden>

<script>
(() => {
  "use strict";

  const $ = id => document.getElementById(id);
  const editor = $("editor");
  const highlight = $("highlight");
  const STORE = "notebox.workspace.v1";
  const MAX_FILE = 3 * 1024 * 1024;
  const HIGHLIGHT_LIMIT = 220000;
  const languages = {
    text: "Plain Text", javascript: "JavaScript", typescript: "TypeScript",
    html: "HTML", css: "CSS", json: "JSON", markdown: "Markdown",
    python: "Python", sql: "SQL", xml: "XML", shell: "Shell"
  };
  const defaults = {
    theme: "dark", fontSize: 14, tabSize: 2,
    wrap: false, lineNumbers: true, autoPairs: true, autosave: true
  };
  const uid = () => globalThis.crypto?.randomUUID?.() ||
    Date.now().toString(36) + Math.random().toString(36).slice(2);
  const escapeHTML = text => String(text).replace(/[&<>"']/g, c =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const normalize = text => text.replace(/\r\n?/g, "\n");
  const inferLanguage = name => {
    const ext = name.split(".").pop().toLowerCase();
    return ({
      js: "javascript", mjs: "javascript", cjs: "javascript",
      ts: "typescript", jsx: "javascript", tsx: "typescript",
      html: "html", htm: "html", css: "css", json: "json",
      md: "markdown", markdown: "markdown", py: "python",
      sql: "sql", xml: "xml", svg: "xml", sh: "shell", bash: "shell"
    })[ext] || "text";
  };
  const makeDoc = (name, text = "", lang = inferLanguage(name)) => ({
    id: uid(), name, text, lang, cursor: 0, scroll: 0
  });

  const starter = [
    "// Welcome to Notebox ✨",
    "// A small workspace for big ideas.",
    "//",
    "// Ctrl/⌘ K    Open the command palette",
    "// Ctrl/⌘ S    Download this file",
    "// Ctrl/⌘ F    Find and replace",
    "// Alt Z       Toggle word wrap",
    "//",
    "// Try opening a .md or .html file, then click Preview.",
    "",
    "const ideas = [",
    '  "Build something useful",',
    '  "Keep learning",',
    '  "Make it your own"',
    "];",
    "",
    "function startCreating(name) {",
    "  return ideas.map((idea, index) => ({",
    "    id: index + 1,",
    "    author: name,",
    "    idea,",
    "    done: false",
    "  }));",
    "}",
    "",
    'console.log(startCreating("You"));',
    ""
  ].join("\n");

  let state = { docs: [makeDoc("welcome.js", starter)], active: "", settings: { ...defaults } };
  let loadWarning = "";
  function sanitizeSettings(s = {}) {
    const out = { ...defaults };
    if (["dark", "light", "midnight"].includes(s.theme)) out.theme = s.theme;
    if (Number.isFinite(+s.fontSize)) out.fontSize = Math.max(10, Math.min(30, +s.fontSize));
    if ([2, 4, 8].includes(+s.tabSize)) out.tabSize = +s.tabSize;
    for (const key of ["wrap", "lineNumbers", "autoPairs", "autosave"])
      if (typeof s[key] === "boolean") out[key] = s[key];
    return out;
  }
  function sanitizeDocs(docs) {
    if (!Array.isArray(docs)) throw new Error("Invalid workspace");
    return docs.filter(d => d && typeof d.text === "string" && typeof d.name === "string")
      .slice(0, 100).map(d => ({
        id: uid(), name: d.name.slice(0, 160) || "untitled.txt",
        text: normalize(d.text),
        lang: languages[d.lang] ? d.lang : inferLanguage(d.name),
        cursor: Math.max(0, Math.min(d.text.length, Number(d.cursor) || 0)),
        scroll: Math.max(0, Number(d.scroll) || 0)
      }));
  }
  try {
    const raw = localStorage.getItem(STORE);
    if (raw) {
      const saved = JSON.parse(raw);
      const activeIndex = saved.docs?.findIndex(d => d.id === saved.active);
      const docs = sanitizeDocs(saved.docs);
      if (docs.length) {
        state.docs = docs;
        state.active = docs[Math.max(0, Math.min(docs.length - 1, activeIndex || 0))].id;
        state.settings = sanitizeSettings(saved.settings);
      }
    }
  } catch {
    loadWarning = "Could not restore browser storage. You can still edit and download files.";
  }
  if (!state.active) state.active = state.docs[0].id;

  let dirty = false, saveTimer, renderFrame, previewTimer;
  let matches = [], currentMatch = -1;
  let searchOptions = { case: false, word: false, regex: false };
  let beforeSnapshot = null, composition = false;
  let returnFocus = null;
  const histories = new Map();
  const doc = () => state.docs.find(d => d.id === state.active);
  const snapshot = () => ({ text: editor.value, start: editor.selectionStart, end: editor.selectionEnd });
  const history = () => {
    if (!histories.has(state.active))
      histories.set(state.active, { undo: [], redo: [], time: 0, kind: "" });
    return histories.get(state.active);
  };

  function toast(message) {
    const node = document.createElement("div");
    node.className = "toast";
    node.textContent = message;
    $("toasts").append(node);
    setTimeout(() => node.remove(), 3600);
  }

  function captureView() {
    doc().cursor = editor.selectionStart;
    doc().scroll = editor.scrollTop;
  }
  function persist() {
    clearTimeout(saveTimer);
    captureView();
    try {
      localStorage.setItem(STORE, JSON.stringify(state));
      dirty = false;
      $("saveStatus").textContent = "● Saved locally";
      $("saveStatus").style.color = "var(--green)";
      return true;
    } catch {
      dirty = true;
      $("saveStatus").textContent = "● Storage full / unavailable";
      $("saveStatus").style.color = "var(--red)";
      return false;
    }
  }
  function scheduleSave() {
    dirty = true;
    $("saveStatus").textContent = state.settings.autosave ? "● Saving…" : "● Not saved locally";
    $("saveStatus").style.color = "var(--muted)";
    clearTimeout(saveTimer);
    if (state.settings.autosave) saveTimer = setTimeout(persist, 500);
  }

  function renderDocuments() {
    $("docCount").textContent = state.docs.length;
    $("documents").replaceChildren();
    $("tabs").replaceChildren();
    for (const d of state.docs) {
      const active = d.id === state.active;
      const item = document.createElement("button");
      item.className = "document" + (active ? " active" : "");
      item.innerHTML = `<span class="file-icon">${escapeHTML(d.name.split(".").pop().slice(0, 4).toUpperCase())}</span>
        <span class="doc-info"><div class="doc-name">${escapeHTML(d.name)}</div>
        <div class="doc-meta">${languages[d.lang]} · ${d.text.split("\n").length} lines</div></span>`;
      item.onclick = () => switchDoc(d.id);
      item.ondblclick = () => renameDoc(d.id);
      $("documents").append(item);

      const tab = document.createElement("div");
      tab.className = "tab" + (active ? " active" : "");
      const name = document.createElement("button");
      name.className = "tab-name";
      name.textContent = d.name;
      name.title = d.name + " — double-click to rename";
      name.onclick = () => switchDoc(d.id);
      name.ondblclick = () => renameDoc(d.id);
      if (active) name.setAttribute("aria-current", "page");
      const close = document.createElement("button");
      close.className = "close";
      close.textContent = "×";
      close.title = "Remove " + d.name + " from workspace";
      close.setAttribute("aria-label", close.title);
      close.onclick = () => closeDoc(d.id);
      tab.append(name, close);
      $("tabs").append(tab);
    }
    const add = document.createElement("button");
    add.textContent = "＋";
    add.title = "New document";
    add.onclick = newDoc;
    $("tabs").append(add);
    $("filename").textContent = doc().name;
    document.title = doc().name + " — Notebox";
    $("language").value = doc().lang;
  }

  function loadActive() {
    editor.value = doc().text;
    const cursor = Math.min(doc().cursor || 0, editor.value.length);
    editor.setSelectionRange(cursor, cursor);
    editor.scrollTop = doc().scroll || 0;
    editor.scrollLeft = 0;
    renderDocuments();
    updateSearch(false);
    renderCode();
    updateStatus();
    updatePreview();
    requestAnimationFrame(() => {
      editor.scrollTop = doc().scroll || 0;
      syncScroll();
    });
  }
  function switchDoc(id) {
    if (id === state.active) return;
    captureView();
    beforeSnapshot = null;
    state.active = id;
    loadActive();
    editor.focus();
    scheduleSave();
  }
  function newDoc() {
    let n = 1;
    while (state.docs.some(d => d.name === `untitled-${n}.txt`)) n++;
    addDoc(makeDoc(`untitled-${n}.txt`));
  }
  function addDoc(d) {
    captureView();
    state.docs.push(d);
    state.active = d.id;
    loadActive();
    editor.focus();
    scheduleSave();
  }
  function renameDoc(id = state.active) {
    const d = state.docs.find(d => d.id === id);
    const name = prompt("Document name:", d.name);
    if (!name?.trim()) return;
    d.name = name.trim().slice(0, 160);
    d.lang = inferLanguage(d.name);
    renderDocuments();
    renderCode();
    updatePreview();
    scheduleSave();
  }
  function closeDoc(id = state.active) {
    const d = state.docs.find(d => d.id === id);
    if (d.text && !confirm(`Remove "${d.name}" from this workspace?\n\nDownload it first if you need a copy. This also removes the locally saved tab.`)) return;
    captureView();
    const index = state.docs.findIndex(d => d.id === id);
    state.docs.splice(index, 1);
    histories.delete(id);
    if (!state.docs.length) state.docs.push(makeDoc("untitled.txt"));
    if (state.active === id) state.active = state.docs[Math.min(index, state.docs.length - 1)].id;
    loadActive();
    scheduleSave();
    editor.focus();
  }

  // Lightweight, dependency-free tokenizers. These color text, not validate it.
  function tokenizer(lang) {
    const common = {
      javascript: [
        ["comment", /\/\/[^\n]*|\/\*[\s\S]*?(?:\*\/|$)/],
        ["string", /"(?:\\[\s\S]|[^"\\])*"|'(?:\\[\s\S]|[^'\\])*'|`(?:\\[\s\S]|[^`\\])*`/],
        ["keyword", /\b(?:async|await|break|case|catch|class|const|continue|debugger|default|delete|do|else|export|extends|false|finally|for|from|function|get|if|import|in|instanceof|let|new|null|of|return|set|static|super|switch|this|throw|true|try|typeof|undefined|var|void|while|yield|interface|type|enum|implements|private|public|readonly|as|declare|namespace|abstract|boolean|string|number|never|unknown|any)\b/],
        ["number", /\b(?:0[xX][\da-fA-F]+|0[bB][01]+|\d+(?:\.\d*)?(?:[eE][+-]?\d+)?n?)\b/],
        ["operator", /=>|[+\-*%=!<>|&?:~^]+/]
      ],
      python: [
        ["comment", /#[^\n]*/],
        ["string", /"""[\s\S]*?(?:"""|$)|'''[\s\S]*?(?:'''|$)|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'/],
        ["keyword", /\b(?:and|as|assert|async|await|break|class|continue|def|del|elif|else|except|False|finally|for|from|global|if|import|in|is|lambda|None|nonlocal|not|or|pass|raise|return|True|try|while|with|yield|self)\b/],
        ["number", /\b\d+(?:\.\d+)?\b/]
      ],
      json: [
        ["string", /"(?:\\.|[^"\\])*"/],
        ["keyword", /\b(?:true|false|null)\b/],
        ["number", /-?\b\d+(?:\.\d+)?(?:[eE][+-]?\d+)?\b/]
      ],
      css: [
        ["comment", /\/\*[\s\S]*?(?:\*\/|$)/],
        ["string", /"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'/],
        ["keyword", /@[a-z-]+|\b[a-z-]+(?=\s*:)/],
        ["number", /#[\da-fA-F]{3,8}\b|-?\b\d*\.?\d+(?:px|em|rem|vh|vw|s|ms|deg|%)?/],
        ["tag", /[.#][a-zA-Z_][\w-]*/]
      ],
      html: [
        ["comment", /<!--[\s\S]*?(?:-->|$)/],
        ["tag", /<\/?[a-zA-Z][^>]*>|<!DOCTYPE[^>]*>/],
        ["string", /&(?:#\d+|#x[\da-fA-F]+|\w+);/]
      ],
      markdown: [
        ["comment", /<!--[\s\S]*?(?:-->|$)/],
        ["string", /```[\s\S]*?(?:```|$)|`[^`\n]+`/],
        ["heading", /^#{1,6}[^\n]*|^\s*[-*>][^\n]*/],
        ["keyword", /\*\*[^*\n]+\*\*|__[^_\n]+__|\[[^\]]+\]\([^)]+\)/]
      ],
      sql: [
        ["comment", /--[^\n]*|\/\*[\s\S]*?(?:\*\/|$)/],
        ["string", /'(?:''|[^'])*'|"(?:\\.|[^"\\])*"/],
        ["keyword", /\b(?:SELECT|FROM|WHERE|AS|AND|OR|NOT|NULL|JOIN|LEFT|RIGHT|INNER|OUTER|ON|GROUP|BY|ORDER|ASC|DESC|HAVING|LIMIT|OFFSET|INSERT|INTO|VALUES|UPDATE|SET|DELETE|CREATE|TABLE|DROP|ALTER|INDEX|PRIMARY|KEY|DISTINCT|UNION|ALL|EXISTS|IN|LIKE|BETWEEN|CASE|WHEN|THEN|ELSE|END|COUNT|SUM|AVG|MAX|MIN|TRUE|FALSE)\b/],
        ["number", /\b\d+(?:\.\d+)?\b/]
      ],
      shell: [
        ["comment", /#[^\n]*/],
        ["string", /"(?:\\.|[^"\\])*"|'[^']*'/],
        ["keyword", /\b(?:if|then|else|elif|fi|for|while|do|done|case|esac|in|function|export|local|return|echo|exit|source|sudo)\b/],
        ["number", /\$\{?[\w@#?*!]+\}?|\b\d+\b/]
      ]
    };
    const rules = common[lang === "typescript" ? "javascript" : lang === "xml" ? "html" : lang];
    if (!rules) return null;
    return {
      regex: new RegExp(rules.map(([name, re]) => `(?<${name}>${re.source})`).join("|"), lang === "sql" ? "gmi" : "gm"),
      names: rules.map(r => r[0])
    };
  }

  function renderCode() {
    cancelAnimationFrame(renderFrame);
    const text = editor.value;
    const syntax = text.length <= HIGHLIGHT_LIMIT ? tokenizer(doc().lang) : null;
    const lines = [""];
    let matchPointer = 0;
    const decoratedMatches = matches.slice(0, 1500).filter(m => m.end > m.start);

    function appendChunk(value, cls, offset) {
      let p = 0;
      while (p < value.length) {
        const absolute = offset + p;
        while (matchPointer < decoratedMatches.length && decoratedMatches[matchPointer].end <= absolute) matchPointer++;
        const found = decoratedMatches[matchPointer];
        const hit = found && found.start <= absolute && absolute < found.end;
        let end = value.length;
        if (found) end = Math.min(end, (hit ? found.end : found.start) - offset);
        if (end <= p) end = p + 1;
        const parts = value.slice(p, end).split("\n");
        parts.forEach((part, i) => {
          if (i) lines.push("");
          if (!part) return;
          const classes = [cls ? "tok-" + cls : "", hit ? "search-hit" : ""].filter(Boolean).join(" ");
          lines[lines.length - 1] += classes
            ? `<span class="${classes}">${escapeHTML(part)}</span>`
            : escapeHTML(part);
        });
        p = end;
      }
    }

    let last = 0;
    if (syntax) {
      for (const m of text.matchAll(syntax.regex)) {
        if (m.index > last) appendChunk(text.slice(last, m.index), "", last);
        const cls = syntax.names.find(name => m.groups[name] !== undefined);
        appendChunk(m[0], cls, m.index);
        last = m.index + m[0].length;
      }
    }
    if (last < text.length) appendChunk(text.slice(last), "", last);
    highlight.innerHTML = lines.map(line => `<div class="code-line">${line || "&#8203;"}</div>`).join("");
    adjustHighlightWidth();
    updateGutter();
    syncScroll();
  }
  function requestRender() {
    cancelAnimationFrame(renderFrame);
    renderFrame = requestAnimationFrame(renderCode);
  }
  function adjustHighlightWidth() {
    if (state.settings.wrap) highlight.style.width = editor.clientWidth + "px";
    else {
      highlight.style.width = "";
      highlight.style.minWidth = editor.clientWidth + "px";
    }
  }
  function updateGutter() {
    if (!state.settings.lineNumbers) return;
    const rows = highlight.children;
    const current = editor.value.slice(0, editor.selectionStart).split("\n").length;
    let html = "";
    for (let i = 0; i < rows.length; i++) {
      const height = state.settings.wrap ? rows[i].offsetHeight : Math.round(state.settings.fontSize * 1.65);
      html += `<div class="line-number${i + 1 === current ? " current" : ""}" style="height:${height}px">${i + 1}</div>`;
    }
    $("lineNumbers").innerHTML = html;
  }
  function syncScroll() {
    highlight.style.transform = `translate(${-editor.scrollLeft}px, ${-editor.scrollTop}px)`;
    $("lineNumbers").style.transform = `translateY(${-editor.scrollTop}px)`;
  }
  function updateStatus() {
    const value = editor.value;
    const start = editor.selectionStart, end = editor.selectionEnd;
    const line = value.slice(0, start).split("\n").length;
    const col = start - value.lastIndexOf("\n", start - 1);
    $("cursorStatus").textContent = `Ln ${line}, Col ${col}` + (end > start ? ` · ${end - start} selected` : "");
    $("charCount").textContent = `${value.length.toLocaleString()} chars`;
    $("wordCount").textContent = `${(value.match(/\S+/g) || []).length.toLocaleString()} words`;
    $("undoBtn").disabled = !history().undo.length;
    $("redoBtn").disabled = !history().redo.length;
    const prev = $("lineNumbers").querySelector(".current");
    if (prev) prev.classList.remove("current");
    $("lineNumbers").children[line - 1]?.classList.add("current");
    if (!composition) doc().cursor = start;
  }

  // Per-document undo/redo, with typing grouped into short bursts.
  function recordUndo(before, kind = "command") {
    const h = history(), now = Date.now();
    const groupable = ["insertText", "deleteContentBackward", "deleteContentForward"].includes(kind);
    const merge = groupable && h.kind === kind && now - h.time < 650 &&
      before.start === before.end;
    if (!merge) {
      h.undo.push(before);
      if (h.undo.length > 150) h.undo.shift();
    }
    h.redo = [];
    h.kind = kind;
    h.time = now;
  }
  function changed() {
    doc().text = editor.value;
    doc().cursor = editor.selectionStart;
    updateSearch(false);
    requestRender();
    updateStatus();
    scheduleSave();
    clearTimeout(previewTimer);
    previewTimer = setTimeout(updatePreview, 250);
  }
  function editRange(start, end, value, selectStart, selectEnd) {
    const before = snapshot();
    editor.setRangeText(value, start, end, "end");
    if (selectStart !== undefined) editor.setSelectionRange(selectStart, selectEnd ?? selectStart);
    if (before.text !== editor.value) recordUndo(before);
    changed();
    editor.focus();
  }
  function replaceDocument(value) {
    editRange(0, editor.value.length, value, Math.min(editor.selectionStart, value.length));
  }
  function undo(redo = false) {
    const h = history(), source = redo ? h.redo : h.undo, target = redo ? h.undo : h.redo;
    if (!source.length) return;
    target.push(snapshot());
    const old = source.pop();
    h.kind = "";
    editor.value = old.text;
    editor.setSelectionRange(old.start, old.end);
    changed();
    editor.focus();
    revealCursor();
  }

  editor.addEventListener("beforeinput", e => {
    if (e.inputType === "historyUndo" || e.inputType === "historyRedo") {
      e.preventDefault();
      undo(e.inputType === "historyRedo");
      return;
    }
    beforeSnapshot = snapshot();
  });
  editor.addEventListener("input", e => {
    const before = beforeSnapshot || { text: doc().text, start: doc().cursor || 0, end: doc().cursor || 0 };
    recordUndo(before, e.inputType || "input");
    beforeSnapshot = null;
    changed();
  });
  editor.addEventListener("compositionstart", () => composition = true);
  editor.addEventListener("compositionend", () => { composition = false; changed(); });
  editor.addEventListener("scroll", syncScroll);
  editor.addEventListener("select", updateStatus);
  editor.addEventListener("keyup", updateStatus);
  editor.addEventListener("click", () => { history().kind = ""; updateStatus(); });

  function lineSelection() {
    const value = editor.value, s = editor.selectionStart, e = editor.selectionEnd;
    const start = value.lastIndexOf("\n", s - 1) + 1;
    const adjustedEnd = e > s && value[e - 1] === "\n" ? e - 1 : e;
    let end = value.indexOf("\n", adjustedEnd);
    if (end < 0) end = value.length;
    return { start, end, text: value.slice(start, end), s, e };
  }
  function indent(outdent = false) {
    const size = state.settings.tabSize, s = editor.selectionStart, e = editor.selectionEnd;
    if (s === e && !outdent) {
      const column = s - (editor.value.lastIndexOf("\n", s - 1) + 1);
      editRange(s, e, " ".repeat(size - column % size));
      return;
    }
    const block = lineSelection();
    const re = new RegExp(`^(?:\\t| {1,${size}})`);
    const transformed = block.text.split("\n").map(line =>
      outdent ? line.replace(re, "") : " ".repeat(size) + line).join("\n");
    if (s === e) {
      const delta = transformed.length - block.text.length;
      editRange(block.start, block.end, transformed, Math.max(block.start, s + delta));
    } else editRange(block.start, block.end, transformed, block.start, block.start + transformed.length);
  }
  function toggleComment() {
    const lang = doc().lang, block = lineSelection();
    if (lang === "json") return toast("JSON does not support comments.");
    if (["html", "xml", "markdown", "css"].includes(lang)) {
      const open = lang === "css" ? "/*" : "<!--";
      const close = lang === "css" ? "*/" : "-->";
      const trimmed = block.text.trim();
      const output = trimmed.startsWith(open) && trimmed.endsWith(close)
        ? trimmed.slice(open.length, -close.length).replace(/^ | $/g, "")
        : `${open} ${block.text} ${close}`;
      editRange(block.start, block.end, output, block.start, block.start + output.length);
      return;
    }
    const prefix = lang === "python" || lang === "shell" ? "#" : lang === "sql" ? "--" : "//";
    const rows = block.text.split("\n");
    const uncomment = rows.filter(l => l.trim()).every(l => l.trimStart().startsWith(prefix));
    const output = rows.map(line => {
      if (!line.trim()) return line;
      const spaces = line.match(/^\s*/)[0];
      const content = line.slice(spaces.length);
      return uncomment
        ? spaces + content.slice(prefix.length).replace(/^ /, "")
        : spaces + prefix + " " + content;
    }).join("\n");
    editRange(block.start, block.end, output, block.start, block.start + output.length);
  }
  function duplicateLine() {
    const b = lineSelection();
    editRange(b.end, b.end, "\n" + b.text, b.end + 1, b.end + 1 + b.text.length);
  }
  function moveLine(direction) {
    const b = lineSelection(), text = editor.value;
    if (direction < 0 && b.start > 0) {
      const previousStart = text.lastIndexOf("\n", b.start - 2) + 1;
      const previous = text.slice(previousStart, b.start - 1);
      editRange(previousStart, b.end, b.text + "\n" + previous, previousStart, previousStart + b.text.length);
    } else if (direction > 0 && b.end < text.length) {
      let nextEnd = text.indexOf("\n", b.end + 1);
      if (nextEnd < 0) nextEnd = text.length;
      const next = text.slice(b.end + 1, nextEnd);
      const start = b.start + next.length + 1;
      editRange(b.start, nextEnd, next + "\n" + b.text, start, start + b.text.length);
    }
  }

  editor.addEventListener("keydown", e => {
    if (composition || e.isComposing) return;
    const mod = e.ctrlKey || e.metaKey;
    const s = editor.selectionStart, end = editor.selectionEnd, value = editor.value;
    if (e.key === "Tab") { e.preventDefault(); indent(e.shiftKey); return; }
    if (mod && e.key === "/") { e.preventDefault(); toggleComment(); return; }
    if (mod && e.shiftKey && e.key.toLowerCase() === "d") { e.preventDefault(); duplicateLine(); return; }
    if (e.altKey && ["ArrowUp", "ArrowDown"].includes(e.key)) {
      e.preventDefault(); moveLine(e.key === "ArrowUp" ? -1 : 1); return;
    }
    if (e.key === "Enter" && !mod && !e.altKey) {
      e.preventDefault();
      const lineStart = value.lastIndexOf("\n", s - 1) + 1;
      const left = value.slice(lineStart, s);
      const base = left.match(/^[ \t]*/)[0];
      const extra = /[{[(]\s*$/.test(left) || (doc().lang === "python" && /:\s*$/.test(left));
      const indentation = base + (extra ? " ".repeat(state.settings.tabSize) : "");
      const right = value.slice(end);
