    if (state.settings.autoPairs && !mod && !e.altKey) {
      const pairs = { "(": ")", "[": "]", "{": "}", '"': '"', "'": "'", "`": "`" };
      if (s === end && [")", "]", "}", '"', "'", "`"].includes(e.key) && value[s] === e.key) {
        e.preventDefault(); editor.setSelectionRange(s + 1, s + 1); updateStatus(); return;
      }
      if (pairs[e.key]) {
        if ((e.key === "'" || e.key === '"') && /[\w]/.test(value[s - 1] || "") && s === end) return;
        e.preventDefault();
        editRange(s, end, e.key + value.slice(s, end) + pairs[e.key], s + 1, end + 1);
        return;
      }
      if (e.key === "Backspace" && s === end && s > 0 && pairs[value[s - 1]] === value[s]) {
