  // Find and replace. RegExp construction errors are displayed inline.
  function buildSearchRegex() {
    const term = $("findInput").value;
    if (!term) return null;
    let source = searchOptions.regex ? term : term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    if (searchOptions.word) source = "\\b(?:" + source + ")\\b";
    return new RegExp(source, "gm" + (searchOptions.case ? "" : "i"));
  }
  function updateSearch(render = true) {
    matches = [];
