    $("findError").textContent = "";
    if (!$("findbar").hidden) {
      try {
        const regex = buildSearchRegex();
        if (regex) {
          let m;
          while ((m = regex.exec(editor.value)) && matches.length < 20000) {
            matches.push({ start: m.index, end: m.index + m[0].length });
            if (!m[0].length) regex.lastIndex++;
          }
        }
      } catch (error) { $("findError").textContent = error.message; }
    }
    currentMatch = matches.findIndex(m => m.start === editor.selectionStart && m.end === editor.selectionEnd);
    updateMatchCount();
    if (render) requestRender();
  }
  function updateMatchCount() {
    $("matchCount").textContent = matches.length
