      : "No results";
  }
  function revealCursor() {
    const line = editor.value.slice(0, editor.selectionStart).split("\n").length - 1;
    const row = highlight.children[line];
    const y = row ? row.offsetTop : line * Math.round(state.settings.fontSize * 1.65) + 18;
    if (y < editor.scrollTop || y > editor.scrollTop + editor.clientHeight - 45)
      editor.scrollTop = Math.max(0, y - editor.clientHeight / 2);
    if (!state.settings.wrap) {
      const prefix = editor.value.slice(editor.value.lastIndexOf("\n", editor.selectionStart - 1) + 1, editor.selectionStart);
      const canvas = revealCursor.canvas || (revealCursor.canvas = document.createElement("canvas"));
      const ctx = canvas.getContext("2d");
      ctx.font = getComputedStyle(editor).font;
      const x = ctx.measureText(prefix.replace(/\t/g, " ".repeat(state.settings.tabSize))).width + 18;
      if (x < editor.scrollLeft || x > editor.scrollLeft + editor.clientWidth - 35)
        editor.scrollLeft = Math.max(0, x - editor.clientWidth / 2);
