  function findNext(direction = 1) {
    if (!matches.length) return;
    if (currentMatch < 0) {
      const pos = editor.selectionStart;
      currentMatch = direction > 0
        ? matches.findIndex(m => m.start >= pos)
        : matches.findLastIndex(m => m.start <= pos);
      if (currentMatch < 0) currentMatch = direction > 0 ? 0 : matches.length - 1;
    } else currentMatch = (currentMatch + direction + matches.length) % matches.length;
    const m = matches[currentMatch];
    editor.focus();
    editor.setSelectionRange(m.start, m.end);
    revealCursor();
    updateStatus();
    updateMatchCount();
  }
  function toggleFind(force) {
    const open = force ?? $("findbar").hidden;
    $("findbar").hidden = !open;
