  function replacementFor(match) {
    if (!searchOptions.regex) return $("replaceInput").value;
    const regex = buildSearchRegex();
    regex.lastIndex = match.start;
    const m = regex.exec(editor.value);
    if (!m || m.index !== match.start) return $("replaceInput").value;
    const text = editor.value;
    return $("replaceInput").value.replace(/\$(\$|&|`|'|<[^>]+>|\d{1,2})/g, (whole, key) => {
      if (key === "$") return "$";
      if (key === "&") return m[0];
      if (key === "`") return text.slice(0, m.index);
      if (key === "'") return text.slice(m.index + m[0].length);
      if (key.startsWith("<")) return m.groups ? (m.groups[key.slice(1, -1)] ?? "") : whole;
      const n = +key;
      if (n > 0 && n < m.length) return m[n] ?? "";
