  // Safe Markdown subset; raw HTML is escaped. HTML preview uses a sandbox.
  function inlineMarkdown(text) {
    return escapeHTML(text)
      .replace(/`([^`]+)`/g, "<code>$1</code>")
      .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
      .replace(/__([^_]+)__/g, "<strong>$1</strong>")
      .replace(/~~([^~]+)~~/g, "<del>$1</del>")
      .replace(/\*([^*\n]+)\*/g, "<em>$1</em>");
  }
  function markdown(text) {
    const result = [];
    let fenced = false, code = [], list = "";
    const closeList = () => { if (list) { result.push(`</${list}>`); list = ""; } };
    for (const line of text.split("\n")) {
      if (/^\s*```/.test(line)) {
        closeList();
        if (fenced) { result.push("<pre><code>" + escapeHTML(code.join("\n")) + "</code></pre>"); code = []; }
        fenced = !fenced;
        continue;
      }
      if (fenced) { code.push(line); continue; }
      const item = line.match(/^\s*(?:([-+*])|\d+\.)\s+(.*)$/);
      if (item) {
        const type = item[1] ? "ul" : "ol";
        if (list !== type) { closeList(); result.push(`<${type}>`); list = type; }
        let content = item[2];
        if (/^\[[ xX]\]\s/.test(content)) {
          const checked = /^\[[xX]\]/.test(content);
          result.push(`<li style="list-style:none">${checked ? "☑" : "☐"} ${inlineMarkdown(content.slice(4))}</li>`);
        } else result.push("<li>" + inlineMarkdown(content) + "</li>");
        continue;
      }
      closeList();
      const heading = line.match(/^(#{1,6})\s+(.*)$/);
      if (heading) result.push(`<h${heading[1].length}>${inlineMarkdown(heading[2])}</h${heading[1].length}>`);
      else if (/^\s*([-*_])(?:\s*\1){2,}\s*$/.test(line)) result.push("<hr>");
      else if (/^>\s?/.test(line)) result.push("<blockquote>" + inlineMarkdown(line.replace(/^>\s?/, "")) + "</blockquote>");
      else if (!line.trim()) result.push('<div style="height:8px"></div>');
      else result.push("<p>" + inlineMarkdown(line) + "</p>");
    }
    closeList();
    if (fenced) result.push("<pre><code>" + escapeHTML(code.join("\n")) + "</code></pre>");
    return result.join("\n");
  }
  function updatePreview() {
    if ($("previewPane").hidden) return;
