      return;
    }
    const dark = state.settings.theme !== "light";
    const body = d.lang === "markdown" ? markdown(d.text) : "<pre><code>" + escapeHTML(d.text) + "</code></pre>";
    $("previewFrame").srcdoc = `<!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
      <style>
      *{box-sizing:border-box}body{margin:0;padding:28px;font:15px/1.75 system-ui,sans-serif;
      background:${dark ? "#161822" : "#fff"};color:${dark ? "#dce0ef" : "#303448"};overflow-wrap:anywhere}
      h1,h2,h3{line-height:1.3;letter-spacing:-.5px}h1{font-size:30px}h2{font-size:24px}
      p{margin:5px 0}pre{padding:16px;border-radius:9px;overflow:auto;white-space:pre-wrap;background:${dark ? "#222536" : "#f1f2f8"}}
      code{font:13px/1.7 ui-monospace,monospace;background:${dark ? "#222536" : "#f1f2f8"};padding:2px 4px;border-radius:4px}
      pre code{padding:0}blockquote{margin:12px 0;padding:8px 16px;border-left:3px solid #a395ff;color:${dark ? "#a8b0cc" : "#70768a"}}
      hr{border:0;border-top:1px solid ${dark ? "#34384c" : "#e1e3ef"};margin:22px 0}li{margin:4px 0}
      </style></head><body>${body}</body></html>`;
