  async function importFiles(files) {
    for (const file of Array.from(files)) {
      if (file.size > MAX_FILE) { toast(`${file.name}: maximum import size is 3 MB.`); continue; }
      try {
        const text = normalize(await file.text());
        if (file.name.endsWith(".notebox.json")) {
          const data = JSON.parse(text);
          const docs = sanitizeDocs(data.docs);
          if (!docs.length) throw new Error("No documents found");
          if (!confirm(`Import ${docs.length} documents into this workspace?\nExisting documents will be kept.`)) continue;
          captureView();
          state.docs.push(...docs);
          state.active = docs[0].id;
          loadActive();
          scheduleSave();
          toast("Workspace imported. Existing tabs were kept.");
        } else {
          if (text.includes("\0")) { toast(`${file.name} appears to be a binary file.`); continue; }
