#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    string a, b;
    cin >> n >> m >> a >> b;

    int k = count(b.begin(), b.end(), '#');
    int t = 0;  // 已执行的操作次数

    for (char &ch : a) {
        if (ch != '#') continue;

        // 到下一个 'a' 需要跳过多少次操作
        int d = (26 - t % 26) % 26;

        if (d <= k) {
            t += d;
            k -= d;
        }

        ch = char('a' + t % 26);
        ++t;
    }

    // 剩余操作全部分配给 b，不影响答案
    cout << a << '\n';
    return 0;
}
