Dưới đây là chương trình **C** cài đặt thuật toán Euclide mở rộng theo các bước bạn đưa ra, với đầu vào `a, b` là hai số nguyên không âm.

Thuật toán trả về `d, x, y` sao cho:
\[
d = \gcd(a,b), \qquad ax + by = d.
\]

```c
#include <stdio.h>

void euclidMoRong(long long a, long long b,
                 long long *d, long long *x, long long *y) {
    // (1) Truong hop b = 0
    if (b == 0) {
        *d = a;
        *x = 1;
        *y = 0;
        return;
    }

    // (2) Khoi tao
    long long x2 = 1, x1 = 0;
    long long y2 = 0, y1 = 1;

    // (3) Lap khi b > 0
    while (b > 0) {
        // (3.1) Tinh thuong, so du va he so moi
        long long q = a / b;
        long long r = a - q * b;
        long long xMoi = x2 - q * x1;
        long long yMoi = y2 - q * y1;

        // (3.2) Cap nhat
        a = b;
        b = r;
        x2 = x1;
        x1 = xMoi;
        y2 = y1;
        y1 = yMoi;
    }

    // (4) Tra ket qua thong qua con tro
    *d = a;
    *x = x2;
    *y = y2;
}

int main(void) {
    long long a, b;
    long long d, x, y;

    printf("Nhap hai so nguyen khong am a, b: ");
    if (scanf("%lld %lld", &a, &b) != 2 || a < 0 || b < 0) {
        printf("Du lieu khong hop le!\n");
        return 1;
    }

    if (a == 0 && b == 0) {
        printf("Vui long nhap it nhat mot so khac 0.\n");
        return 1;
    }

    euclidMoRong(a, b, &d, &x, &y);

    printf("UCLN(%lld, %lld) = %lld\n", a, b, d);
    printf("x = %lld, y = %lld\n", x, y);
    printf("%lld * (%lld) + %lld * (%lld) = %lld\n",
           a, x, b, y, d);

    return 0;
}
```

