%% 定义全局变量
global DH_params target_pos joint_inertia joint_avg_speed;

% DH参数：[a(mm), alpha(deg), d(mm), theta_min(deg), theta_max(deg)]
DH_params = [
    300, -90, 600, -160, 160;
    1200,  0,   0, -150,  15;
    300, -90,   0, -200,  80;
    0,   -90, 1200, -180, 180;
    0,   -90,   0, -120, 120;
    0,     0,   0, -180, 180
];

target_pos = [1500; 1200; 200];           % 目标位置，mm
joint_inertia = [0.5, 0.3, 0.4, 0.6, 0.2, 0.4];
joint_avg_speed = [2.0, 1.5, 1.0, 2.5, 3.0, 2.0];

% 固定随机种子便于复现。
% 每次循环随机状态继续变化，不会重复使用同一初始种群。
rng(1, 'twister');

%% 优化设置
constraintTolerance = 1e-6;

opts = optimoptions('gamultiobj', ...
    'PopulationSize', 1000, ...
    'MaxGenerations', 100, ...
    'ConstraintTolerance', constraintTolerance, ...
    'PlotFcn', @gaplotpareto, ...
    'Display', 'iter');

lb = deg2rad(DH_params(:, 4)).';
ub = deg2rad(DH_params(:, 5)).';

%% 多次运行
numStarts = 5;

bestSolutions = cell(numStarts, 1);
bestFvals = cell(numStarts, 1);

for runIdx = 1:numStarts
    fprintf('\n========== 第 %d / %d 次运行 ==========\n', ...
        runIdx, numStarts);

    [x, fval, exitflag] = gamultiobj( ...
        @objective_function, ...
        6, [], [], [], [], ...
        lb, ub, ...
        @constraint_function, ...
        opts);

    % 防止空结果导致后续索引报错
    if isempty(x) || isempty(fval)
        warning('第 %d 次运行没有返回候选解。', runIdx);
        continue;
    end

    if exitflag <= 0
        warning(['第 %d 次运行未正常收敛，exitflag = %d。' ...
                 '仍检查并保留返回的可行候选解。'], ...
                 runIdx, exitflag);
    end

    % 检查有限值、位置误差约束和关节上下界
    finiteMask = all(isfinite(x), 2) & all(isfinite(fval), 2);

    errorMask = fval(:, 1) <= 200 + constraintTolerance;

    lowerMask = all(bsxfun(@ge, x, lb - constraintTolerance), 2);
    upperMask = all(bsxfun(@le, x, ub + constraintTolerance), 2);

    validMask = finiteMask & errorMask & lowerMask & upperMask;

    x = x(validMask, :);
    fval = fval(validMask, :);

    if isempty(x)
        warning('第 %d 次运行没有满足约束的候选解。', runIdx);
        continue;
    end

    % 存储本次有效结果
    bestSolutions{runIdx} = x;
    bestFvals{runIdx} = fval;

    % 可视化并显示代表性解
    visualize_results(fval, runIdx);
    disp_results(x, fval);
end

