%% ==================== 局部函数 ====================

% 目标函数：最小化末端位置误差和能量代理指标
function f = objective_function(theta)
    global target_pos joint_inertia joint_avg_speed;

    % 统一为行向量，避免行列方向不一致导致隐式扩展
    theta = theta(:).';

    [endPos, ~] = forward_kinematics(theta);

    % 第一目标：末端位置误差，mm
    positionError = norm(endPos - target_pos);

    % 第二目标中的重力项：
    % 简化为末端有一个5 kg的集中质量，z轴正方向向上。
    % 这里只考虑该集中质量，不包含各连杆的重力势能。
    mass = 5;
    g = 9.81;

    height_m = endPos(3) / 1000;
    gravitationalPotential = mass * g * height_m;

    % 保留原来的关节代理项。
    % 注意：它不是严格的电机能耗或标准转动动能公式。
    jointIndex = sum( ...
        joint_inertia .* (joint_avg_speed .* theta).^2);

    energyIndex = jointIndex + gravitationalPotential;

    f = [positionError, energyIndex];
end


% 非线性约束：末端位置误差不超过200 mm
function [c, ceq] = constraint_function(theta)
    global target_pos;

    [endPos, ~] = forward_kinematics(theta);

    % gamultiobj要求 c <= 0
    c = norm(endPos - target_pos) - 200;
    ceq = [];
end


% 正向运动学：采用标准DH变换
function [endPos, T] = forward_kinematics(theta)
    global DH_params;

    theta = theta(:);
    numJoints = size(DH_params, 1);

    if numel(theta) ~= numJoints
        error('关节角数量必须与DH参数行数一致。');
    end

    T = eye(4);

    for jointIdx = 1:numJoints
        T = T * dh_matrix( ...
            DH_params(jointIdx, :), theta(jointIdx));
    end

    endPos = T(1:3, 4);
end


% 标准DH矩阵
function T = dh_matrix(params, theta)
    a = params(1);
    alpha = deg2rad(params(2));
    d = params(3);

    ct = cos(theta);
    st = sin(theta);
    ca = cos(alpha);
    sa = sin(alpha);

    T = [
        ct, -st * ca,  st * sa, a * ct;
        st,  ct * ca, -ct * sa, a * st;
        0,        sa,       ca,      d;
        0,         0,        0,      1
    ];
end


% 可视化本次运行返回的可行解
function visualize_results(fval, runIdx)
    if isempty(fval)
        return;
    end

    figure( ...
        'Name', sprintf('Pareto候选解 - 第%d次运行', runIdx), ...
        'NumberTitle', 'off');

    scatter(fval(:, 1), fval(:, 2), 30, 'filled');

    xlabel('末端位置误差（mm）');
    ylabel('能量指标（代理目标）');
    title(sprintf('第 %d 次运行：Pareto候选解', runIdx));

    grid on;
end


% 显示代表性解
function disp_results(x, fval)
    if isempty(x) || isempty(fval)
        return;
    end

    [~, minErrorIdx] = min(fval(:, 1));
    [~, minEnergyIdx] = min(fval(:, 2));
    [~, maxEnergyIdx] = max(fval(:, 2));

    % 均衡点：
    % 将两个目标分别归一化到[0,1]，
    % 选择到归一化理想点[0,0]距离最近的候选解。
    fMin = min(fval, [], 1);
    fMax = max(fval, [], 1);

    fRange = fMax - fMin;

    % 某一目标在所有候选解中相同时，防止除零
    fRange(fRange == 0) = 1;

    normalizedF = bsxfun(@rdivide, ...
        bsxfun(@minus, fval, fMin), fRange);

    distanceSquared = sum(normalizedF.^2, 2);
    [~, balancedIdx] = min(distanceSquared);

    % 每个点的角度和目标值都使用同一个索引
    print_solution('最高能量指标点', ...
        x(maxEnergyIdx, :), fval(maxEnergyIdx, :));

    print_solution('最低能量指标点', ...
        x(minEnergyIdx, :), fval(minEnergyIdx, :));

    print_solution('最低误差点', ...
        x(minErrorIdx, :), fval(minErrorIdx, :));

    print_solution('均衡点（归一化后等权选择）', ...
        x(balancedIdx, :), fval(balancedIdx, :));
end


% 统一输出函数，避免复制代码时混用索引
function print_solution(label, theta, fval)
    fprintf('\n%s - 关节角度（度）：\n', label);

    disp(array2table(rad2deg(theta(:).'), ...
        'VariableNames', ...
        {'Joint1', 'Joint2', 'Joint3', ...
         'Joint4', 'Joint5', 'Joint6'}));

    fprintf('%s - 目标函数值：\n', label);

    disp(array2table(fval(:).', ...
        'VariableNames', ...
        {'EndEffectorError_mm', 'EnergyIndex'}));
end
