```python
import sys


def maxEnergy(ener):
    if len(ener) < 2:
        return 0

    largest = second_largest = float('-inf')
    smallest = second_smallest = float('inf')

    for energy in ener:
        if energy >= largest:
            second_largest = largest
            largest = energy
        elif energy > second_largest:
            second_largest = energy

        if energy <= smallest:
            second_smallest = smallest
            smallest = energy
        elif energy < second_smallest:
            second_smallest = energy

    if smallest * second_smallest > largest * second_largest:
        return smallest + second_smallest

    return largest + second_largest


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    numOfChem = int(data[0])
    ener = [int(data[i]) for i in range(1, numOfChem + 1)]
    print(maxEnergy(ener))


if __name__ == "__main__":
    main()
