B = steadyPoints(end, :);
v = B - A;

% 绘制足够长的基线，使延长线上的投影也能显示
tRange = [min(0, t) - 0.15, max(1, t) + 0.15];
linePoints = [
    A + tRange(1) * v;
    A + tRange(2) * v
];

figure('Color', 'w');
hold on;
grid on;
axis equal;

h1 = plot(steadyPoints(:, 1), steadyPoints(:, 2), ...
    'bo', 'MarkerSize', 8, 'MarkerFaceColor', 'b');

h2 = plot(linePoints(:, 1), linePoints(:, 2), ...
    'k--', 'LineWidth', 1.2);

h3 = plot([A(1), B(1)], [A(2), B(2)], ...
    'k-', 'LineWidth', 2);

h4 = plot(queryPoint(1), queryPoint(2), ...
    'rp', 'MarkerSize', 14, 'MarkerFaceColor', 'r');

h5 = plot(targetPoint(1), targetPoint(2), ...
    'gs', 'MarkerSize', 10, 'MarkerFaceColor', 'g');

h6 = plot([queryPoint(1), targetPoint(1)], ...
          [queryPoint(2), targetPoint(2)], ...
          'r--', 'LineWidth', 1.5);

for i = 1:size(steadyPoints, 1)
    text(steadyPoints(i, 1), steadyPoints(i, 2), ...
        sprintf('  P%d', i), 'VerticalAlignment', 'bottom');
end

xlabel('X');
ylabel('Y');
title('基于基线投影的稳态点调度');

legend([h1, h2, h3, h4, h5, h6], ...
    {'已知稳态点', '基线所在直线', '基线线段', ...
     '待估计点', '目标稳态点', '待估计点与目标点连线'}, ...
    'Location', 'best');

hold off;

%% 局部函数
function [targetPoint, t] = steadySchedule( ...
    steadyPoints, queryPoint, limitToSegment)
%STEADYSCHEDULE 根据首尾稳态点构成的基线进行投影调度
%
% 输入：
%   steadyPoints   - N×2 实数矩阵，每行表示一个稳态点 [x, y]
%   queryPoint     - 1×2 实数向量，表示待估计点 [x, y]
%   limitToSegment - 是否将目标点限制在首尾点之间，默认 false
%
% 输出：
%   targetPoint    - 1×2 向量，表示计算得到的目标稳态点
%   t              - 基线位置参数；启用限制时为截断后的参数

    if nargin < 3
        limitToSegment = false;
    end

    % 输入检查
    validateattributes(steadyPoints, {'numeric'}, ...
        {'real', 'finite', '2d', 'nonempty'});

    validateattributes(queryPoint, {'numeric'}, ...
        {'real', 'finite', 'size', [1, 2]});

    validateattributes(limitToSegment, {'logical'}, {'scalar'});

    if size(steadyPoints, 2) ~= 2 || size(steadyPoints, 1) < 2
        error('steadyPoints 必须为 N×2 矩阵，且 N >= 2。');
    end

    % 转为浮点数，避免整数类型参与投影运算
    steadyPoints = double(steadyPoints);
    queryPoint = double(queryPoint);

    % 第一个和最后一个稳态点
    A = steadyPoints(1, :);
    B = steadyPoints(end, :);

    % 基线向量及其长度平方
    v = B - A;
    lengthSquared = dot(v, v);

    if lengthSquared == 0
        error('第一个和最后一个稳态点重合，无法确定基线方向。');
    end

    % 正交投影参数
    t = dot(queryPoint - A, v) / lengthSquared;

    % 可选：限制在基线线段范围内
    if limitToSegment
        t = max(0, min(1, t));
    end

    % 目标稳态点
    targetPoint = A + t * v;
end
```

上述示例的投影结果为：

```text
待估计点：      (4.0000, 6.0000)
目标稳态点：    (5.4400, 4.0800)
基线位置参数 t：0.6800
```

**需要区分两种结果：**

1. `targetPoint` 是基线上的连续调度结果，不一定属于原有的 \(N\) 个稳态点。
2. 若只能选择已有稳态点，则可使用代码中的 `nearestIndex`。这是在投影后额外进行的一次离散选择。

按照所描述的简化方法，中间的 \(N-2\) 个稳态点不参与基线投影计算；若这些点明显偏离基线，投影结果只是该简化模型下的估计。

可以做到 **\(O(n)\) 时间复杂度**。关键是：**不实际拼接两个数，只计算拼接结果对 \(36\) 的余数，而且只需区分右边的数是一位数还是多位数。**

## 1. 把拼接转换成取模

设左边的数为 \(x\)，右边的数为 \(y\)，\(y\) 有 \(k\) 位，那么拼接结果是：

\[
b=x\cdot 10^k+y
\]

要求：

\[
(x\cdot 10^k+y)\bmod 36=0
\]

直接计算可能溢出，但只计算余数就不会。

注意这里统计的是**有序下标对**：\((i,j)\) 和 \((j,i)\) 是不同方案，且 \(i\ne j\)。数组中数值相同的不同元素也需要分别统计。

## 2. 关键性质：位数只需要分成两类

观察 \(10^k\bmod36\)：

\[
10^1\bmod36=10
\]

\[
10^2\bmod36=28
\]

而：

\[
28\cdot10\bmod36=28
\]

因此：

\[
10^k\bmod36=
\begin{cases}
10,&k=1\\
28,&k\ge2
\end{cases}
\]

所以右边的数无论是两位还是十九位，都可以统一处理！

## 3. 用计数数组统计

定义：

- `cnt[0][r]`：数组中，**一位数**且模 \(36\) 余数为 \(r\) 的元素个数。
- `cnt[1][r]`：数组中，**至少两位数**且模 \(36\) 余数为 \(r\) 的元素个数。

先遍历一次数组，统计这些数量。

然后枚举作为左边的数 \(x\)，令：

\[
r=x\bmod36
\]

### 右边是一位数

需要：

\[
(10r+y)\bmod36=0
\]

所以右边的数的余数必须是：

\[
t_1=(36-(10r\bmod36))\bmod36
\]

方案数直接加上：

```cpp
cnt[0][t1]
```

### 右边至少两位

同理，所需余数为：

\[
t_2=(36-(28r\bmod36))\bmod36
\]

方案数加上：

```cpp
cnt[1][t2]
```

### 排除自己和自己拼接

计数数组中包含当前元素自己，因此如果 \(x\) 和自己拼接也能被 \(36\) 整除，就要减去这一种非法方案。

只减去当前下标对应的一个元素，不能排除其他数值相同的元素。

## 4. C++ 代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> a(n);
    long long cnt[2][36] = {};

    for (int i = 0; i < n; ++i) {
        cin >> a[i];

        int type = (a[i] < 10 ? 0 : 1);
        int r = a[i] % 36;

        ++cnt[type][r];
    }

    long long ans = 0;

    for (long long x : a) {
        int r = x % 36;

        // 右边是一位数
        int t1 = (36 - r * 10 % 36) % 36;
        ans += cnt[0][t1];

        // 右边至少两位
        int t2 = (36 - r * 28 % 36) % 36;
        ans += cnt[1][t2];

        // 排除使用同一个数组元素两次的情况
        int factor = (x < 10 ? 10 : 28);
        if ((r * factor + r) % 36 == 0) {
            --ans;
        }
    }

    cout << ans << '\n';
    return 0;
}
```

## 5. 复杂度和数据范围

- **时间复杂度：\(O(n)\)**，只遍历数组两次。
- **空间复杂度：\(O(n)\)**，用于保存数组；计数表仅有 \(72\) 个位置。
- \(a_i\le10^{18}\)，可以用 `long long` 保存。
- 答案最多为：

\[
n(n-1)\le 10^5(10^5-1)=9\,999\,900\,000
\]

因此答案也必须用 `long long`。

整个算法不生成拼接后的大整数，所以不会出现拼接结果溢出的问题。

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n;
        string s;
        cin >> n >> s;

        long long answer = n / 2;

        for (int i = 1; i < n; i += 2) {
            if (s[i] == '(') answer += 2;
        }

        cout << answer << '\n';
    }

    return 0;
}
```

### Why this works

Let `balance[i]` be the number of unmatched opening brackets after position `i`. The cost equals the sum of all prefix balances: a matched pair `(l, r)` contributes `1` to each balance from `l` through `r - 1`, totaling `r - l`.

For any valid restoration:
- At every **odd position**, the balance is odd and nonnegative, so it is at least `1`.
- At an **even position containing `(`**, the balance is at least `2`.
- At an **even position containing `)`**, the balance is at least `0`.

These minimum balances can all be achieved:
- At an odd position, insert `(` if the current balance is `0`; otherwise insert `)`.
- This keeps the balance after every odd position at `1`, and after every even position at either `0` or `2`.

The last character must be `)` because a valid restoration is guaranteed, so the resulting sequence also ends with balance `0`.

Therefore:

\[
\text{minimum cost} = \frac{n}{2} + 2 \times \text{number of fixed opening brackets}.
\]

**Complexity:** `O(n)` time per test case and `O(1)` extra space beyond the input string.

